Object.assign(window.TEM8_DICTIONARY, {"tax":{"media":{"uk":"media/uk/tax__gb_1.mp3","us":"media/us/tax__us_1.mp3"},"oxford":{"phon":"tæks","pos":"noun","senses":[{"en":"money that you have to pay to the government so that it can pay for public services. People pay tax according to their income and businesses pay tax according to their profits. Tax is also often paid on goods and services.","cn":"税；税款","ex":{"en":"to pay your taxes","cn":"交税"}},{"en":"to put a tax on somebody/something; to make somebody pay tax","cn":"对…征税；课税；使纳税","ex":{"en":"His declared aim was to tax the rich.","cn":"他宣布他的目的是向富人征税。"},"pos":"verb"},{"en":"to pay tax on a vehicle so that you may use it on the roads","cn":"缴纳车辆牌照税","lab":"British English","ex":{"en":"The car is taxed until July.","cn":"这辆汽车的牌照税缴纳到了七月。"},"pos":"verb"},{"en":"to need a great amount of physical or mental effort","cn":"使负重担；使受压力；使大伤脑筋","ex":{"en":"The questions did not tax me.","cn":"那些问题没有让我费脑筋。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"税;税款","en":"Tax is an amount of money that you have to pay to the government so that it can pay for public services.","ex":{"en":"No-one enjoys paying tax","cn":"没人喜欢纳税。"}},{"pos":"VERB 动词","cn":"对(人、公司或货物)征税","en":"When a person or company is taxed, they have to pay a part of their income or profits to the government. When goods are taxed, a percentage of their price has to be paid to the government.","ex":{"en":"Husband and wife are now taxed separately on their incomes","cn":"现在夫妻双方分别按各自的收入纳税。"}},{"pos":"VERB 动词","cn":"使用尽，耗尽(力气、耐心、资源等)","en":"If something taxes your strength, your patience, or your resources, it uses nearly all of them, so that you have great difficulty in carrying out what you are trying to do.","ex":{"en":"Overcrowding has taxed the city's ability to deal with waste","cn":"人口过多使得城市的垃圾处理能力达到了极限。"}}]},"examples":[{"en":"Any interest payments are taxed as part of your income.","cn":"利息所得作为你收入的一部分要予以征税。"},{"en":"The problem is currently taxing the brains of the nation's experts (= making them think very hard).","cn":"目前这个问题使得全国的专家大伤脑筋。"}]},"taxation":{"media":{"uk":"media/uk/taxation__gb_1.mp3","us":"media/us/taxation__us_1.mp3"},"oxford":{"phon":"tækˈseɪʃn","pos":"noun","senses":[{"en":"money that has to be paid as taxes","cn":"税；税款；税金；税收","ex":{"en":"to reduce taxation","cn":"减税"}},{"en":"the system of collecting money by taxes","cn":"税制；征税；课税","ex":{"en":"changes in the taxation structure","cn":"税制结构的变化"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"征税;课税;税制","en":"Taxation is the system by which a government takes money from people and spends it on things such as education, health, and defence."},{"pos":"N-UNCOUNT 不可数名词","cn":"税;税额;税款","en":"Taxation is the amount of money that people have to pay in taxes.","ex":{"en":"The result will be higher taxation.","cn":"结果将是征收更高的税。"}}]},"examples":[{"en":"changes in the taxation structure","cn":"税制结构的变化"},{"en":"to reduce taxation","cn":"减税"}]},"taboo":{"oxford":{"phon":"təˈbuː","pos":"adjective","senses":[{"en":"considered so offensive or embarrassing that people must not mention it","cn":"禁忌：被认为是令人反感或令人尴尬的，人们不得提及","ex":{"en":"in the days when sex was a taboo subject","cn":"在谈性色变的年代"}},{"en":"a cultural or religious custom that does not allow people to do, use or talk about a particular thing","cn":"（文化或宗教习俗方面的）禁忌，忌讳，戒律","ex":{"en":"an incest taboo","cn":"乱伦禁忌"},"pos":"noun"},{"en":"a general agreement not to do something or talk about something","cn":"禁止；避讳","ex":{"en":"The subject is still a taboo in our family.","cn":"我们家仍然很避讳谈论这件事。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"禁忌;忌讳","en":"If there is a taboo on a subject or activity, it is a social custom to avoid doing that activity or talking about that subject, because people find them embarrassing or offensive.","ex":{"en":"The topic of addiction remains something of a taboo","cn":"毒瘾仍然是个有些忌讳的话题。"}}]},"media":{"uk":"media/uk/taboo__gb_1.mp3","us":"media/us/taboo__us_1.mp3"},"examples":[{"en":"Death is one of the great taboos in our culture.","cn":"在我们的文化中，“死亡”是一大忌。"},{"en":"The subject is still a taboo in our family.","cn":"这个话题在我们家里仍然讳莫如深。"}]},"tarpaulin":{"media":{"uk":"media/uk/tarpaulin__gb_1.mp3","us":"media/us/tarpaulin__us_1.mp3"},"oxford":{"phon":"tɑːˈpɔːlɪn","pos":"noun","senses":[{"en":"a large sheet made of heavy waterproof material, used to cover things with and to keep rain off","cn":"柏油帆布；（防水）油布","ex":{"en":"The car was covered with a black tarpaulin.","cn":"那辆车用黑色的油布盖着。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"防水帆布;油布","en":"Tarpaulin is a fabric made of canvas or similar material coated with tar, wax, paint, or some other waterproof substance.","ex":{"en":"...a piece of tarpaulin.","cn":"一块油布"}},{"pos":"N-COUNT 可数名词","cn":"(一块)防水帆布，油布","en":"A tarpaulin is a sheet of heavy waterproof material that is used as a protective cover."}]}},"tailor-made":{"oxford":{"phon":"ˌteɪlə ˈmeɪd","pos":"adjective","senses":[{"en":"made for a particular person or purpose, and therefore very suitable","cn":"特制的；专门设置的；非常合适的","ex":{"en":"a tailor-made course of study","cn":"专门设置的课程"}},{"en":"made by a tailor for a particular person","cn":"定做的","ex":{"en":"a tailor-made suit","cn":"定做的西服"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"专门制作的;定制的;特制的","en":"If something is tailor-made, it has been specially designed for a particular person or purpose.","ex":{"en":"...tailor-made itineraries for tourists seeking something more individual than packaged holidays","cn":"为那些不喜欢包办旅行、寻求个性的游客们专门安排的游览路线"}},{"pos":"ADJ 形容词","cn":"极其适合的;恰到好处的","en":"If you say that someone or something is tailor-made for a particular task, purpose, or need, you are emphasizing that they are perfectly suitable for it.","ex":{"en":"He was tailor-made, it was said, for the task ahead","cn":"据说他是前头面临任务的最佳人选。"}},{"pos":"ADJ 形容词","cn":"(衣服)量身定做的，量体裁成的","en":"Tailor-made clothes have been specially made to fit a particular person.","ex":{"en":"He was wearing a tweed suit that looked tailor-made.","cn":"他身穿一套粗花呢西服，看上去像是量身定做的。"}}]},"media":{"uk":"media/uk/tailor_made_1_gb_1.mp3","us":"media/us/tailor_made_1_us_1.mp3"},"examples":[{"en":"She seems tailor-made for the job (= perfectly suited for it).","cn":"她似乎生来就是为了专门做这项工作的。"},{"en":"a trip tailor-made just for you","cn":"专门为你安排的旅行"}]},"tackle":{"media":{"img":["media/pic/sports_comp.jpg","media/thumb/rugby.jpg"],"uk":"media/uk/tackle__gb_1.mp3","us":"media/us/tackle__us_1.mp3"},"oxford":{"phon":"ˈtækl","pos":"verb","senses":[{"en":"to make a determined effort to deal with a difficult problem or situation","cn":"应付，处理，解决（难题或局面）","g":"[transitive]","ex":{"en":"The government is determined to tackle inflation.","cn":"政府决心解决通货膨胀问题。"}},{"en":"to speak to somebody about a problem or difficult situation","cn":"与某人交涉；向某人提起（问题或困难情况）","g":"[transitive]","ex":{"en":"I tackled him about the money he owed me.","cn":"我就他欠我钱的事与他进行了交涉。"}},{"en":"to try and take the ball from an opponent","cn":"抢球；抢断；抢截；铲断","g":"[transitive, intransitive]","ex":{"en":"He was tackled just outside the penalty area.","cn":"他就在禁区外让对方把球抢断。"}},{"en":"to make an opponent fall to the ground in order to stop them running","cn":"擒抱摔倒；阻截","g":"[intransitive, transitive]","ex":{"en":"He can run fast and tackle hard.","cn":"他跑得快，阻截凶。"}},{"en":"to deal with somebody who is violent or threatening you","cn":"抓获；擒获；给以颜色","g":"[transitive]","ex":{"en":"He tackled a masked intruder at his home.","cn":"他在家里抓住了一个私自闯入的蒙面人。"}},{"en":"an act of trying to take the ball from an opponent in football (soccer), hockey, etc.; an act of knocking somebody to the ground, for example in rugby or American football","cn":"（足球、曲棍球等）抢断球，阻截铲球；（橄榄球或美式足球）擒抱摔倒，阻截","g":"[countable]","ex":{"en":"He was booked for a late tackle on Torres.","cn":"他因最后时刻铲倒托雷斯而被黄牌警告。"},"pos":"noun"},{"en":"a player whose job is to stop opponents by knocking them to the ground","cn":"截锋","g":"[countable]","lab":"North American English","pos":"noun"},{"en":"the equipment used to do a particular sport or activity, especially fishing","cn":"用具；体育器材；（尤指）渔具","g":"[uncountable]","ex":{"en":"He owns a gun and tackle shop in the village.","cn":"他在村里拥有一家枪械店。"},"pos":"noun"},{"en":"a man’s sexual organs","cn":"鸡巴；阳具","g":"[uncountable]","lab":"British English, slang，，","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(果断或高效地)应对，处理，解决(难题或任务)","en":"If you tackle a difficult problem or task, you deal with it in a very determined or efficient way.","ex":{"en":"The first reason to tackle these problems is to save children's lives","cn":"果断处理这些问题的首要原因是为了挽救孩子们的生命。"}},{"pos":"VERB 动词","cn":"(曲棍球、足球等比赛中)抢断，阻截，铲断;(英式、美式橄榄球比赛中)擒抱摔倒","en":"If you tackle someone in a game such as hockey or football, you try to take the ball away from them. If you tackle someone in rugby or American football, you knock them to the ground.","ex":{"en":"Foley tackled the quarterback.","cn":"福利成功拦截了四分卫。"}},{"pos":"VERB 动词","cn":"(坦率地)与…交谈，与…交涉","en":"If you tackle someone about a particular matter, you speak to them honestly about it, usually in order to get it changed or done.","ex":{"en":"I tackled him about how anyone could live amidst so much poverty.","cn":"我坦率地问他，人在如此贫穷的环境中如何还能生存。"}},{"pos":"VERB 动词","cn":"攻击;与…打架","en":"If you tackle someone, you attack them and fight them.","ex":{"en":"He claims Pasolini overtook and tackled him, pushing him into the dirt.","cn":"他声称帕索利尼追上去打他，把他推倒在烂泥里。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(体育等活动的)器具，器材;（尤指）渔具","en":"Tackle is the equipment that you need for a sport or activity, especially fishing.","ex":{"en":"...fishing tackle.","cn":"渔具"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（吊拉物体用的）索具，滑轮组","en":"Tackle is the equipment, usually consisting of ropes and pulleys, needed for lifting or pulling something.","ex":{"en":"I finally hoisted him up with a block and tackle.","cn":"我最终用滑轮组把他拉了上去。"}}]},"examples":[{"en":"He tackled a masked intruder at his home.","cn":"他在家里抓住了一个私自闯入的蒙面人。"},{"en":"I tackled him about the money he owed me.","cn":"我就他欠我钱的事与他进行了交涉。"}]},"talkative":{"media":{"uk":"media/uk/talkative__gb_1.mp3","us":"media/us/talkative__us_1.mp3"},"oxford":{"phon":"ˈtɔːkətɪv","pos":"adjective","senses":[{"en":"liking to talk a lot","cn":"爱说话的；饶舌的；健谈的","ex":{"en":"He's not very talkative, is he?","cn":"他的话不多，是吧？"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"爱说话的;话多的;健谈的","en":"Someone who is talkative talks a lot.","ex":{"en":"He suddenly became very talkative, his face slightly flushed, his eyes much brighter.","cn":"他的话突然多了起来，脸颊微微泛红，双眼明亮许多。"}}]},"examples":[{"en":"She was in a talkative mood.","cn":"她滔滔不绝，话兴正浓。"},{"en":"He's not very talkative, is he?","cn":"他的话不多，是吧？"}]},"tank":{"media":{"uk":"media/uk/tank__gb_1.mp3","us":"media/us/tank__us_1.mp3"},"oxford":{"phon":"tæŋk","pos":"noun","senses":[{"en":"a large container for holding liquid or gas","cn":"（贮放液体或气体的）箱，槽，罐","ex":{"en":"a fuel/water/storage tank","cn":"燃料／水／存储箱"}},{"en":"the contents of a tank or the amount it will hold","cn":"箱（或桶等）所装之物；一箱（或一桶等）的量","ex":{"en":"We drove there and back on one tank of fuel.","cn":"我们开车去那里来回用了一箱燃料。"}},{"en":"a military vehicle covered with strong metal and armed with guns. It can travel over very rough ground using wheels that move inside metal belts.","cn":"坦克","ex":{"en":"Tanks rolled in to end the siege.","cn":"坦克赶来解围。"}},{"en":"an artificial pool, lake or reservoir","cn":"（人工）水池，湖，水库","lab":"Indian English"},{"en":"to decrease suddenly or fail completely","cn":"彻底失败；破产；倒闭","g":"[intransitive]","lab":"informal","ex":{"en":"The company's shares tanked on Wall Street.","cn":"这家公司的股票在华尔街彻底崩盘了。"},"pos":"verb"},{"en":"to lose a game, especially deliberately","cn":"（尤指故意）输掉比赛","g":"[transitive, intransitive]","lab":"North American English, sport，，","ex":{"en":"She was accused of tanking the match.","cn":"有人指责她故意输掉这场比赛。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(盛放液体或气体的)罐，槽，箱，缸","en":"A tank is a large container for holding liquid or gas.","ex":{"en":"...an empty fuel tank","cn":"空空的油箱"}},{"pos":"N-COUNT 可数名词","cn":"坦克","en":"A tank is a large military vehicle that is equipped with weapons and moves along on metal tracks that are fitted over the wheels."}]},"examples":[{"en":"We drove there and back on one tank of petrol.","cn":"我们开车去那里来回用了一油箱汽油。"},{"en":"The company's shares tanked on Wall Street.","cn":"这家公司的股票在华尔街彻底崩盘了。"}]},"tag":{"oxford":{"phon":"tæɡ","pos":"noun","senses":[{"en":"a small piece of paper, cloth, plastic, etc. attached to something to identify it or give information about it","cn":"标签；标牌","g":"[countable]","ex":{"en":"He put name tags on all his shirts.","cn":"他给自己所有的衬衣都缝上了标有姓名的签条。"}},{"en":"an electronic device that can be attached to a person, animal or object so that police, researchers, etc. know where the person, etc. is","cn":"（电子）跟踪器","g":"[countable]","ex":{"en":"The police use electronic tags to monitor the whereabouts of young offenders on probation.","cn":"警方利用电子跟踪器监视缓刑期间的青年罪犯。"}},{"en":"a name or phrase that is used to describe a person or thing in some way","cn":"称呼；诨名","g":"[countable, usually singular]","ex":{"en":"They are finally ready to drop the tag ‘the new Beatles’.","cn":"他们终于准备放弃“新披头士乐队”这一称谓。"}},{"en":"a word or phrase that is added to a sentence for emphasis, for example I do in Yes, I do","cn":"附加语（为加强语气，如 Yes, I do 一句中的 I do）","g":"[countable]","lab":"linguistics"},{"en":"a set of letters or symbols that are put before and after a piece of text or data in order to identify it or show that it is to be treated in a particular way","cn":"标志；标记；标签；标识符","g":"[countable]","lab":"computing"},{"en":"a short quotation or saying in a foreign language","cn":"（外国语的）语录，引语，格言，谚语","g":"[countable]","ex":{"en":"the Latin tag ‘Si vis pacem, para bellum.’ (= if you want peace, prepare for war)","cn":"拉丁语格言：“欲要和平，辄需备战。”"}},{"en":"a children’s game in which one child runs after the others and tries to touch one of them","cn":"捉人（儿童游戏）","g":"[uncountable]","lab":"British English also"},{"en":"a symbol or name used by a graffiti writer and painted in a public place","cn":"（在公共场所涂鸦者用的）符号，名字","g":"[countable]"},{"en":"to fasten a tag onto something/somebody","cn":"给…加上标签","ex":{"en":"Each animal was tagged with a number for identification.","cn":"每只动物都系上了标有号码的小牌，以便辨认。"},"pos":"verb"},{"en":"to attach an electronic device to a person, animal or object so that the police, researchers, etc. know where the person, etc. is","cn":"给…安电子跟踪器","ex":{"en":"Persistent young offenders will be electronically tagged in a scheme to cut youth crime.","cn":"在一项减少青少年犯罪的计划中，将对惯犯的青少年罪犯进行电子标记。"},"pos":"verb"},{"en":"to give somebody/something a name that describes what they are or do","cn":"把…称作；给…起诨名","ex":{"en":"The country no longer wanted to be tagged as a Third World nation.","cn":"这个国家不愿意再被称为第三世界国家。"},"pos":"verb"},{"en":"to add a set of letters or symbols to a piece of text or data in order to identify it or to show that it is to be treated in a particular way","cn":"（给…）加标识符，加标签","lab":"computing","pos":"verb"},{"en":"to add a link to various users' profiles from a photo on a social media website","cn":"给（社交网站上照片中的人）加标记（由此可添加链接至其个人资料）","ex":{"en":"If you upload a photo, people can tag the people in it.","cn":"如果你上传一张照片，人们可以标记照片上的人。"},"pos":"verb"},{"en":"to leave a name or mark on a piece of graffiti to show who made it","cn":"在（涂鸦）上留名（或做标记）","ex":{"en":"Graffiti artists started tagging and painting entire subway trains.","cn":"涂鸦艺术家开始为整列地铁列车贴上标签和绘画。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"标签;标牌","en":"A tag is a small piece of card or cloth which is attached to an object or person and has information about that object or person on it.","ex":{"en":"Staff wore name tags.","cn":"工作人员都佩戴姓名牌。"}},{"pos":"N-COUNT 可数名词","cn":"(电子)追踪器","en":"An electronic tag is a device that is firmly attached to someone or something and sets off an alarm if that person or thing moves away or is removed.","ex":{"en":"A hospital is to fit newborn babies with electronic tags to foil kidnappers","cn":"一家医院计划在新生儿身上安置电子追踪器，防止婴儿被拐卖。"}},{"pos":"VERB 动词","cn":"给…贴标签;在…上做记号","en":"If you tag something, you attach something to it or mark it so that it can be identified later.","ex":{"en":"Professor Orr has developed interesting ways of tagging chemical molecules using existing laboratory lasers","cn":"奥尔教授发明了用现有实验室激光设备给化学分子做记号的种种有趣的办法。"}},{"pos":"N-COUNT 可数名词","cn":"称呼;称号","en":"You can refer to a phrase that is used to describe someone or something as a tag .","ex":{"en":"In Britain, jazz is losing its elitist tag and gaining a much broader audience.","cn":"在英国，爵士乐不再是精英人物的专利，它正吸引着越来越多的听众。"}},{"pos":"VERB 动词","cn":"将…描述成;用…来称呼;把…称作","en":"If you tag someone in a particular way, you keep describing them using a particular phrase or thinking of them as a particular thing.","ex":{"en":"...the pundits were still tagging him with that age-old label, 'best of a bad bunch'","cn":"专家们仍用多年前的称呼“最好的坏人”来称呼他。"}},{"pos":"N-COUNT 可数名词","cn":"(引用自书籍、讲演、文章的)短语，说法","en":"A tag is a short phrase or saying that you quote from a book, speech, or piece of writing."},{"pos":"N-UNCOUNT 不可数名词","cn":"(儿童玩的)捉人游戏","en":"Tag is a children's game in which one child chases the others and tries to touch them."},{"pos":"","cn":"","en":"相关词组：tag along tag on"}]},"media":{"uk":"media/uk/tag__gb_1.mp3","us":"media/us/tag__us_1.mp3"},"examples":[{"en":"He put name tags on all his shirts.","cn":"他给自己所有的衬衣都缝上了标有姓名的签条。"},{"en":"The police use electronic tags to monitor the whereabouts of young offenders on probation.","cn":"警方利用电子跟踪器监视缓刑期间的青年罪犯。"}]},"table":{"media":{"uk":"media/uk/table__gb_1.mp3","us":"media/us/table__us_1.mp3","img":["media/ldoce/img/dining_room_table.jpg"]},"oxford":{"phon":"ˈteɪbl","pos":"noun","senses":[{"en":"a piece of furniture that consists of a flat top supported by legs","cn":"桌子；台子；几","lab":"British English also","sc":"furniture","ex":{"en":"We sat at a round table in the corner.","cn":"我们坐在角落的一张圆桌旁。"}},{"en":"the people sitting at a table for a meal or to play cards, etc.","cn":"（就餐或玩牌等的）一桌人","sc":"people","ex":{"en":"He kept the whole table entertained with his jokes.","cn":"他笑话不断，把全桌人逗得直乐。"}},{"en":"a list of facts or numbers arranged in a special order, usually in rows and columns","cn":"表；一览表","sc":"list of facts/numbers","ex":{"en":"a table of contents (= a list of the main points or information in a book, usually at the front of the book)","cn":"目录"}},{"en":"a list of sports teams, countries, schools, etc. that shows their position in a competition, etc.","cn":"（竞赛等的）名次表，排名榜，积分表","sc":"in sport","ex":{"en":"If Arsenal win this game they'll go to the top of the table.","cn":"阿森纳队如果赢得这场比赛，就会登上积分榜榜首。"}},{"en":"a list showing the results when a number is multiplied by a set of other numbers, especially 1 to 12, in turn","cn":"乘法表","lab":"informal","sc":"mathematics","ex":{"en":"Do you know your six times table?","cn":"你会背六的乘法表吗？"}},{"en":"to present something formally for discussion","cn":"（正式）提出，把…列入议事日程","lab":"British English","ex":{"en":"to table a question in Parliament","cn":"在议会提出问题"},"pos":"verb"},{"en":"to leave an idea, a proposal, etc. to be discussed at a later date","cn":"（将主意、建议等）搁置","lab":"North American English","ex":{"en":"They voted to table the proposal until the following meeting.","cn":"他们投票决定把这项建议留到下次会议讨论。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"桌子;台子","en":"A table is a piece of furniture with a flat top that you put things on or sit at.","ex":{"en":"She was sitting at the kitchen table eating a currant bun","cn":"她正坐在餐桌旁，吃着葡萄干圆面包。"}},{"pos":"N-COUNT 可数名词","cn":"(饭店的)饭桌，餐桌","en":"If you ask for a table in a restaurant, you want to have a meal there.","ex":{"en":"I'd like a table for two at about 8:30, please","cn":"我想订一张 8:30 左右的双人桌。"}},{"pos":"VERB 动词","cn":"正式提出，提交(议案)","en":"If someone tables a proposal, they say formally that they want it to be discussed at a meeting.","ex":{"en":"They've tabled a motion criticising the Government for doing nothing about the problem.","cn":"他们提交了一项动议，批评政府在该问题上无所作为。"}},{"pos":"VERB 动词","cn":"搁置(提案、计划)","en":"If someone tables a proposal or plan which has been put forward, they decide to discuss it or deal with it at a later date, rather than straight away.","ex":{"en":"We will table that for later.","cn":"那个问题我们留到以后再讨论吧。"}},{"pos":"N-COUNT 可数名词","cn":"表;表格;目录","en":"A table is a written set of facts and figures arranged in columns and rows.","ex":{"en":"Consult the table on page 104","cn":"参阅 104 页的表格。"}},{"pos":"N-COUNT 可数名词","cn":"(1 至 12 的)乘法表","en":"A table is a list of the multiplications of numbers between one and twelve. Children often have to learn tables at school.","ex":{"en":"He didn't know his eleven-times table","cn":"他不知道11的乘法口诀。"}},{"pos":"PHRASE 短语","cn":"提交讨论;摆到桌面上","en":"If you put something on the table, you present it at a meeting for it to be discussed.","ex":{"en":"This is one of the best packages we've put on the table in years","cn":"这是我们几年来提交的最好的几套方案之一。"}},{"pos":"PHRASE 短语","cn":"扭转局面;转败为胜","en":"If you turn the tables on someone, you change the situation completely, so that instead of them causing problems for you, you are causing problems for them.","ex":{"en":"The only question is whether the President can use his extraordinary political skills to turn the tables on his opponents.","cn":"唯一的问题是，总统能否运用他杰出的政治手腕化被动为主动，击败对手。"}},{"pos":"","cn":"","en":"to put your cards on the table→see: ;"}]},"examples":[{"en":"Table 2 shows how prices and earnings have increased over the past 20 years.","cn":"表 2 显示了过去 20 年来价格和收入的增长情况。"},{"en":"They have tabled a motion for debate at the next Party Conference.","cn":"他们已经提出一项动议，在下次党的会议上进行辩论。"}]},"tang":{"media":{"uk":"media/uk/tang__gb_1.mp3","us":"media/us/tang__us_1.mp3"},"oxford":{"phon":"tæŋ","pos":"noun","senses":[{"en":"a strong sharp taste or smell","cn":"强烈味道；刺鼻气味","ex":{"en":"the tang of lemons","cn":"强烈的柠檬味"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"浓烈刺鼻的气味(或味道)","en":"A tang is a strong, sharp smell or taste.","ex":{"en":"She could smell the salty tang of the sea.","cn":"她能闻到海水浓烈的咸味。"}}]},"examples":[{"en":"a refreshing tangy lemon flavour","cn":"清新浓郁的柠檬香味"},{"en":"the tang of lemons","cn":"清爽的柠檬味"}]},"tale":{"media":{"uk":"media/uk/tale__gb_1.mp3","us":"media/us/tale__us_1.mp3"},"oxford":{"phon":"teɪl","pos":"noun","senses":[{"en":"a story created using the imagination, especially one that is full of action and adventure","cn":"（尤指充满惊险的）故事；历险记","ex":{"en":"a coming-of-age/morality tale","cn":"成长/道德故事"}},{"en":"an exciting spoken description of an event, which may not be completely true","cn":"（精彩但不一定完全真实的）讲述，叙述","ex":{"en":"I love listening to his tales of life at sea.","cn":"我喜欢听他讲述他的海上生活。"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"(常包含魔法或惊险内容的)传说，故事","en":"A tale is a story, often involving magic or exciting events.","ex":{"en":"...a collection of stories, poems and folk tales","cn":"由短篇故事、诗歌和传说汇成的作品集"}},{"pos":"N-COUNT 可数名词","cn":"(对真人真事精彩的或夸张的)描述，讲述","en":"You can refer to an interesting, exciting, or dramatic account of a real event as a tale .","ex":{"en":"The media have been filled with tales of horror and loss resulting from Monday's earthquake.","cn":"媒体上尽是星期一发生的地震所带来的恐惧和损失的报道。"}},{"pos":"PHRASE 短语","cn":"大难不死;逃过劫难;幸免于难","en":"If you survive a dangerous or frightening experience and so are able to tell people about it afterwards, you can say that you lived to tell the tale .","ex":{"en":"You lived to tell the tale this time but who knows how far you can push your luck.","cn":"你这次算是逃过了一劫，不过谁知道你的运气还会持续多久呢？"}},{"pos":"PHRASE 短语","cn":"造谣;泄密","en":"If someone tells tales about you, they tell other people things about you which are untrue or which you wanted to be kept secret.","ex":{"en":"I hesitated, not wanting to tell tales about my colleague.","cn":"我犹豫了，不想说同事的坏话。"}}]},"examples":[{"en":"I've heard tales of people seeing ghosts in that house.","cn":"我听说有人在那栋房子里见到过鬼。"},{"en":"Her experiences provide a cautionary tale (= a warning) for us all.","cn":"她的经历成了我们大家的前车之鉴。"}]},"taxi":{"media":{"img":["media/pic/taxi_comp.jpg","media/thumb/taxi1.jpg"],"uk":"media/uk/taxi__gb_1.mp3","us":"media/us/taxi__us_1.mp3"},"oxford":{"phon":"ˈtæksi","pos":"noun","senses":[{"en":"a car with a driver that you pay to take you somewhere. Taxis usually have meters that show how much money you have to pay.","cn":"出租汽车；计程车；的士","ex":{"en":"We took a taxi to the airport.","cn":"我们乘出租车去机场。"}},{"en":"a small bus with a driver that you pay to take you somewhere. Taxis usually have fixed routes and stop wherever passengers need to get on or off.","cn":"（走固定路线、乘客可随时上下的）小公共汽车，小巴士"},{"en":"to move slowly along the ground before taking off or after landing","cn":"（起飞前或降落后在地面上）滑行","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"出租车;计程车;的士","en":"A taxi is a car driven by a person whose job is to take people where they want to go in return for money.","ex":{"en":"The taxi drew up in front of the Riviera Club","cn":"出租车在里维埃拉俱乐部门口停了下来。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(飞机)缓慢滑行","en":"When an aircraft taxis along the ground, or when a pilot taxis a plane somewhere, it moves slowly along the ground.","ex":{"en":"She gave permission to the plane to taxi into position and hold for takeoff","cn":"她发出指令，允许飞机滑行入位，准备起飞。"}}]},"examples":[{"en":"I came home by taxi.","cn":"我是坐出租车回家的。"},{"en":"We'd better take a taxi.","cn":"我们最好乘出租车。"}]},"ta":{"oxford":{"phon":"tɑː","pos":"exclamation","senses":[{"en":"thank you","cn":"谢谢"},{"en":"Territorial Army","cn":"（英国）本土防卫义勇军，国防义勇军","lab":"British English","pos":"noun"},{"en":"teaching assistant","cn":"助教","pos":"noun"}]},"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"谢谢","en":"Ta means 'thank you'."}]},"media":{"uk":"media/uk/ta_1_gb_1.mp3","us":"media/us/ta_1_us_1.mp3"}},"tangible":{"media":{"uk":"media/uk/tangible__gb_1.mp3","us":"media/us/tangible__us_1.mp3"},"oxford":{"phon":"ˈtændʒəbl","pos":"adjective","senses":[{"en":"that can be clearly seen to exist","cn":"有形的；实际的；真实的","g":"[usually before noun]","ex":{"en":"tangible benefits/improvements/results, etc.","cn":"实际的好处、改进、效果等"}},{"en":"that you can touch or feel","cn":"可触摸的；可触知的；可感知的","ex":{"en":"The tension between them was almost tangible.","cn":"他们之间的紧张关系几乎让人都感觉得出来。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"清晰可见的;摸得着的;感觉得到的;明显的","en":"If something is tangible, it is clear enough or definite enough to be easily seen, felt, or noticed.","ex":{"en":"There should be some tangible evidence that the economy is starting to recover","cn":"应该有明显迹象表明经济开始复苏了。"}}]},"examples":[{"en":"The tension between them was almost tangible.","cn":"他们之间的紧张关系几乎让人都感觉得出来。"},{"en":"tangible benefits/improvements/results, etc.","cn":"实际的好处、改进、效果等"}]},"tap":{"media":{"uk":"media/uk/tap__gb_1.mp3","us":"media/us/tap__us_1.mp3","img":["media/ldoce/img/tap.jpg"]},"oxford":{"phon":"tæp","pos":"verb","senses":[{"en":"to hit somebody/something quickly and lightly","cn":"轻敲；轻拍；轻叩","g":"[intransitive, transitive]","ex":{"en":"Someone tapped at the door.","cn":"有人轻轻叩门。"}},{"en":"if you tap your fingers, feet, etc. or they tap, you hit them gently against a table, the floor, etc., for example to the rhythm of music","cn":"（用…）轻轻叩击","g":"[transitive, intransitive]","ex":{"en":"He kept tapping his fingers on the table.","cn":"他不停地用手指轻轻敲着桌子。"}},{"en":"to make use of a source of energy, knowledge, etc. that already exists","cn":"利用，开发，发掘（已有的资源、知识等）","g":"[transitive, intransitive]","ex":{"en":"We need to tap the expertise of the people we already have.","cn":"我们需要利用我们现有人员的专业知识。"}},{"en":"to fit a device to a phone so that somebody’s calls can be listened to secretly","cn":"（在电话上）安装窃听器，搭线窃听","g":"[transitive]","lab":"especially British English","ex":{"en":"He was convinced his phone was being tapped.","cn":"他确信自己的电话在被人窃听。"}},{"en":"to cut into a tree in order to get liquid from it","cn":"在（树）上切口（导出液体）","g":"[transitive]"},{"en":"to choose somebody to do a particular job","cn":"委任；指定（某人做某事）","g":"[transitive, usually passive]","lab":"North American English","ex":{"en":"Richards has been tapped to replace the retiring chairperson.","cn":"理查兹获得委任接替行将退任的主席。"}},{"en":"to produce a tap (6)","cn":"发拍音","g":"[transitive]","lab":"phonetics"},{"en":"a device for controlling the flow of water from a pipe into a bath or sink","cn":"水龙头；旋塞","g":"[countable]","lab":"especially British English","ex":{"en":"bath taps","cn":"浴缸水龙头"},"pos":"noun"},{"en":"a device for controlling the flow of liquid or gas from a pipe or container","cn":"龙头；旋塞","g":"[countable]","ex":{"en":"a gas tap","cn":"煤气阀门"},"pos":"noun"},{"en":"a light hit with your hand or fingers","cn":"轻击；轻拍；轻敲；轻叩","g":"[countable]","ex":{"en":"He felt a tap on his shoulder and turned round.","cn":"他觉得有人轻轻拍他的肩膀便转过身来。"},"pos":"noun"},{"en":"an act of fitting a device to a phone so that somebody’s phone calls can be listened to secretly","cn":"电话窃听；搭线窃听","g":"[countable]","ex":{"en":"a phone tap","cn":"电话窃听"},"pos":"noun"},{"en":"a style of dancing in which you tap to the rhythm of the music with your feet, wearing special shoes with pieces of metal on the heels and toes","cn":"一种舞蹈风格，您可以用脚踩着音乐的节奏，穿着特殊的鞋，在脚后跟和脚趾上铺上金属片","g":"[uncountable]","pos":"noun"},{"en":"a speech sound that is produced by striking the tongue quickly and lightly against the part of the mouth behind the upper front teeth. The ‘t’ in later in American English is an example of a tap.","cn":"拍音","g":"[countable]","lab":"phonetics","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"龙头;阀门;旋塞","en":"A tap is a device that controls the flow of a liquid or gas from a pipe or container, for example on a sink.","ex":{"en":"She turned on the taps.","cn":"她打开了那些龙头。"}},{"pos":"VERB 动词","cn":"轻打;轻拍;轻叩","en":"If you tap something, you hit it with a quick light blow or a series of quick light blows.","ex":{"en":"He tapped the table to still the shouts of protest","cn":"他敲了敲桌子，以平息抗议的喧闹声。"}},{"pos":"VERB 动词","cn":"(尤指听音乐时，用手指或脚)敲节拍，打拍子","en":"If you tap your fingers or feet, you make a regular pattern of sound by hitting a surface lightly and repeatedly with them, especially while you are listening to music.","ex":{"en":"The song's so catchy it makes you bounce round the living room or tap your feet.","cn":"这首歌很动听，听着它你就会不由自主地在客厅里舞动，或是用脚打拍子。"}},{"pos":"VERB 动词","cn":"开发，发掘，利用(资源、形势)","en":"If you tap a resource or situation, you make use of it by getting from it something that you need or want.","ex":{"en":"He owes his election to having tapped deep public disillusion with professional politicians","cn":"他将自己的当选归因于充分利用了公众对于职业政治家们不再抱希望的心情。"}},{"pos":"VERB 动词","cn":"偷听，窃听，监听(电话)","en":"If someone taps your telephone, they attach a special device to the line so that they can secretly listen to your conversations.","ex":{"en":"The government passed laws allowing the police to tap telephones","cn":"政府通过了允许警方监听电话的法令。"}},{"pos":"PHRASE 短语","cn":"(饮料)散装的，可随时(打开旋塞)取饮的","en":"If drinks are on tap, they come from a tap rather than from a bottle.","ex":{"en":"Filtered water is always on tap, making it very convenient to use.","cn":"随时打开龙头都有过滤水，用起来很方便。"}},{"pos":"PHRASE 短语","cn":"可轻松获取;可随时使用","en":"If something is on tap, you can have as much of it as you want whenever you want.","ex":{"en":"The advantage of group holidays is company on tap but time alone if you want it.","cn":"团体度假的好处在于，要找人陪伴非常容易，想要独处也行。"}},{"pos":"","cn":"","en":"相关词组：tap out"}]},"examples":[{"en":"The movie seems to tap into a general sentimentality about animals.","cn":"这部电影似乎在激发人们对动物的普遍怜惜之情。"},{"en":"The music set everyone's feet tapping.","cn":"乐曲使得每个人都用脚轻轻打起拍子来。"}]},"tail":{"oxford":{"phon":"teɪl","pos":"noun","senses":[{"en":"the part that sticks out at the back of the body of a bird, an animal or a fish, which the animal can move from side to side or up and down","cn":"尾；尾巴","g":"[countable]","sc":"of bird/animal/fish","ex":{"en":"The dog ran up, wagging its tail.","cn":"那条狗摇着尾巴跑上前去。"}},{"en":"having the type of tail mentioned","cn":"有…尾巴的","sc":"-tailed","ex":{"en":"a white-tailed eagle","cn":"白尾雕"}},{"en":"the back part of a plane, spacecraft, etc.","cn":"尾部；后部","g":"[countable]","sc":"of plane/spacecraft","ex":{"en":"The plane's tail section had broken off.","cn":"飞机的尾部断了。"}},{"en":"a part of something that sticks out at the back like a tail","cn":"尾状后部；尾状物","g":"[countable]","sc":"back/end of something","ex":{"en":"the tail of a kite","cn":"风筝的尾坠"}},{"en":"the last part of something that is moving away from you","cn":"（离去事物的）末尾部分","g":"[countable]","sc":"back/end of something","ex":{"en":"the tail of the procession","cn":"游行队伍的末尾"}},{"en":"a long jacket divided at the back below the waist into two pieces that become narrower at the bottom, worn by men at very formal events","cn":"燕尾服；男式晚礼服","g":"[plural]","lab":"informal","sc":"jacket","ex":{"en":"The men all wore top hat and tails.","cn":"男士都头戴高顶礼帽，身穿晚礼服。"}},{"en":"the side of a coin that does not have a picture of the head of a person on it, used as one choice when a coin is tossed to decide something","cn":"硬币反面，硬币文面（没有头像的一面）","g":"[uncountable]","sc":"side of coin"},{"en":"a person who is sent to follow somebody secretly and find out information about where that person goes, what they do, etc.","cn":"盯梢人；暗探","g":"[countable]","lab":"informal","sc":"person who follows somebody","ex":{"en":"The police have put a tail on him.","cn":"警方已派人对他进行盯梢。"}},{"en":"to follow somebody closely, especially in order to watch where they go and what they do","cn":"跟踪；尾随；盯梢","ex":{"en":"A private detective had been tailing them for several weeks.","cn":"私人侦探几个星期来一直在跟踪他们。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"尾;尾巴","en":"The tail of an animal, bird, or fish is the part extending beyond the end of its body.","ex":{"en":"The cattle were swinging their tails to disperse the flies.","cn":"那些牛甩动着尾巴驱赶苍蝇。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指细长物体的)尾部，末端","en":"You can use tail to refer to the end or back of something, especially something long and thin.","ex":{"en":"...the horizontal stabilizer bar on the plane's tail","cn":"飞机尾部的水平尾翼"}},{"pos":"N-PLURAL 复数名词","cn":"（男子的）燕尾服，晚礼服","en":"If a man is wearing tails, he is wearing a formal jacket which has two long pieces hanging down at the back."},{"pos":"VERB 动词","cn":"跟踪;盯梢;尾随","en":"To tail someone means to follow close behind them and watch where they go and what they do.","ex":{"en":"Officers had tailed the gang from London during a major undercover inquiry","cn":"在一次重大的秘密调查行动中，警察从伦敦就盯上了那帮匪徒。"}},{"pos":"N-COUNT 可数名词","cn":"盯梢者;跟踪者","en":"A tail is someone who is paid to watch and to follow another person.","ex":{"en":"He checked behind. No tail.","cn":"他看看身后——没有人跟着。"}},{"pos":"ADV 副词","cn":"(硬币的)反面","en":"If you toss a coin and it comes down tails, you can see the side of it that does not have a picture of a head on it."},{"pos":"PHRASE 短语","cn":"主次颠倒;喧宾夺主","en":"If you say that the tail is wagging the dog, you mean that a small or unimportant part of something is becoming too important and is controlling the whole thing.","ex":{"en":"Past TV deals have seen the tail wagging the dog. Now football clubs feel they are equal partners with TV.","cn":"以往和电视台的交易中，足球俱乐部就已经有过喧宾夺主的记录。现在，他们更是觉得可以和电视台平起平坐了。"}},{"pos":"PHRASE 短语","cn":"（由于失败或羞愧）夹着尾巴，垂头丧气","en":"If you say that you have your tail between your legs, you are emphasizing that you feel defeated and ashamed.","ex":{"en":"His team retreated last night with tails tucked firmly between their legs.","cn":"昨晚，他的队伍灰溜溜地退场了。"}},{"pos":"PHRASE 短语","cn":"掉头逃跑;转身逃走","en":"If you turn tail, you turn and run away.","ex":{"en":"I turned tail and fled in the direction of the main house.","cn":"我掉头就跑，朝主屋方向逃去。"}},{"pos":"","cn":"","en":"cannot make head or tail of something→see: ; to top and tail→see: ;"},{"pos":"","cn":"","en":"相关词组：tail away tail back tail off"}]},"media":{"uk":"media/uk/tail__gb_1.mp3","us":"media/us/tail__us_1.mp3","img":["media/ldoce/img/ldoce_262.png"]},"examples":[{"en":"‘But why … ?’ Her voice tailed away. “","cn":"但是为什么 … ？”她的声音细了下去。"},{"en":"A private detective had been tailing them for several weeks.","cn":"私人侦探几个星期来一直在跟踪他们。"}]},"talker":{"media":{"uk":"media/uk/talker__gb_1.mp3","us":"media/us/talker__us_1.mp3"},"oxford":{"phon":"ˈtɔːkə(r)","pos":"noun","senses":[{"en":"a person who talks in a particular way or who talks a lot","cn":"说话…的人；爱说话的人","ex":{"en":"a brilliant talker","cn":"能言善辩的人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"健谈的人;以某种方式说话的人","en":"You can use talker to refer to someone when you are considering how much they talk, or how good they are at talking to people.","ex":{"en":"...a fluent talker.","cn":"口若悬河的人"}}]},"examples":[{"en":"He's more a talker than a doer (= he talks instead of doing things).","cn":"他说得多做得少。"},{"en":"She's a (great) talker (= she talks a lot).","cn":"她很健谈。"}]},"tagged":{"oxford":{"phon":"tæɡ","pos":"noun","senses":[{"en":"( often in compounds","cn":"常构成复合词 ) a small piece of paper, cloth, plastic, etc. attached to sth to identify it or give information about it 标签；标牌"},{"en":"a name or phrase that is used to describe a person or thing in some way","cn":"称呼；诨名"}]}},"target":{"media":{"uk":"media/uk/target__gb_1.mp3","us":"media/us/target__us_1.mp3"},"oxford":{"phon":"ˈtɑːɡɪt","pos":"noun","senses":[{"en":"a result that you try to achieve","cn":"目标；指标","lab":"North American English","ex":{"en":"to meet/hit a target","cn":"完成目标"}},{"en":"an object, a person or a place that people aim at when attacking","cn":"（攻击的）目标，对象","lab":"figurative","ex":{"en":"They attacked military and civilian targets.","cn":"他们袭击了军事和民用目标。"}},{"en":"an object that people practise shooting at, especially a round board with circles on it","cn":"靶；靶子","lab":"figurative","ex":{"en":"to aim at a target","cn":"瞄准靶子"}},{"en":"to aim an attack or a criticism at somebody/something","cn":"把…作为攻击目标；把…作为批评的对象","ex":{"en":"He accused the group of deliberately targeting civilians.","cn":"他指控该组织蓄意以平民为攻击目标。"},"pos":"verb"},{"en":"to try to have an effect on a particular group of people or particular thing","cn":"面向，把…对准（某群体或某事物）","ex":{"en":"Film-makers are increasingly targeting international markets.","cn":"电影制片人越来越多地瞄准国际市场。"},"pos":"verb"},{"en":"a chain of stores in the US, first opened in 1962, which sells goods at low prices but which has a reputation for better quality goods and more organized stores than some other discounters","cn":"美国的连锁商店，于1962年首次开业，以低价出售商品，但与其他一些折扣店相比，它以质量更好的商品和更有条理的商店而享有声誉","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"靶子;目标;对象","en":"A target is something at which someone is aiming a weapon or other object.","ex":{"en":"The village lies beside a main road, making it an easy target for bandits","cn":"村子坐落在大路边上，很容易成为土匪袭击的对象。"}},{"pos":"N-COUNT 可数名词","cn":"目标;目的","en":"A target is a result that you are trying to achieve.","ex":{"en":"He's won back his place too late to achieve his target of 20 goals this season.","cn":"他赢回自己的位置时为时已晚，无法实现本赛季进 20 粒球的目标。"}},{"pos":"VERB 动词","cn":"攻击;批评;以…为攻击目标","en":"To target a particular person or thing means to decide to attack or criticize them.","ex":{"en":"Republicans targeted Unsoeld as vulnerable in her bid for reelection this year","cn":"共和党人将安索尔德定为攻击目标，认为她在争取今年连任的竞选中不堪一击。"}},{"pos":"VERB 动词","cn":"瞄准;面向;尽力吸引","en":"If you target a particular group of people, you try to appeal to those people or affect them.","ex":{"en":"The campaign will target American insurance companies","cn":"这场活动将以美国各保险公司为目标。"}},{"pos":"PHRASE 短语","cn":"进展顺利;有可能实现目标","en":"If someone or something is on target, they are making good progress and are likely to achieve the result that is wanted.","ex":{"en":"We were still right on target for our deadline.","cn":"我们仍然有可能赶在最后期限前达成目标。"}}]},"examples":[{"en":"The university will reach its target of 5 000 students next September.","cn":"这所大学将于下个九月达到在校学生 5 000 人的目标。"},{"en":"That's only OK if you believe that the end justifies the means (= bad methods of doing sth are acceptable if the final result is good).","cn":"如果你认为只要目的正确可以不择手段，那勉强是可以接受的。"}]},"task":{"media":{"uk":"media/uk/task__gb_1.mp3","us":"media/us/task__us_1.mp3"},"oxford":{"phon":"tɑːsk","pos":"noun","senses":[{"en":"a piece of work that somebody has to do, especially a hard or unpleasant one","cn":"（尤指艰巨或令人厌烦的）任务，工作","ex":{"en":"to accomplish/perform/undertake/complete a task","cn":"完成／执行／承担／完成任务"}},{"en":"an activity that is designed to help achieve a particular learning goal, especially in language teaching","cn":"（尤指语言教学中旨在帮助达到某一学习目的的）活动","ex":{"en":"Look at the diagram and then do the task below.","cn":"先看图表，然后做下面的任务。"}},{"en":"to give somebody a task to do","cn":"交给某人（任务）；派给某人（工作）","ex":{"en":"NATO troops were tasked with keeping the peace.","cn":"北约部队被赋予维持和平的任务。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"任务;工作","en":"A task is an activity or piece of work which you have to do, usually as part of a larger project.","ex":{"en":"Walker had the unenviable task of breaking the bad news to Hill","cn":"沃克不得不把这个坏消息告诉希尔。"}},{"pos":"VERB 动词","cn":"给…分配任务;派给…（工作）","en":"If you are tasked with doing a particular activity or piece of work, someone in authority asks you to do it.","ex":{"en":"The minister was tasked with checking that British aid money was being spent wisely.","cn":"部长被指派去督查英国的援助资金是否已用到实处。"}},{"pos":"PHRASE 短语","cn":"批评;责备","en":"If you take someone to task, you criticize them or tell them off because of something bad or wrong that they have done.","ex":{"en":"The country's intellectuals are also being taken to task for their failure to speak out against the regime.","cn":"该国知识分子也因未能公开反对该政权受到了指责。"}}]},"examples":[{"en":"a daunting/an impossible/a formidable/an unenviable, etc. task","cn":"令人望而生畏、不可能完成、艰巨、令人为难等的任务"},{"en":"Getting hold of this information was no easy task (= was difficult).","cn":"把这一情报搞到手绝不是件轻而易举的事。"}]},"tastes":{"oxford":{"phon":"teɪst","pos":"noun","senses":[{"en":"the particular quality that different foods and drinks have that allows you to recognize them when you put them in your mouth","cn":"味道；滋味"},{"en":"the sense you have that allows you to recognize different foods and drinks when you put them in your mouth","cn":"味觉"}]},"media":{"uk":"media/uk/taste__gb_1.mp3","us":"media/us/taste__us_1.mp3"}},"taxis":{"oxford":{"phon":"ˈtæksi","pos":"noun","senses":[{"en":"a car with a driver that you pay to take you somewhere. Taxis usually have meters which show how much money you have to pay.","cn":"出租汽车；计程车；的士"},{"en":"in some places in Africa, a small bus with a driver that you pay to take you somewhere. Taxis usually have fixed routes and stop wherever passengers need to get on or off. （","cn":"非洲某些地方行走固定路线、乘客可随时上下的）小公共汽车，小巴士"}]},"media":{"img":["media/pic/taxi_comp.jpg","media/thumb/taxi1.jpg"],"uk":"media/uk/taxi__gb_1.mp3","us":"media/us/taxi__us_1.mp3"}},"tablet":{"oxford":{"phon":"ˈtæblət","pos":"noun","senses":[{"en":"a small computer that is easy to carry, with a large touch screen and usually without a physical keyboard","cn":"平板电脑","ex":{"en":"The company has launched its latest 10-inch tablet.","cn":"该公司推出了其最新款 10 英寸平板电脑。"}},{"en":"a small round solid piece of medicine that you swallow","cn":"药片；片剂","lab":"especially British English","ex":{"en":"Take two tablets with water before meals.","cn":"每次两片，饭前用水冲服。"}},{"en":"an amount of a substance in a small, round, solid piece","cn":"丸","ex":{"en":"water purification tablets","cn":"净水丸"}},{"en":"a flat piece of stone that has words written on it, especially one that has been fixed to a wall in memory of an important person or event","cn":"（尤指固定于墙上作纪念的）牌，碑，匾","lab":"figurative","ex":{"en":"The school has a memorial tablet engraved with the name of the founder.","cn":"学校有一块牌位，刻着创始人的名字。"}},{"en":"a piece of soap","cn":"一块肥皂","lab":"old-fashioned, formal，，"},{"en":"a number of pieces of paper for writing or drawing on, that are fastened together at one edge","cn":"便笺本；拍纸簿","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"药片;片剂","en":"A tablet is a small solid round mass of medicine which you swallow.","ex":{"en":"It's time for your tablets, dear","cn":"该吃药了，亲爱的。"}},{"pos":"N-COUNT 可数名词","cn":"(黏土、石头制成的)牌，匾，碑","en":"Clay tablets or stone tablets are the flat pieces of clay or stone which people used to write on before paper was invented. tablets of stone→see: ;","ex":{"en":"He also studied the ancient stone tablets from around the pyramids.","cn":"他还研究了在金字塔周围发现的古代石匾。"}}]},"media":{"uk":"media/uk/tablet__gb_1.mp3","us":"media/us/tablet__us_1.mp3"},"examples":[{"en":"( figurative ) We can be very flexible — our entry requirements are not set in tablets of stone (= they can be changed).","cn":"我们可以非常灵活，加入条件并非铁板钉钉。"},{"en":"Take two tablets with water before meals.","cn":"每次两片，饭前用水冲服。"}]},"tailored":{"oxford":{"phon":"ˈteɪləd","pos":"adjective","senses":[{"en":"made to fit well or closely","cn":"定做的；合身的","ex":{"en":"a tailored jacket","cn":"定做的夹克衫"}},{"en":"made for a particular person or purpose","cn":"特制的；专门的","ex":{"en":"a tailored programme","cn":"量身定制的计划"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣服)紧身的，合身的","en":"Tailored clothes are designed to fit close to the body, rather than being loose.","ex":{"en":"...a white tailored shirt.","cn":"白色紧身衬衫"}}]},"media":{"uk":"media/uk/tailored__gb_1.mp3","us":"media/us/tailored__us_1.mp3"},"examples":[{"en":"a tailored jacket","cn":"订做的夹克衫"},{"en":"a tailored suit","cn":"定做的套装"}]},"tape":{"media":{"img":["media/pic/stationery_supplies_comp.jpg","media/thumb/tape.jpg"],"uk":"media/uk/tape__gb_1.mp3","us":"media/us/tape__us_1.mp3"},"oxford":{"phon":"teɪp","pos":"noun","senses":[{"en":"a long, narrow piece of material with a sticky substance on one side that is used for sticking things together","cn":"胶带；胶条","g":"[uncountable]","ex":{"en":"adhesive/sticky tape","cn":"黏胶带"}},{"en":"a long, thin piece of magnetic material, used for recording sounds, pictures or information, especially before digital technology became available","cn":"磁带，录音带，录像带（尤指数字技术出现之前）","g":"[uncountable]","ex":{"en":"Twenty years ago he was caught on tape in a very embarrassing situation.","cn":"20 年前他在一个令人尴尬的场合被录音。"}},{"en":"a cassette that contains sounds, or sounds and pictures, that have been recorded","cn":"录了音的盒式磁带；录了像的盒式磁带","g":"[countable]","ex":{"en":"a blank tape (= a tape with nothing recorded on it)","cn":"空白盒式磁带"}},{"en":"a narrow piece of material that is used for tying things together or as a label","cn":"（捆、系物品或作标记的）狭带，带子，线带，窄布条","g":"[countable, uncountable]","ex":{"en":"The papers were in a pile, tied together with a tape.","cn":"报纸叠成一摞，用带子捆了起来。"}},{"en":"a long, thin piece of material that is stretched across the place where a race will finish or used to mark off an area","cn":"（赛跑场地的）终点线；隔离线","g":"[countable]","ex":{"en":"the finishing tape","cn":"终点线"}},{"en":"a long thin piece of plastic, cloth or flexible metal that has measurements marked on it and is used for measuring the length or height of something","cn":"卷尺；皮尺","g":"[countable]"},{"en":"to record somebody/something on magnetic tape using a special machine","cn":"把…录在磁带上","ex":{"en":"Private conversations between the two had been taped and sent to a newspaper.","cn":"这两个人的私下谈话被录下音来送给了一家报纸。"},"pos":"verb"},{"en":"to fasten something by sticking or tying it with tape","cn":"用胶带粘住；用带子系紧","ex":{"en":"Put it in a box and tape it up securely.","cn":"把这个放进盒子里，再用带子系牢。"},"pos":"verb"},{"en":"to stick something onto something else using sticky tape","cn":"用胶带粘贴","ex":{"en":"Someone had taped a message on the door.","cn":"有人用胶带把字条贴在了门上。"},"pos":"verb"},{"en":"to tie a bandage (= a piece of cloth) around an injury or a wound","cn":"用绷带包扎","lab":"North American English","ex":{"en":"That's a nasty cut—come on, we'll get it all taped up.","cn":"伤口很严重，快，咱们用绷带把它包扎起来。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"磁带;录音带;录像带","en":"Tape is a narrow plastic strip covered with a magnetic substance. It is used to record sounds, pictures, and computer information.","ex":{"en":"Tape is expensive and loses sound quality every time it is copied","cn":"磁带成本高，而且每录制一次音质就会变差一些。"}},{"pos":"N-COUNT 可数名词","cn":"(盒式或卷盘式)录音带，录像带","en":"A tape is a cassette or spool with magnetic tape wound round it.","ex":{"en":"...a new cassette tape","cn":"一盒新带子"}},{"pos":"VERB 动词","cn":"(用录音机、录像机)录制(音乐、声音或电视画面)","en":"If you tape music, sounds, or television pictures, you record them using a tape recorder or a video recorder.","ex":{"en":"She has just taped an interview","cn":"她刚录制完一次采访。"}},{"pos":"N-VAR 可变名词","cn":"(捆扎东西或注明衣物主人的)布条，布带","en":"A tape is a strip of cloth used to tie things together or to identify who a piece of clothing belongs to.","ex":{"en":"The books were all tied up with tape.","cn":"所有书籍都用布条捆扎了起来。"}},{"pos":"N-COUNT 可数名词","cn":"(赛道上的)终点线","en":"A tape is a ribbon that is stretched across the finishing line of a race.","ex":{"en":"...the finishing tape.","cn":"终点线"}},{"pos":"N-UNCOUNT 不可数名词","cn":"胶带;胶条","en":"Tape is a sticky strip of plastic used for sticking things together.","ex":{"en":"...strong adhesive tape.","cn":"强力胶带"}},{"pos":"VERB 动词","cn":"(用胶带)粘贴","en":"If you tape one thing to another, you attach it using sticky tape.","ex":{"en":"I taped the base of the feather onto the velvet","cn":"我用胶带把羽毛的根部粘在了天鹅绒上。"}},{"pos":"","cn":"","en":"相关词组：tape up"}]},"examples":[{"en":"Private conversations between the two had been taped and sent to a newspaper.","cn":"这两个人的私下谈话被录下音来送给了一家报纸。"},{"en":"That's a nasty cut — come on, we'll get it all taped up.","cn":"伤口很严重，快，咱们用绷带把它包扎起来。"}]},"talk":{"media":{"uk":"media/uk/talk__gb_1.mp3","us":"media/us/talk__us_1.mp3"},"oxford":{"phon":"tɔːk","pos":"verb","senses":[{"en":"to say things; to speak in order to give information or to express ideas or feelings","cn":"说话；讲话；谈话","g":"[intransitive, transitive]","sc":"speak to somebody","ex":{"en":"Stop talking and listen!","cn":"别说话，注意听！"}},{"en":"to discuss something, usually something serious or important","cn":"讨论，谈论，商谈，洽谈（通常指重大的事）","g":"[intransitive, transitive]","sc":"discuss","ex":{"en":"This situation can't go on. We need to talk.","cn":"这种情况不能再继续下去了。我们需要谈一谈。"}},{"en":"to say words in a language","cn":"（用某种语言）讲，说","g":"[intransitive, transitive]","sc":"say words","ex":{"en":"The baby is just starting to talk.","cn":"这婴儿刚开始咿呀学语。"}},{"en":"to say things that are/are not sensible","cn":"说，讲（有理、无理的话）","g":"[transitive]","lab":"British English","sc":"sense/nonsense","ex":{"en":"She talks a lot of sense.","cn":"她讲得很在理。"}},{"en":"used to emphasize an amount of money, how serious something is, etc.","cn":"（用以强调款额、情况严重程度等）讲的是，指的是","g":"[transitive]","lab":"informal","sc":"for emphasis","ex":{"en":"We're talking £500 for three hours' work.","cn":"咱们讲的可是工作三个小时酬金 500 英镑。"}},{"en":"to talk about a person’s private life","cn":"说闲话；讲人坏话；嚼舌头","g":"[intransitive]","sc":"about private life","ex":{"en":"Don't phone me at work—people will talk.","cn":"别在上班时给我打电话，人家会说闲话的。"}},{"en":"to give information to somebody, especially unwillingly","cn":"供出消息；供认；招认","g":"[intransitive]","sc":"give information","ex":{"en":"The police questioned him but he refused to talk.","cn":"警察审问他，但他拒不招供。"}},{"en":"a speech or lecture on a particular subject","cn":"（专题）报告，演讲","g":"[countable]","sc":"speech","ex":{"en":"I went to several interesting talks at the conference.","cn":"会议期间我听了几场有意思的演讲。"},"pos":"noun"},{"en":"a conversation or discussion","cn":"交谈；谈话；讨论；商讨","g":"[countable]","sc":"conversation","ex":{"en":"She looked worried so we had a talk.","cn":"她看上去很忧虑，所以我们谈了一下。"},"pos":"noun"},{"en":"formal discussions between governments or organizations","cn":"（政府或组织之间正式的）洽谈，会谈，谈判","g":"[plural]","sc":"formal discussions","ex":{"en":"peace/trade talks","cn":"和谈；贸易谈判"},"pos":"noun"},{"en":"words that are spoken, but without the necessary facts or actions to support them","cn":"空话；空谈","g":"[uncountable]","lab":"informal","sc":"words without actions","ex":{"en":"It's just talk. He'd never carry out his threats.","cn":"这只不过是说说而已。他绝不会把他的恫吓付诸行动。"},"pos":"noun"},{"en":"stories that suggest a particular thing might be true or might happen in the future","cn":"传言；谣言；流言蜚语；揣测","g":"[uncountable]","sc":"stories/rumours","ex":{"en":"She dismissed the stories of her resignation as newspaper talk.","cn":"她不理会有关她辞职的报道，认为那不过是报纸的谣言。"},"pos":"noun"},{"en":"a topic of conversation or a way of speaking","cn":"话题；说话方式","g":"[uncountable]","sc":"topic/way of speaking","ex":{"en":"business talk","cn":"业务洽谈"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"讲话;说话","en":"When you talk, you use spoken language to express your thoughts, ideas, or feelings.","ex":{"en":"He was too distressed to talk","cn":"他伤心得讲不出话来。"}},{"pos":"V-RECIP 相互动词","cn":"交谈;谈话","en":"If you talk to someone, you have a conversation with them. You can also say that two people talk .","ex":{"en":"We talked and laughed a great deal","cn":"我们说笑了很久。"}},{"pos":"V-RECIP 相互动词","cn":"谈心，倾诉，诉说心事","en":"If you talk to someone, you tell them about the things that are worrying you. You can also say that two people talk .","ex":{"en":"Your first step should be to talk to a teacher or school counselor","cn":"你第一步应该是去找老师或学校辅导员谈谈。"}},{"pos":"VERB 动词","cn":"发表谈话;发表观点","en":"If you talk on or about something, you make an informal speech telling people what you know or think about it.","ex":{"en":"She will talk on the issues she cares passionately about including education and nursery care","cn":"她将会谈一些自己十分感兴趣的话题，包括教育和幼儿护理。"}},{"pos":"N-PLURAL 复数名词","cn":"(通常指国家、劳资间为达成某种协定的)谈判，商谈","en":"Talks are formal discussions intended to produce an agreement, usually between different countries or between employers and employees.","ex":{"en":"...the next round of Middle East peace talks","cn":"下一轮中东和平谈判"}},{"pos":"V-RECIP 相互动词","cn":"磋商;讨论","en":"If one group of people talks to another, or if two groups talk, they have formal discussions in order to do a deal or produce an agreement.","ex":{"en":"We're talking to some people about opening an office in London","cn":"我们在和一些人讨论在伦敦设立办事处的事儿。"}},{"pos":"V-RECIP 相互动词","cn":"会谈;对话;谈判","en":"When different countries or different sides in a dispute talk, or talk to each other, they discuss their differences in order to try and settle the dispute.","ex":{"en":"The Foreign Minister said he was ready to talk to any country that had no hostile intentions","cn":"外交部长说他愿意和任何不怀敌意的国家举行会谈。"}},{"pos":"VERB 动词","cn":"议论;嚼舌;说闲话","en":"If people are talking about another person or are talking, they are discussing that person.","ex":{"en":"Everyone is talking about him","cn":"人人都在议论他。"}},{"pos":"VERB 动词","cn":"(通常指不情愿地)供出，招认，招供","en":"If someone talks when they are being held by police or soldiers, they reveal important or secret information, usually unwillingly.","ex":{"en":"They'll talk, they'll implicate me.","cn":"他们会招供的，他们会把我牵连进去的。"}},{"pos":"VERB 动词","cn":"讲，说，操(某种语言或口音)","en":"If you talk a particular language or talk with a particular accent, you use that language or have that accent when you speak.","ex":{"en":"You don't sound like a foreigner talking English","cn":"听你讲英语，不像是外国人。"}},{"pos":"VERB 动词","cn":"谈论，讨论(政治、体育等)","en":"If you talk something such as politics or sport, you discuss it.","ex":{"en":"The guests were mostly middle-aged men talking business.","cn":"顾客多数是些谈正事的中年男子。"}},{"pos":"VERB 动词","cn":"说，讲(…的话)","en":"You can use talk to say what you think of the ideas that someone is expressing. For example, if you say that someone is talking sense, you mean that you think the opinions they are expressing are sensible.","ex":{"en":"You must admit George, you're talking absolute rubbish.","cn":"乔治，你得承认你说的全都是废话。"}},{"pos":"VERB 动词","cn":"谈论;讨论","en":"You can say that you are talking a particular thing to draw attention to your topic or to point out a characteristic of what you are discussing.","ex":{"en":"We're not talking a murder here; we're talking poker machines or gambling — things that are misdemeanors in most states","cn":"我们现在讨论的不是谋杀，而是扑克机或赌博——这些在多数州只能算轻罪了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(想法、威胁)说说而已，空谈","en":"If you say that something such as an idea or threat is just talk, or all talk, you mean that it does not mean or matter much, because people are exaggerating about it or do not really intend to do anything about it.","ex":{"en":"Has much of this actually been tried here? Or is it just talk?","cn":"这个多半已经真正尝试过了吗？还是仅仅说说而已？"}},{"pos":"PHRASE 短语","cn":"这才叫…;真是","en":"You can say talk about before mentioning a particular expression or situation, when you mean that something is a very striking or clear example of that expression or situation.","ex":{"en":"Took us quite a while to get here, didn't it? Talk about Fate moving in a mysterious way!","cn":"我们用了很长时间才走到今天这步，是吧？这就叫命运难测啊！"}},{"pos":"PHRASE 短语","cn":"我说，说到，谈到(用于引出新话题)","en":"You can use the expression talking of to introduce a new topic that you want to discuss, and to link it to something that has already been mentioned.","ex":{"en":"Belvoir Farms produce a delicious elderflower tea. Talking of elderflower, you might wish to try Elderflower Champagne.","cn":"贝尔沃农场生产一种非常好喝的接骨木花茶。说到接骨木花，你兴许想尝尝接骨木花香槟酒。"}},{"pos":"","cn":"","en":"to talk shop→see: ;"},{"pos":"","cn":"","en":"相关词组：talk around talk back talk down talk down to talk into talk out talk out of talk over talk round talk through talk up"}]},"examples":[{"en":"What are you talking about? (= used when you are surprised, annoyed and/or worried by sth that sb has just said)","cn":"你在胡说什么？（对他人所言感到惊奇、不悦或担忧时用）"},{"en":"I don't know what you're talking about (= used to say that you did not do sth that sb has accused you of).","cn":"我不知道你在说什么（表示自己没有做对方指责的事）。"}]},"talented":{"media":{"uk":"media/uk/talented__gb_1.mp3","us":"media/us/talented__us_1.mp3"},"oxford":{"phon":"ˈtæləntɪd","pos":"adjective","senses":[{"en":"having a natural ability to do something well","cn":"有才能的；天才的；有才干的","ex":{"en":"a talented player/musician/artist","cn":"天才运动员／音乐家／艺术家"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"天资聪颖的;天赋高的","en":"Someone who is talented has a natural ability to do something well.","ex":{"en":"Howard is a talented pianist","cn":"霍华德是个很有天分的钢琴家。"}}]},"examples":[{"en":"a talented player","cn":"天才运动员"},{"en":"a talented actor","cn":"一名很有天赋的演员"}]},"taste":{"media":{"uk":"media/uk/taste__gb_1.mp3","us":"media/us/taste__us_1.mp3"},"oxford":{"phon":"teɪst","pos":"noun","senses":[{"en":"the particular quality that different foods and drinks have that allows you to recognize them when you put them in your mouth","cn":"味道；滋味","g":"[countable, uncountable]","sc":"of food and drink","ex":{"en":"a sweet/salty/bitter/sour taste","cn":"甜味；咸味；苦味；酸味"}},{"en":"the sense you have that allows you to recognize different foods and drinks when you put them in your mouth","cn":"味觉","g":"[uncountable]","sc":"sense","ex":{"en":"I've lost my sense of taste.","cn":"我失去了味觉。"}},{"en":"a small quantity of food or drink that you try in order to see what it is like","cn":"少许尝的东西；一口；一点儿","g":"[countable, usually singular]","sc":"small quantity","ex":{"en":"Just have a taste of this cheese.","cn":"尝一点儿这种奶酪吧。"}},{"en":"a short experience of something","cn":"体验；尝试","g":"[singular]","sc":"short experience","ex":{"en":"This was my first taste of live theatre.","cn":"这是我初次在现场看戏。"}},{"en":"a person’s ability to choose things that people recognize as being of good quality or appropriate","cn":"鉴赏力；欣赏力","g":"[uncountable]","sc":"ability to choose well","ex":{"en":"He has very good taste in music.","cn":"他有很高的音乐欣赏力。"}},{"en":"what a person likes or prefers","cn":"爱好；志趣","g":"[countable, uncountable]","sc":"what you like","ex":{"en":"You can adapt the recipe to suit your personal taste.","cn":"你可以按自己的口味调整食谱。"}},{"en":"to have a particular taste","cn":"有…味道","sc":"have taste","ex":{"en":"to taste good/delicious/sweet","cn":"味道好／香／甜"},"pos":"verb"},{"en":"having a particular taste","cn":"有…味道的","sc":"have taste","ex":{"en":"foul-tasting medicine","cn":"难吃的药"},"pos":"verb"},{"en":"to be able to recognize tastes in food and drink","cn":"尝出，品出（食品或饮料的味道）","g":"[transitive]","sc":"recognize taste","ex":{"en":"You can taste the garlic in this stew.","cn":"在这炖肉里你可以尝出大蒜的味道。"},"pos":"verb"},{"en":"to test the taste of something by eating or drinking a small amount of it","cn":"尝，品（味道）","g":"[transitive]","sc":"test taste","ex":{"en":"Taste it and see if you think there's enough salt in it.","cn":"你尝尝看这够不够咸。"},"pos":"verb"},{"en":"to eat or drink food or liquid","cn":"吃；喝","g":"[transitive]","sc":"eat/drink","ex":{"en":"That's the best ice cream I've ever tasted.","cn":"那是我吃过的最好的冰激凌。"},"pos":"verb"},{"en":"to have a short experience of something, especially something that you want more of","cn":"浅尝；尝到甜头","g":"[transitive]","sc":"have short experience","ex":{"en":"He had tasted freedom only to lose it again.","cn":"他刚尝到了自由的甜头，却又失去了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"味觉","en":"Taste is one of the five senses that people have. When you have food or drink in your mouth, your sense of taste makes it possible for you to recognize what it is.","ex":{"en":"...a keen sense of taste.","cn":"灵敏的味觉"}},{"pos":"N-COUNT 可数名词","cn":"味道;口味","en":"The taste of something is the individual quality which it has when you put it in your mouth and which distinguishes it from other things. For example, something may have a sweet, bitter, sour, or salty taste.","ex":{"en":"I like the taste of wine and enjoy trying different kinds","cn":"我喜欢葡萄酒的味道，喜欢品尝不同的口味。"}},{"pos":"N-SING 单数名词","cn":"(品尝的)少量，一点，一小口","en":"If you have a taste of some food or drink, you try a small amount of it in order to see what the flavour is like.","ex":{"en":"We have a taste of the white wine he's brought.","cn":"我们尝了尝他带来的白葡萄酒。"}},{"pos":"VERB 动词","cn":"有…的味道","en":"If food or drink tastes of something, it has that particular flavour, which you notice when you eat or drink it.","ex":{"en":"I drank a cup of tea that tasted of diesel","cn":"我喝了杯有股柴油味的茶。"}},{"pos":"VERB 动词","cn":"尝;品尝","en":"If you taste some food or drink, you eat or drink a small amount of it in order to try its flavour, for example to see if you like it or not.","ex":{"en":"He finished his aperitif and tasted the wine the waiter had produced","cn":"他喝完开胃酒，又尝了点侍者端来的葡萄酒。"}},{"pos":"VERB 动词","cn":"尝出…的味道","en":"If you can taste something that you are eating or drinking, you are aware of its flavour.","ex":{"en":"You can taste the chilli in the dish but it is a little sweet.","cn":"你可以尝出菜里面有辣椒，不过味道有点甜。"}},{"pos":"N-SING 单数名词","cn":"(短暂的)经历，体验，尝试","en":"If you have a taste of a particular way of life or activity, you have a brief experience of it.","ex":{"en":"But having had a taste of the big time, he won't want to go back to playing in the reserves","cn":"但是，有过一举成名的经历以后，他就不会再想回去当替补了。"}},{"pos":"VERB 动词","cn":"(短暂地)经历，感受，尝试","en":"If you taste something such as a way of life or a pleasure, you experience it for a short period of time.","ex":{"en":"Anyone who has tasted this life wants it to carry on for as long as possible.","cn":"任何过过这种日子的人都希望它持续得越久越好。"}},{"pos":"N-SING 单数名词","cn":"喜欢;偏好","en":"If you have a taste for something, you have a liking or preference for it.","ex":{"en":"She developed a taste for journeys to isolated hazardous regions in North America","cn":"她喜欢上了到北美那些险象环生的偏远地区旅行。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"鉴赏力;品味","en":"A person's taste is their choice in the things that they like or buy, for example their clothes, possessions, or music. If you say that someone has good taste, you mean that you approve of their choices. If you say that they have poor taste, you disapprove of their choices.","ex":{"en":"His taste in clothes is extremely good","cn":"他在穿衣方面很有品味。"}},{"pos":"PHRASE 短语","cn":"格调庸俗的/格调高雅的;没品位的/高品位的;不合时宜的/得体的","en":"If you say that something that is said or done is in bad taste or in poor taste, you mean that it is offensive, often because it concerns death or sex and is inappropriate for the situation. If you say that something is in good taste, you mean that it is not offensive and that it is appropriate for the situation.","ex":{"en":"He rejects the idea that his film is in bad taste","cn":"他不接受那种认为他的电影格调不高的观点。"}},{"pos":"PHRASE 短语","cn":"(烹饪时)依各人口味，酌量","en":"When a recipe tells you to add a particular spice or other flavouring to taste, it means that you can add as much of that ingredient as you like.","ex":{"en":"Add tomato paste, salt and pepper to taste.","cn":"酌量添加番茄酱、盐和胡椒粉。"}}]},"examples":[{"en":"Although we didn't know it, this incident was a taste of things to come.","cn":"尽管当时我们并不知道，但这件事是后来一系列事件的开端。"},{"en":"That trip gave me a taste for foreign travel.","cn":"那次旅游使我产生了去国外旅行的兴趣。"}]},"taught":{"collins":{"senses":[{"pos":"","cn":"","en":"Taught is the past tense and past participle of teach."}]},"media":{"uk":"media/uk/taught__gb_1.mp3","us":"media/us/taught__us_1.mp3"}},"talent":{"media":{"uk":"media/uk/talent__gb_1.mp3","us":"media/us/talent__us_1.mp3"},"oxford":{"phon":"ˈtælənt","pos":"noun","senses":[{"en":"a natural ability to do something well","cn":"天才；天资；天赋","g":"[uncountable, countable]","ex":{"en":"The festival showcases the talent of young musicians.","cn":"会演展示了年轻音乐家们的才华。"}},{"en":"people or a person with a natural ability to do something well","cn":"有才能的人；人才；天才","g":"[uncountable, countable]","ex":{"en":"to nurture/develop young talent","cn":"培养青年人才"}},{"en":"people who are sexually attractive","cn":"（统称）性感的人","g":"[uncountable]","lab":"British English, slang，，","ex":{"en":"He likes to spend his time chatting up the local talent.","cn":"他喜欢把时间花在和当地的妞儿搭讪上。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"天资;天赋","en":"Talent is the natural ability to do something well.","ex":{"en":"She is proud that both her children have a talent for music","cn":"她为自己的两个孩子都有音乐天赋而自豪。"}}]},"examples":[{"en":"He likes to spend his time chatting up the local talent.","cn":"他喜欢把时间花在和当地的妞儿搭讪上。"},{"en":"She showed considerable talent for getting what she wanted.","cn":"她很有天资，能够达成自己的目标。"}]},"tall":{"media":{"uk":"media/uk/tall__gb_1.mp3","us":"media/us/tall__us_1.mp3"},"oxford":{"phon":"tɔːl","pos":"adjective","senses":[{"en":"having a greater than average height","cn":"高的；高大的","ex":{"en":"She's tall and thin.","cn":"她身材高瘦。"}},{"en":"used to describe or ask about the height of somebody/something","cn":"（用以表示或询问高度）有…高，身高","ex":{"en":"How tall are you?","cn":"你身高多少？"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"高的;高大的","en":"Someone or something that is tall has a greater height than is normal or average.","ex":{"en":"Being tall can make you feel incredibly self-confident","cn":"个子高会使你感觉极其自信。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(用于指高度)有…高的，身高…的","en":"You use tall to ask or talk about the height of someone or something. →see usage note at:","ex":{"en":"How tall are you?","cn":"你多高？"}},{"pos":"PHRASE 短语","cn":"难办的事情;棘手的问题","en":"If something is a tall order, it is very difficult.","ex":{"en":"Financing your studies may seem like a tall order, but there is plenty of help available.","cn":"学费的筹措可能看似一个大难题，好在你可以获得许多帮助。"}},{"pos":"PHRASE 短语","cn":"昂首挺胸;理直气壮","en":"If you say that someone walks tall, you mean that they behave in a way that shows that they have pride in themselves and in what they are doing."}]},"examples":[{"en":"He's six feet tall and weighs 200 pounds.","cn":"他身高六英尺，体重 200 磅。"},{"en":"the tallest building in the world","cn":"世界上最高的建筑物"}]},"take":{"media":{"uk":"media/uk/take__gb_1.mp3","us":"media/us/take__us_1.mp3"},"oxford":{"phon":"teɪk","pos":"verb","senses":[{"en":"to carry or move something from one place to another","cn":"携带；拿走；取走；运走","g":"[transitive]","sc":"carry/lead","ex":{"en":"Remember to take your coat when you leave.","cn":"走的时候记着把大衣拿走。"}},{"en":"to go with somebody from one place to another, especially to guide or lead them","cn":"带去；引领","g":"[transitive]","sc":"carry/lead","ex":{"en":"It's too far to walk—I'll take you by car.","cn":"步行路太远，我开车送你去。"}},{"en":"to make somebody/something go from one level, situation, etc. to another","cn":"使达到，把…推向，把…带到（另一个层次、层面等）","g":"[transitive]","sc":"carry/lead","ex":{"en":"Her energy and talent took her to the top of her profession.","cn":"她凭着充沛的精力和天赋的才能达到了事业的顶峰。"}},{"en":"to need or require a particular amount of time","cn":"需要…时间；费时","g":"[transitive, no passive, intransitive]","sc":"time","ex":{"en":"The process took about a year.","cn":"这个过程花了约一年时间。"}},{"en":"to photograph somebody/something","cn":"拍照；照相；摄影","g":"[transitive]","sc":"photograph","ex":{"en":"to take a picture/photo/shot of somebody/something","cn":"给（某人／某物）拍照／照相／拍快照"}},{"en":"to use a form of transport, a road, a path, etc. to go to a place","cn":"乘坐，搭乘（交通工具）；取（道）；走（路线）","g":"[transitive]","sc":"transport/road","ex":{"en":"to take the bus/train","cn":"乘公共汽车／火车"}},{"en":"to put your hands or arms around somebody/something and hold them/it; to reach for somebody/something and hold them/it","cn":"拿；抱；握；取；接","g":"[transitive]","sc":"reach and hold","ex":{"en":"I passed him the rope and he took it.","cn":"我把绳子递给他，他接了过去。"}},{"en":"to remove something/somebody from a place or a person","cn":"拿开；取出；挪开","g":"[transitive]","lab":"informal","sc":"remove","ex":{"en":"Will you take your books off the table?","cn":"把你的书从桌子上拿走好吗？"}},{"en":"to remove something without permission or by mistake","cn":"擅自拿走；偷走；误拿","g":"[transitive]","lab":"figurative","sc":"remove","ex":{"en":"Someone has taken my scarf.","cn":"有人把我的围巾拿走了。"}},{"en":"to get something from a particular source","cn":"从…中取出；取材于","g":"[transitive]","sc":"remove","ex":{"en":"The scientists are taking water samples from the river.","cn":"科学家正从河中采水样。"}},{"en":"to sit down in or use a chair, etc.","cn":"就（座）；占据（座位）","g":"[transitive]","sc":"seat","ex":{"en":"Are these seats taken?","cn":"这些座位有人吗？"}},{"en":"to eat, drink, etc. something","cn":"吃；喝；服（药）","g":"[transitive]","sc":"eat/drink","ex":{"en":"Do you take sugar in your coffee?","cn":"你的咖啡里要放糖吗？"}},{"en":"to find out and record something; to write something down","cn":"记录；摘录；记下","g":"[transitive]","sc":"write down","ex":{"en":"The police officer took my name and address.","cn":"警察记下了我的姓名和地址。"}},{"en":"to do an exam or a test","cn":"参加（考试或测验）","g":"[transitive]","sc":"exam","ex":{"en":"When did you take your driving test?","cn":"你什么时候参加的驾驶执照考试？"}},{"en":"to study a subject at school, college, etc.","cn":"学习，读，修（课程）","g":"[transitive]","sc":"study","ex":{"en":"She is planning to take a course in web design.","cn":"她打算修一门网络设计课。"}},{"en":"to use a particular course of action in order to deal with or achieve something","cn":"采取（措施）；采用（方法）","g":"[transitive]","sc":"action","ex":{"en":"We need to take a different approach to the problem.","cn":"我们应该采用另一种方法来解决这一问题。"}},{"en":"used with nouns to say that somebody is doing something, performing an action, etc.","cn":"（与名词连用，表示举动、动作等）","g":"[transitive]","lab":"British English","sc":"action","ex":{"en":"to take a look","cn":"看一看"}},{"en":"to test or measure something","cn":"量取；测定","g":"[transitive]","sc":"measurement","ex":{"en":"to take somebody’s temperature","cn":"给某人量体温"}},{"en":"to capture a place or person; to get control of something","cn":"夺取；攻占；抓获；控制","g":"[transitive]","sc":"capture","ex":{"en":"The rebels succeeded in taking the town.","cn":"反叛者攻占了那个城镇。"}},{"en":"to choose, buy or rent something","cn":"选中；买下；租用","g":"[transitive]","sc":"choose/buy","ex":{"en":"I'll take the grey jacket.","cn":"我要那件灰色夹克衫。"}},{"en":"to buy a newspaper or magazine regularly","cn":"经常购买（某报纸或期刊）","g":"[transitive]","lab":"formal","sc":"choose/buy","ex":{"en":"We take the ‘Express’.","cn":"我们订阅的是《快报》。"}},{"en":"to accept or receive something","cn":"接受；收到","g":"[transitive]","sc":"accept/receive","ex":{"en":"If they offer me the job, I'll take it.","cn":"如果他们给我这份工作，我就接受。"}},{"en":"to act in response to an opportunity","cn":"抓住，利用（机会）","g":"[transitive]","sc":"accept/receive","ex":{"en":"When the bus stopped for fuel, we took the opportunity to get something to eat.","cn":"公共汽车停下加油，我们趁机找了点儿吃的。"}},{"en":"to accept somebody as a customer, patient, etc.","cn":"接纳；接待（顾客、患者等）","g":"[transitive]","sc":"accept/receive","ex":{"en":"The school doesn't take boys (= only has girls).","cn":"这所学校不收男生。"}},{"en":"to experience or be affected by something","cn":"遭受；经受；承受","g":"[transitive]","sc":"accept/receive","ex":{"en":"The school took the full force of the explosion.","cn":"这所学校在爆炸中毁坏最严重。"}},{"en":"to be able to bear something","cn":"忍受；容忍；承受","g":"[transitive, no passive]","sc":"accept/receive","ex":{"en":"She can't take criticism.","cn":"她受不了批评。"}},{"en":"to react to something/somebody in a particular way","cn":"（以某种方式）对待，处理","g":"[transitive]","sc":"accept/receive","ex":{"en":"He took the criticism surprisingly well.","cn":"他对待这一批评的态度竟意外地好。"}},{"en":"to understand or consider something in a particular way","cn":"领会；理解；考虑","g":"[transitive]","sc":"consider","ex":{"en":"How am I supposed to take that remark?","cn":"我应该怎么理解那话的意思？"}},{"en":"to consider somebody/something to be somebody/something, especially when you are wrong","cn":"（尤指错误地）以为，把…看作；误认为","g":"[transitive]","sc":"consider","ex":{"en":"Even the experts took the painting for a genuine Van Gogh.","cn":"连行家都误以为这幅画是凡高的真迹。"}},{"en":"to have a particular feeling, opinion or attitude","cn":"产生（感觉）；持有（看法）；采取（态度）","g":"[transitive]","sc":"have feeling/opinion","ex":{"en":"My parents always took an interest in my hobbies.","cn":"我父母总是关心重视我的爱好。"}},{"en":"to reduce one number by the value of another","cn":"减去","g":"[transitive]","lab":"informal","sc":"mathematics","ex":{"en":"Take 5 from 12 and you're left with 7.","cn":"12 减 5 得 7。"}},{"en":"used to introduce somebody/something as an example","cn":"以…为例；将…作为例证","g":"[transitive]","sc":"give example","ex":{"en":"Lots of couples have problems in the first year of marriage. Take Ann and Paul.","cn":"在婚后头一年里，许多夫妇都出现一些问题。安和保罗就是个例子。"}},{"en":"to have or start to have a particular form, position or state","cn":"采用（形式）；就任（职位）；出现（状况）","g":"[transitive]","sc":"form/position","ex":{"en":"Our next class will take the form of a debate.","cn":"我们下一堂课将采用辩论的形式。"}},{"en":"to need or require something in order to happen or be done","cn":"需要；要求","g":"[transitive, no passive]","lab":"informal","sc":"need","ex":{"en":"It only takes one careless driver to cause an accident.","cn":"只要有一个粗心大意的驾驶者便会发生车祸。"}},{"en":"to use something in order to work","cn":"使用；用","g":"[transitive, no passive]","sc":"need","ex":{"en":"The buses have been adapted to take biofuel.","cn":"公共汽车被改装为使用生物燃料。"}},{"en":"to wear a particular size in shoes or clothes","cn":"穿用（…尺码的鞋或衣服）","g":"[transitive, no passive]","sc":"size of shoes/clothes","ex":{"en":"What size shoes do you take?","cn":"你穿多大号的鞋？"}},{"en":"to have enough space for something/somebody; to be able to hold or contain a particular quantity","cn":"容纳；装；盛","g":"[transitive, no passive]","sc":"hold/contain","ex":{"en":"The bus can take 60 passengers.","cn":"这辆公共汽车可载 60 名乘客。"}},{"en":"to be the teacher or leader in a class or a religious service","cn":"授（课）；主持（宗教仪式）","g":"[transitive]","sc":"teach/lead","ex":{"en":"The head teacher usually takes us for French.","cn":"校长通常给我们上法语课。"}},{"en":"to go over or around something","cn":"跨过；跳过；绕过","g":"[transitive]","sc":"go over/around","ex":{"en":"The horse took the first fence well.","cn":"那匹马轻快地跃过了第一道栅栏。"}},{"en":"to kick or throw the ball from a fixed or agreed position","cn":"踢；掷","g":"[transitive]","sc":"in sports","ex":{"en":"to take a penalty/free kick/corner","cn":"主罚点球／任意球；开角球"}},{"en":"to use a particular method to find out people’s opinions","cn":"付诸（表决）；举行（投票）；进行（调查）","g":"[transitive]","sc":"vote/survey","ex":{"en":"to take a vote/poll/survey","cn":"付诸表决；进行民意测验／调查"}},{"en":"to be successful; to work","cn":"成功；起作用；行得通","g":"[intransitive]","sc":"be successful","ex":{"en":"The skin graft failed to take.","cn":"皮肤移植未能成功。"}},{"en":"to have or require something when used in a sentence or other structure","cn":"（用于句子或其他结构中时）有，需要","g":"[transitive]","sc":"grammar","ex":{"en":"The verb ‘rely’ takes the preposition ‘on’.","cn":"动词 rely 需要和介词 on 连用。"}},{"en":"a scene or part of a film that is filmed at one time without stopping the camera","cn":"（不停机一次连续拍摄的）场景，镜头","ex":{"en":"We managed to get it right in just two takes.","cn":"我们仅拍摄了两个镜头就把这部分戏拍好了。"},"pos":"noun"},{"en":"an amount of money that somebody receives, especially the money that is earned by a business during a particular period of time","cn":"收入额；进项","g":"[usually singular]","lab":"informal","ex":{"en":"How much is my share of the take?","cn":"我的那一份收入是多少？"},"pos":"noun"},{"en":"the particular opinion or idea that somebody has about something","cn":"看法；意见","lab":"informal","ex":{"en":"What's his take on the plan?","cn":"他对这项计划有什么意见？"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（后接名词，用于描述动作或事件）","en":"You can use take followed by a noun to talk about an action or event, when it would also be possible to use the verb that is related to that noun. For example, you can say 'she took a shower' instead of 'she showered'.","ex":{"en":"She was too tired to take a shower","cn":"她累得连澡都懒得冲。"}},{"pos":"VERB 动词","cn":"（与一系列名词连用，代替意义更为具体的动词）","en":"In ordinary spoken or written English, people use take with a range of nouns instead of using a more specific verb. For example people often say 'he took control' or 'she took a positive attitude' instead of 'he assumed control' or 'she adopted a positive attitude'.","ex":{"en":"The Patriotic Front took power after a three-month civil war","cn":"经过 3 个月内战，爱国阵线夺取了政权。"}},{"pos":"VERB 动词","cn":"拿;取","en":"If you take something, you reach out for it and hold it.","ex":{"en":"Here, let me take your coat","cn":"来，我帮你拿大衣。"}},{"pos":"VERB 动词","cn":"随身带;携带","en":"If you take something with you when you go somewhere, you carry it or have it with you.","ex":{"en":"Mark often took his books to Bess's house to study","cn":"马克常常带着书本去贝丝家学习。"}},{"pos":"VERB 动词","cn":"运送;带领;通向","en":"If a person, vehicle, or path takes someone somewhere, they transport or lead them there.","ex":{"en":"She took me to a Mexican restaurant","cn":"她带我去了一家墨西哥餐厅。"}},{"pos":"VERB 动词","cn":"(工作、兴趣等)使…去，使…前往","en":"If something such as a job or interest takes you to a place, it is the reason for you going there.","ex":{"en":"He was a poor student from Madras whose genius took him to Cambridge","cn":"他是个来自马德拉斯的穷学生，凭自身的才华上了剑桥。"}},{"pos":"VERB 动词","cn":"请教（问题等）；洽谈(生意等)","en":"If you take something such as your problems or your business to someone, you go to that person when you have problems you want to discuss or things you want to buy.","ex":{"en":"You need to take your problems to a trained counsellor","cn":"你需要去找训练有素的咨询顾问请教这些问题。"}},{"pos":"VERB 动词","cn":"使…达到(一定水平、程度或状态)","en":"If one thing takes another to a particular level, condition, or state, it causes it to reach that level or condition.","ex":{"en":"A combination of talent, hard work and good looks have taken her to the top","cn":"兼具天赋、勤奋和美貌使她得以出人头地。"}},{"pos":"VERB 动词","cn":"拿掉;去掉;拿开","en":"If you take something from a place, you remove it from there.","ex":{"en":"He took a handkerchief from his pocket and lightly wiped his mouth","cn":"他从口袋里掏出手帕，轻轻擦了擦嘴。"}},{"pos":"VERB 动词","cn":"偷走;(擅自)拿走","en":"If you take something from someone who owns it, you steal it or go away with it without their permission.","ex":{"en":"He has taken my money, and I have no chance of getting it back","cn":"他偷了我的钱，我再也要不回来了。"}},{"pos":"VERB 动词","cn":"(军队、政党)攻占，夺取，赢得，俘虏","en":"If an army or political party takes something or someone, they win them from their enemy or opponent.","ex":{"en":"A Serb army unit took the town","cn":"一支塞尔维亚部队攻占了那个镇。"}},{"pos":"VERB 动词","cn":"减去;减","en":"If you take one number or amount from another, you subtract it or deduct it.","ex":{"en":"Take off the price of the house, that's another hundred thousand.","cn":"减去房价，又是 10 万。"}},{"pos":"VERB 动词","cn":"忍受;忍耐;接受;经受","en":"If you cannot take something difficult, painful, or annoying, you cannot tolerate it without becoming upset, ill, or angry.","ex":{"en":"Don't ever ask me to look after those kids again. I just can't take it!","cn":"以后别再叫我去照看那些孩子了，我简直无法忍受！"}},{"pos":"VERB 动词","cn":"(尤指在战争中)蒙受，遭受(损害、损失)","en":"If you take something such as damage or loss, you suffer it, especially in war or in a battle.","ex":{"en":"They have taken heavy casualties.","cn":"他们遭受重大伤亡。"}},{"pos":"VERB 动词","cn":"花费，占用(时间)","en":"If something takes a certain amount of time, that amount of time is needed in order to do it.","ex":{"en":"Since the roads are very bad, the journey took us a long time","cn":"由于路况很糟糕，我们路上花了很长时间。"}},{"pos":"VERB 动词","cn":"需要，要求(某种素质或某物)","en":"If something takes a particular quality or thing, that quality or thing is needed in order to do it.","ex":{"en":"At one time, walking across the room took all her strength","cn":"曾经有段时间她得费尽全力才能从房间一头走到另一头。"}},{"pos":"VERB 动词","cn":"接受;采纳","en":"If you take something that is given or offered to you, you agree to accept it.","ex":{"en":"When I took the job I thought I could change the system, but it's hard","cn":"我接受那份工作时，以为我能改变那种体制，可实际上很难。"}},{"pos":"VERB 动词","cn":"(从…中)获取，感到","en":"If you take a feeling such as pleasure, pride, or delight in a particular thing or activity, the thing or activity gives you that feeling.","ex":{"en":"They take great pride in their heritage","cn":"他们为自己的历史传统深感自豪。"}},{"pos":"VERB 动词","cn":"(商店、饭店、剧院等)收入，赚取","en":"If a shop, restaurant, theatre, or other business takes a certain amount of money, they get that amount from people buying goods or services.","ex":{"en":"The firm took £100,000 in bookings.","cn":"这家公司在票务预订方面的收入达到 10 万英镑。"}},{"pos":"N-SING 单数名词","cn":"(商业机构的)收入，获利","en":"You can use take to refer to the amount of money that a business such as a store or theatre gets from selling its goods or tickets during a particular period.","ex":{"en":"It added another $11.8 million to the take, for a grand total of $43 million.","cn":"这就又增加了1,180万美元的收入，总计为 4,300 万美元。"}},{"pos":"VERB 动词","cn":"赢得，摘得(奖项或奖牌)","en":"If you take a prize or medal, you win it.","ex":{"en":"'Poison' took first prize at the 1991 Sundance Film Festival","cn":"《毒药》在 1991 年的圣丹斯电影节上获得一等奖。"}},{"pos":"VERB 动词","cn":"承担，承受，接受(责备、责任或功劳)","en":"If you take the blame, responsibility, or credit for something, you agree to accept it.","ex":{"en":"His brother Raoul did it, but Leonel took the blame and kept his mouth shut","cn":"事情是莱昂内尔的弟弟拉乌尔干的，可是莱昂内尔却代他受过，并且对此绝口不提。"}},{"pos":"VERB 动词","cn":"接受，接纳(病人或顾客)","en":"If you take patients or clients, you accept them as your patients or clients.","ex":{"en":"Some universities would be forced to take more students than they wanted","cn":"有些大学将被迫超计划招生。"}},{"pos":"VERB 动词","cn":"接听(电话)","en":"If you take a telephone call, you speak to someone who is telephoning you.","ex":{"en":"Douglas telephoned Catherine at her office. She refused to take his calls.","cn":"道格拉斯把电话打进凯瑟琳的办公室，可是她不接。"}},{"pos":"VERB 动词","cn":"(以特定方式)看待，对待","en":"If you take something in a particular way, you react in the way mentioned to a situation or to someone's beliefs or behaviour.","ex":{"en":"Unfortunately, no one took my messages seriously","cn":"遗憾的是，没人把我提供的信息当回事。"}},{"pos":"VERB 动词","cn":"以…(为例);拿…(来说)","en":"You use take when you are discussing or explaining a particular question, in order to introduce an example or to say how the question is being considered.","ex":{"en":"There's confusion and resentment, and it's almost never expressed out in the open. Take this office, for example","cn":"有人迷惘，有人憎恨，可是几乎谁也没有公开表达过。就拿这个办公室的人来说吧。"}},{"pos":"VERB 动词","cn":"理解;明白;同意","en":"If you take someone's meaning or point, you understand and accept what they are saying.","ex":{"en":"They've turned sensible, if you take my meaning","cn":"他们变得通情达理了，如果你明白我的意思的话。"}},{"pos":"VERB 动词","cn":"把…错当成;误以为","en":"If you take someone for something, you believe wrongly that they are that thing.","ex":{"en":"She had taken him for a journalist","cn":"她把他错当成记者了。"}},{"pos":"VERB 动词","cn":"选择要;选择购买","en":"If you take something from among a number of things, you choose to have or buy it.","ex":{"en":"'I'll take the grilled tuna,' Mary Ann told the waiter.","cn":"“给我来份烤金枪鱼吧，”玛丽·安告诉侍者。"}},{"pos":"VERB 动词","cn":"走，沿着(道路或路线)","en":"If you take a road or route, you choose to travel along it.","ex":{"en":"From Wrexham centre take the Chester Road to the outskirts of town","cn":"从雷克瑟姆市中心出发，沿着切斯特路到达市郊。"}},{"pos":"VERB 动词","cn":"(短期)租赁，租住","en":"If you take a house or flat, you rent it, usually for only a short time.","ex":{"en":"My wife and I have taken the cottage for a month.","cn":"我和妻子租下这套乡间小屋已经一个月了。"}},{"pos":"VERB 动词","cn":"购买,订阅(报纸等)","en":"If you take something such as a newspaper, you buy it or have it delivered to your home on a regular basis.","ex":{"en":"Before the Chronicle I used to take the Guardian.","cn":"在订阅《纪事报》以前，我看的是《卫报》。"}},{"pos":"VERB 动词","cn":"乘坐;搭乘","en":"If you take a car, train, bus, or plane, you use it to go from one place to another.","ex":{"en":"It's the other end of the High Street. We'll take the car, shall we?","cn":"它在大街的那头，我们乘车去，好吗？"}},{"pos":"VERB 动词","cn":"学习，选修(课程)","en":"If you take a subject or course at school or university, you choose to study it.","ex":{"en":"Students are allowed to take European history and American history.","cn":"学生可以选修欧洲史和美国史。"}},{"pos":"VERB 动词","cn":"参加(考试)","en":"If you take a test or examination, you do it in order to obtain a qualification.","ex":{"en":"She took her driving test in Greenford","cn":"她在格林福特参加了驾照考试。"}},{"pos":"VERB 动词","cn":"教…(课程);给…讲授(课程)","en":"If you take someone for a subject, you give them lessons in that subject.","ex":{"en":"The teacher who took us for economics was Miss Humphrey.","cn":"教我们经济学的是汉弗莱小姐。"}},{"pos":"VERB 动词","cn":"服用，使用(毒品、药物)","en":"If someone takes drugs, pills, or other medicines, they take them into their body, for example by swallowing them.","ex":{"en":"She's been taking sleeping pills","cn":"她一直在服用安眠药。"}},{"pos":"VERB 动词","cn":"吃;喝","en":"If you take food or drink, you eat or drink it.","ex":{"en":"She made a habit of coming in to take tea with Nanny Crabtree","cn":"她养成了进来和克拉布特里奶奶一起喝茶的习惯。"}},{"pos":"VERB 动词","cn":"记(笔记);写(书信)","en":"If you take a note or a letter, you write down something you want to remember or the words that someone says.","ex":{"en":"She sat expressionless, carefully taking notes","cn":"她坐在那儿面无表情，认真记着笔记。"}},{"pos":"VERB 动词","cn":"测量;度量","en":"If you take a particular measurement, you use special equipment to find out what something measures.","ex":{"en":"By drilling, geologists can take measurements at various depths","cn":"通过钻探，地质学家可以在不同深度测量。"}},{"pos":"VERB 动词","cn":"能容纳;装得下","en":"If a place or container takes a particular amount or number, there is enough space for that amount or number.","ex":{"en":"The place could just about take 2,000 people.","cn":"那地方只能容纳大约 2,000 人。"}},{"pos":"VERB 动词","cn":"穿(特定尺码的鞋或衣物)","en":"If you take a particular size in shoes or clothes, that size fits you.","ex":{"en":"47 per cent of women in the UK take a size 16 or above.","cn":"英国47%的女性穿16码或更大号的。"}},{"pos":"VERB 动词","cn":"(药物)起作用，生效;(染料)着色","en":"If something such as a drug or a dye takes, it has the effect or result that is intended.","ex":{"en":"If the cortisone doesn't take, I may have to have surgery.","cn":"如果可的松无效，我恐怕只能动手术了。"}},{"pos":"N-COUNT 可数名词","cn":"(一次拍摄的)场景，镜头","en":"A take is a short piece of action which is filmed in one continuous process for a cinema or television film.","ex":{"en":"She couldn't get it right — she never knew the lines and we had to do several takes.","cn":"她就是拍不好——她总记不住台词，我们只好拍了好几遍。"}},{"pos":"N-SING 单数名词","cn":"态度;理解;看法","en":"Someone's take on a particular situation or fact is their attitude to it or their interpretation of it.","ex":{"en":"What's your take on the new government? Do you think it can work?","cn":"你对新政府怎么看？你认为它能行吗？"}},{"pos":"PHRASE 短语","cn":"我自认为;我以为;我猜测","en":"You can say 'I take it' to check with someone that what you believe to be the case or what you understand them to mean is in fact the case, or is in fact what they mean.","ex":{"en":"I take it you're a friend of the Kellings, Mr Burr","cn":"伯尔先生，想必您是凯林家的朋友吧？"}},{"pos":"PHRASE 短语","cn":"相信我;我敢保证","en":"You can say 'take it from me' to tell someone that you are absolutely sure that what you are saying is correct, and that they should believe you.","ex":{"en":"Take it from me — this is the greatest achievement by any Formula One driver ever.","cn":"信我的没错——这是一级方程式赛车手有史以来所取得的最高成就。"}},{"pos":"CONVENTION 惯用语","cn":"接不接受随你，要就要不要拉倒(不容讨价还价)","en":"If you say to someone 'take it or leave it', you are telling them that they can accept something or not accept it, but that you are not prepared to discuss any other alternatives.","ex":{"en":"A 72-hour week, 12 hours a day, six days a week, take it or leave it.","cn":"一星期 6 天，一天 12 小时，总共 72 小时，愿不愿意随你的便。"}},{"pos":"PHRASE 短语","cn":"忍受，甘受，屈从于(侮辱或攻击)","en":"If someone takes an insult or attack lying down, they accept it without protesting.","ex":{"en":"The government is not taking such criticism lying down.","cn":"政府决不会甘心忍受这种批评。"}},{"pos":"PHRASE 短语","cn":"使费尽力气;使精疲力竭","en":"If something takes a lot out of you or takes it out of you, it requires a lot of energy or effort and makes you feel very tired and weak afterwards.","ex":{"en":"He looked tired, as if the argument had taken a lot out of him","cn":"他看上去累坏了，似乎这场争论已使他精疲力尽。"}},{"pos":"PHRASE 短语","cn":"使忘却烦恼;使心情好","en":"If something takes you out of yourself, it makes you feel better and so you forget all your worries and unhappiness.","ex":{"en":"Donating time and energy to others can take you out of yourself.","cn":"抽出一些时间和精力帮助别人可以使你忘却烦恼。"}},{"pos":"PHRASE 短语","cn":"休息 5 分钟/休息 10 分钟","en":"If someone tells you to take five or to take ten, they are telling you to have a five or ten minute break from what you are doing."},{"pos":"","cn":"","en":"to be taken aback→see: ; to take up arms→see: ; to take the biscuit→see: ; to take the bull by the horns→see: ; to take your hat off to someone→see: ; to take the mickey→see: ; to take the piss out of someone→see: ; to take something as read→see: ; to be taken for a ride→see: ; to take someone by surprise→see: ; take my word for it→see: ;"},{"pos":"","cn":"","en":"相关词组：take after take against take apart take away take away from take back take down take in take off take on take out take out on take over take to take up take up on take upon take up with"}]},"examples":[{"en":"Lots of couples have problems in the first year of marriage. Take Ann and Paul.","cn":"在婚后头一年里，许多夫妇都出现一些问题。安和保罗就是个例子。"},{"en":"I don't want to take away from his achievements, but he couldn't have done it without my help.","cn":"我不想贬低他的成就，但是如果没有我的帮助，他是做不成的。"}]},"tasting":{"oxford":{"phon":"ˈteɪstɪŋ","pos":"noun","senses":[{"en":"an event at which people can try different kinds of food and drink, especially wine, in small quantities","cn":"品尝会","ex":{"en":"a wine tasting","cn":"品酒会"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"品尝会","en":"Tasting is used in expressions such as wine tasting to refer to a social event at which people try different kinds of the specified drink or food in small amounts."}]},"media":{"uk":"media/uk/tasting__gb_1.mp3","us":"media/us/tasting__us_1.mp3"},"examples":[{"en":"a wine tasting","cn":"品酒会"},{"en":"a wine and cheese tasting","cn":"一次葡萄酒和奶酪品尝会"}]},"targets":{"oxford":{"phon":"ˈtɑːɡɪt","pos":"noun","senses":[{"en":"a result that you try to achieve","cn":"目标；指标"},{"en":"an object, a person or a place that people aim at when attacking （","cn":"攻击的）目标，对象"}]}},"tapes":{"oxford":{"phon":"teɪp","pos":"noun","senses":[{"en":"a long narrow strip of magnetic material that is used for recording sounds, pictures or information","cn":"磁带；录音带；录像带"},{"en":"a cassette that contains sounds, or sounds and pictures, that have been recorded","cn":"录了音的盒式磁带；录了像的盒式磁带"}]}},"talents":{"oxford":{"phon":"ˈtælənt","pos":"noun","senses":[{"en":"a natural ability to do sth well","cn":"天才；天资；天赋"},{"en":"people or a person with a natural ability to do sth well","cn":"有才能的人；人才；天才"}]}},"tales":{"oxford":{"phon":"teɪl","pos":"noun","senses":[{"en":"a story created using the imagination, especially one that is full of action and adventure （","cn":"尤指充满惊险的）故事；历险记"},{"en":"an exciting spoken description of an event, which may not be completely true （","cn":"精彩但不一定完全真实的）讲述，叙述"}]}},"talks":{"oxford":{"phon":"tɔːk","pos":"verb","senses":[{"en":"to say things; to speak in order to give information or to express feelings, ideas, etc.","cn":"说话；讲话；谈话"},{"en":"to discuss sth, usually sth serious or important","cn":"讨论，谈论，商谈，洽谈（通常指重大的事）"}]}},"takes":{"oxford":{"phon":"teɪk","pos":"verb","senses":[{"en":"to carry or move sth from one place to another","cn":"携带；拿走；取走；运走"},{"en":"to go with sb from one place to another, especially to guide or lead them","cn":"带去；引领"}]}},"tasked":{"oxford":{"phon":"tɑːsk","pos":"noun","senses":[{"en":"a piece of work that sb has to do, especially a hard or unpleasant one （","cn":"尤指艰巨或令人厌烦的）任务，工作"},{"en":"an activity which is designed to help achieve a particular learning goal, especially in language teaching （","cn":"尤指语言教学中旨在帮助达到某一学习目的的）活动"}]}},"talked":{"oxford":{"phon":"tɔːk","pos":"verb","senses":[{"en":"to say things; to speak in order to give information or to express feelings, ideas, etc.","cn":"说话；讲话；谈话"},{"en":"to discuss sth, usually sth serious or important","cn":"讨论，谈论，商谈，洽谈（通常指重大的事）"}]}},"taken":{"oxford":{"phon":"teɪk","pos":"verb","senses":[{"en":"to carry or move sth from one place to another","cn":"携带；拿走；取走；运走"},{"en":"to go with sb from one place to another, especially to guide or lead them","cn":"带去；引领"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Taken is the past participle of take ."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"对…感兴趣的;为…所吸引的","en":"If you are taken with something or someone, you are very interested in them or attracted to them.","ex":{"en":"She seems very taken with the idea","cn":"她好像对这个想法很感兴趣。"}}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld44taken.mp3","us":"media/ldoce/hwd/ame/f/ld44taken.mp3"}},"talking":{"oxford":{"phon":"tɔːk","pos":"verb","senses":[{"en":"to say things; to speak in order to give information or to express feelings, ideas, etc.","cn":"说话；讲话；谈话"},{"en":"to discuss sth, usually sth serious or important","cn":"讨论，谈论，商谈，洽谈（通常指重大的事）"}]}},"tanked":{"oxford":{"phon":"tæŋk","pos":"noun","senses":[{"en":"a large container for holding liquid or gas （","cn":"贮放液体或气体的）箱，槽，罐"},{"en":"the contents of a tank or the amount it will hold","cn":"箱（或桶等）所装之物；一箱（或一桶等）的量"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"喝醉的;酩酊大醉的","en":"If someone is tanked or tanked up, they are drunk."}]}},"tables":{"oxford":{"phon":"ˈteɪbl","pos":"noun","senses":[{"en":"a piece of furniture that consists of a flat top supported by legs","cn":"桌子；台子；几"},{"en":"the people sitting at a table for a meal or to play cards, etc. （","cn":"就餐或玩牌等的）一桌人"}]}},"targeted":{"oxford":{"phon":"ˈtɑːɡɪtɪd","pos":"adjective","senses":[{"en":"aimed at a particular place or group of people","cn":"针对特定地方（或人群）的；有目标的；有针对性的","ex":{"en":"strategically targeted attacks","cn":"战略上有针对性的攻击"}}]}},"taking":{"oxford":{"phon":"teɪk","pos":"verb","senses":[{"en":"to carry or move sth from one place to another","cn":"携带；拿走；取走；运走"},{"en":"to go with sb from one place to another, especially to guide or lead them","cn":"带去；引领"}]}},"taxes":{"oxford":{"phon":"tæks","pos":"noun","senses":[{"en":"money that you have to pay to the government so that it can pay for public services. People pay tax according to their income and businesses pay tax according to their profits. Tax is also often paid on goods and services.","cn":"税；税款"},{"en":"to put a tax on sb/sth; to make sb pay tax","cn":"对 … 征税；课税；使纳税"}]}},"tacked":{"oxford":{"phon":"tæk","pos":"noun","senses":[{"en":"the way in which you deal with a particular situation; the direction of your words or thoughts","cn":"方针；方法；思路"},{"en":"( technical","cn":"术语 ) the direction that a boat with sails takes as it sails at an angle to the wind in order to fill its sails （帆船的）抢风调向"}]}},"tapping":{"oxford":{"phon":"tæp","pos":"verb","senses":[{"en":"to hit sb/sth quickly and lightly","cn":"轻敲；轻拍；轻叩"},{"en":"if you tap your fingers, feet, etc. or they tap , you hit them gently against a table, the floor, etc., for example to the rhythm of music （","cn":"用 … ）轻轻叩击"}]}},"tallying":{"oxford":{"phon":"ˈtæli","pos":"noun","senses":[{"en":"a record of the number or amount of sth, especially one that you can keep adding to","cn":"记录；积分表；账"},{"en":"to be the same as or to match another person's account of sth, another set of figures, etc. （","cn":"说法、数字等）与 … 符合（或一致）；吻合"}]}},"tabs":{"oxford":{"phon":"tæb","pos":"noun","senses":[{"en":"a small piece of paper, cloth, metal, etc. that sticks out from the edge of sth, and that is used to give information about it, or to hold it, fasten it, etc.","cn":"标签；签条；突耳；凸舌"},{"en":"a bill for goods you receive but pay for later, especially for food or drinks in a restaurant or bar; the price or cost of sth （","cn":"待付的）账单，账款；（尤指）餐饮账单；费用"}]}},"tasks":{"oxford":{"phon":"tɑːsk","pos":"noun","senses":[{"en":"a piece of work that sb has to do, especially a hard or unpleasant one （","cn":"尤指艰巨或令人厌烦的）任务，工作"},{"en":"an activity which is designed to help achieve a particular learning goal, especially in language teaching （","cn":"尤指语言教学中旨在帮助达到某一学习目的的）活动"}]}},"tatters":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"破烂衣服","en":"Clothes that are in tatters are badly torn in several places, so that pieces can easily come off.","ex":{"en":"His jersey was left in tatters.","cn":"他的运动衫已破烂不堪。"}},{"pos":"N-PLURAL 复数名词","cn":"(计划、心情等)千疮百孔，历经挫折，不堪一击","en":"If you say that something such as a plan or a person's state of mind is in tatters, you are emphasizing that it is weak, has suffered a lot of damage, and is likely to fail completely.","ex":{"en":"The economy is in tatters.","cn":"经济已千疮百孔。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if a plan or someone’s reputation is in tatters, it is ruined 〔","cn":"计划﹑声誉等〕千疮百孔的﹐被毁的"},{"en":"clothes that are in tatters are old and torn 〔","cn":"衣服〕破旧的﹐破烂的"},{"en":"clothing that is old and torn","cn":"破旧的衣服"}]},"collocations":{"phrases":["VERB + TATTERS lie in (figurative) Her marriage now lay in tatters. | hang in Everywhere wallpaper hung in tatters. | leave sth in (figurati","PREP. in ~ Her clothes were in tatters. (figurative) With their plans now in tatters, they gave up.","PHRASES rags and tatters"]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdetatters.mp3","us":"media/ldoce/hwd/ame/0/tatters.mp3"},"examples":[{"en":"The government's education policy lies in tatters.","cn":"政府的教育政策彻底破产了。"},{"en":"His clothes were in tatters.","cn":"他的衣服破旧不堪。"}],"oxford":{"phon":"ˈtætəz","pos":"noun","senses":[{"en":"clothes or pieces of cloth that are badly torn","cn":"破烂的衣服；破衣烂布"}]}},"taillight":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（车辆的）尾灯","en":"The tail-lights on a car or other vehicle are the two red lights at the back.","ex":{"en":"She stood watching the car's tail-lights disappear down the drive.","cn":"她站在那儿，望着小汽车的尾灯消失在车道尽头。"}}]}},"tarragon":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"龙蒿(叶子用作调料)","en":"Tarragon is a European herb with narrow leaves which are used to add flavour to food."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the leaves of a small European plant, used in cooking to give food a special taste","cn":"龙蒿叶〔一种欧洲植物﹐烹调时用于调味〕"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41tarragon.mp3","us":"media/ldoce/hwd/ame/a/tarragon.mp3","img":["media/thumb/tarragon.jpg"]},"examples":[{"en":"chicken with tarragon","cn":"龙蒿叶煮鸡肉"}],"oxford":{"phon":"ˈtærəɡən","pos":"noun","senses":[{"en":"a plant with leaves that have a strong taste and are used in cooking as a herb","cn":"龙蒿（用于烹调）"}]}},"take-up":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"申请率；购买率","en":"Take-up is the rate at which people apply for or buy something which is offered, for example financial help from the government or shares in a company.","ex":{"en":"...a major campaign to increase the take-up of welfare benefits.","cn":"一场声势浩大的旨在增加福利待遇申请、接受率的运动"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the rate at which people accept something that is offered to them","cn":"接受率"}]},"media":{"uk":"media/ldoce/hwd/bre/e/take_up0205.mp3","us":"media/ldoce/hwd/ame/d/ld41take-up.mp3"},"examples":[{"en":"a low take-up of government benefits","cn":"政府救济金的低领取率"},{"en":"Take-up for college places has been slow.","cn":"接受学院录取的比例很低。"}],"oxford":{"phon":"ˈteɪk ʌp","pos":"noun","senses":[{"en":"the rate at which people accept something that is offered or made available to them","cn":"（福利等的）领受率","ex":{"en":"a low take-up of government benefits","cn":"政府救济金的低领取率"}}]}},"tailback":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"交通堵塞;车辆长龙","en":"A tailback is a long line of traffic stretching back along a road, which moves very slowly or not at all, for example because of road works or an accident.","ex":{"en":"The flooding led to six-mile tailbacks between west London and Heathrow Airport.","cn":"洪水导致伦敦西部和希斯罗机场间形成了长达6英里的塞车长龙。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a line of traffic that is moving very slowly or not moving at all 〔","cn":"因交通堵塞而形成的〕车辆长龙"},{"en":"the player who is the furthest back from the front line in American football 〔","cn":"美式橄榄球中的〕殿卫"}]},"media":{"uk":"media/ldoce/hwd/bre/5/tailback0205.mp3","us":"media/ldoce/hwd/ame/1/laadtailback.mp3"},"examples":[{"en":"a five-mile tailback on the M25 25","cn":"号高速公路上长达五英里的塞车长龙"}],"oxford":{"phon":"ˈteɪlbæk","pos":"noun","senses":[{"en":"a long line of traffic that is moving slowly or not moving at all, because something is blocking the road","cn":"（车辆因受阻而排成的）长队，长蛇阵","g":"[countable]","lab":"British English","ex":{"en":"It took a couple of hours for the two-mile tailback to clear.","cn":"两英里长的尾部花了几个小时才清理干净。"}},{"en":"one of the two attacking players in american football whose position is behind the quarterback and next to the full backs; the position a tailback plays at","cn":"尾巴：美式橄榄球中两名进攻球员之一，其位置位于四分卫之后，紧随其后卫；尾巴的位置","g":"[countable, uncountable]","lab":"North American English"}]}},"talkie":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"有声电影","en":"A talkie is a cinema film made with sound, as opposed to a silent film.","ex":{"en":"Garbo made two dozen films, first silent pictures then talkies.","cn":"嘉宝拍过 24 部电影，先是无声的，后是有声的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a film made using sound","cn":"有声电影"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41talkie.mp3","us":"media/ldoce/hwd/ame/1/talkie.mp3"},"oxford":{"phon":"ˈtɔːki","pos":"noun","senses":[{"en":"a film that has sounds and not just pictures","cn":"有声电影"}]}},"tangle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"缠结;纠结;乱糟糟的一团","en":"A tangle of something is a mass of it twisted together in an untidy way.","ex":{"en":"A tangle of wires is all that remains of the computer and phone systems","cn":"原来的计算机和电话系统如今只剩下乱糟糟的一团电线。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)缠绕;(使)缠结","en":"If something is tangled or tangles, it becomes twisted together in an untidy way.","ex":{"en":"Animals get tangled in fishing nets and drown","cn":"动物被缠进渔网里淹死了。"}},{"pos":"N-SING 单数名词","cn":"混乱;纷乱;乱成一团","en":"You can refer to a confusing or complicated situation as a tangle .","ex":{"en":"I was thinking what a tangle we had got ourselves into.","cn":"我在想，我们卷入了怎样的纷争之中。"}},{"pos":"VERB 动词","cn":"(思想、局势变得)纷乱，混乱","en":"If ideas or situations are tangled, they become confused and complicated.","ex":{"en":"The themes get tangled in Mr. Mahfouz's epic storytelling","cn":"马赫福兹先生讲述的故事过于宏大，主题有些混乱了。"}},{"pos":"","cn":"","en":"a tangled web→see: ;"},{"pos":"","cn":"","en":"相关词组：tangle up tangle with"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to become twisted together, or make something become twisted together, in an untidy mass （","cn":"使）缠结在一起﹔（使）乱成一团"},{"en":"to argue or fight with someone 〔","cn":"和…〕争吵﹐打架"},{"en":"a twisted mass of something such as hair or thread 〔","cn":"头发﹑线等〕纠结的一团"}]},"vocab":{"pos":"1 v n 2 v","senses":[{"en":"A tangle is a jumble. You might have a tangle of cords behind your computer or a tangle of complications related to your taxes. Whatever it is, once something is in a tangle , it's difficult to sort out."}]},"collocations":{"phrases":["ADJ. bewildering, confused a confused tangle of voices | dense, matted a dense tangle of undergrowth","VERB + TANGLE get into He got into a tangle with his budget figures. | sort out, unravel The legal tangle was never really unravelled.","PREP. in a ~ This string's in a tangle."]},"media":{"uk":"media/ldoce/hwd/bre/c/tangle_v0205.mp3","us":"media/ldoce/hwd/ame/4/tangle1.mp3"},"examples":[{"en":"She had tangled up the sheets on the bed as she lay tossing and turning.","cn":"她在床上翻来覆去，把被单弄得乱成一团。"},{"en":"Her hair was a mass of tangles.","cn":"她的头发乱糟糟的。"}],"oxford":{"phon":"ˈtæŋɡl","pos":"noun","senses":[{"en":"a twisted mass of threads, hair, etc. that cannot be easily separated","cn":"（线、毛发等的）缠结的一团，乱团，乱糟糟的一堆","lab":"figurative","ex":{"en":"a tangle of branches","cn":"盘绕在一起的树枝"}},{"en":"a lack of order; a confused state","cn":"混乱；纷乱","ex":{"en":"His financial affairs are in a tangle.","cn":"他的财务一塌糊涂。"}},{"en":"a disagreement or fight","cn":"纠纷；不和；争执；打架","lab":"informal"},{"en":"to twist something into an untidy mass; to become twisted in this way","cn":"使缠结；纠结；乱作一团","ex":{"en":"She had tangled up the sheets on the bed as she lay tossing and turning.","cn":"她在床上翻来覆去，把被单弄得乱成一团。"},"pos":"verb"}]}},"tangential":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"关系不大的;不直接相干的","en":"If you describe something as tangential, you mean that it has only a slight or indirect connection with the thing you are concerned with, and is therefore not worth considering seriously.","ex":{"en":"Too much time was spent discussing tangential issues","cn":"太多的时间花在了讨论那些无关紧要的问题上。"}},{"pos":"ADJ 形容词","cn":"切线的;相切的","en":"If something is tangential to something else, it is at a tangent to it.","ex":{"en":"...point T, where the demand curve is tangential to the straight line L.","cn":"需求曲线和直线 L 相切之点 T"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"tangential information, remarks etc are only related to a particular subject in an indirect way 〔","cn":"情况﹑评论等〕不直接相关的﹐关系间接的"}]},"vocab":{"pos":"adj","senses":[{"en":"Tangential refers to something that's not part of the whole. If you make a comment that is tangential to the story you're telling, it's a digression. The story could still be understood without it."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41tangential.mp3","us":"media/ldoce/hwd/ame/f/tangential.mp3"},"examples":[{"en":"a tangential argument","cn":"牵强附会的论点"},{"en":"The matter you raise is rather tangential to this discussion.","cn":"你提出的问题和这次讨论没有多大关系。"}],"oxford":{"phon":"tænˈdʒenʃl","pos":"adjective","senses":[{"en":"having only a slight or indirect connection with something","cn":"稍微沾边的；离题的；不相干的","lab":"formal","ex":{"en":"a tangential argument","cn":"牵强附会的论点"}},{"en":"of or along a tangent","cn":"正切的；切线的","lab":"geometry"}]}},"tauten":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"绷紧;拉紧;(使)(身体某部位)变紧","en":"If a part of your body tautens or if you tauten it, it becomes stiff or firm.","ex":{"en":"Her whole body tautened violently","cn":"她全身紧绷得厉害。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something stretch tight, or to become stretched tight （","cn":"使）拉紧﹐（使）绷紧"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41tauten.mp3","us":"media/ldoce/hwd/ame/6/ld41tauten.mp3"},"oxford":{"phon":"ˈtɔːtn","pos":"verb","senses":[{"en":"to become taut; to make something taut","cn":"（使）拉紧，绷紧","ex":{"en":"Here are some exercises to tauten facial muscles.","cn":"这里有一些可以收紧面部肌肉的练习。"}}]}},"tantamount":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(用于强调非常糟糕、难以接受或不幸)几乎是…，简直是…，无异于…","en":"If you say that one thing is tantamount to a second, more serious thing, you are emphasizing how bad, unacceptable, or unfortunate the first thing is by comparing it to the second.","ex":{"en":"What Bracey is saying is tantamount to heresy","cn":"布雷西的言论简直就是异端邪说。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if an action, suggestion, plan etc is tantamount to something bad, it has the same effect or is almost as bad 〔","cn":"行动﹑建议﹑计划等〕（几乎）等于某（坏）事﹐无异于某（坏）事"}]},"vocab":{"pos":"adj","senses":[{"en":"When something is tantamount to another thing it is essentially its equivalent. For some animal activists, wearing fur is tantamount to murder."}]},"media":{"uk":"media/ldoce/hwd/bre/7/tantamount0205.mp3","us":"media/ldoce/hwd/ame/c/tantamount.mp3"},"examples":[{"en":"If he resigned it would be tantamount to admitting that he was guilty.","cn":"他若辞职就等于承认自己有错。"},{"en":"To leave a dog home alone is tantamount to cruelty.","cn":"把狗独自留在家里等于虐待。"}],"oxford":{"phon":"ˈtæntəmaʊnt","pos":"adjective","senses":[{"en":"having the same bad effect as something else","cn":"无异于；等于；效果与…一样坏","ex":{"en":"If he resigned it would be tantamount to admitting that he was guilty.","cn":"他若辞职就等于承认自己有错。"}}]}},"tannoy":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（在集市或体育场馆内用于播报的）天朗扩音系统","en":"A Tannoy is a system of loudspeakers used to make public announcements, for example at a fair or at a sports stadium."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a system for giving out information in public places using loudspeaker s","cn":"天朗扩音系统〔以扩音器向公众发布消息〕"}]},"media":{"uk":"media/ldoce/hwd/bre/7/tannoy0205.mp3","us":"media/ldoce/hwd/ame/7/ld41tannoy.mp3"},"examples":[{"en":"to make an announcement over the Tannoy","cn":"通过塔诺伊扩音系统发布通知"},{"en":"The train’s approach was announced over the tannoy.","cn":"广播里通知火车就要进站了。"}],"oxford":{"phon":"ˈtænɔɪ","pos":"noun","senses":[{"en":"a system with loudspeakers used for giving information in a public place","cn":"天朗扩音系统","ex":{"en":"to make an announcement over the Tannoy","cn":"通过天朗扩音系统发布通知"}}]}},"taut":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"绷紧的;拉紧的","en":"Something that is taut is stretched very tight.","ex":{"en":"When muscles are taut or cold there is more chance of injury or strain","cn":"肌肉绷紧或受凉时更容易损伤。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肌肉结实的;健美的","en":"If a person or their body is taut, they are very lean with firm muscles.","ex":{"en":"That summer she had shed the weight gained during pregnancy, her body was trim and taut.","cn":"那年夏天，她减去了怀孕期间增加的体重，身材又变得修长而健美。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"忧虑的;紧张的","en":"If someone has a taut expression, they look very worried and tense.","ex":{"en":"Ben sat up quickly, his face taut and terrified","cn":"本一骨碌坐了起来，表情紧张而惊恐。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(文章、电影等)结构严谨的，紧凑的","en":"If you describe a piece of writing or a film as taut, you mean that it is good because it is exciting and has no unnecessary details.","ex":{"en":"...Eric Rochant's 'Aux yeux du monde', a taut thriller about the kidnapping of a school bus.","cn":"艾希·侯相导演的《在世人面前》——一部劫持校车的情节紧凑的惊悚片"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"rope, wire, cloth etc that is tight has been pulled or stretched as far as possible so that it is straight or it cannot move","cn":""},{"en":"stretched very tight","cn":""},{"en":"stretched tight","cn":"拉紧的﹐绷紧的"}]},"vocab":{"pos":"adj","senses":[{"en":"Taut means \"tight, not slack.\" \"The tightrope ought to be taut and not dangling down by the lion cage.\""}]},"collocations":{"phrases":["VERBS be, feel, look | become, go Her body went as taut as a bowstring. | remain, stay Exercise helps your muscles to stay taut. | pull sth,","PREP. with (figurative) a voice taut with anger"]},"media":{"uk":"media/ldoce/hwd/bre/8/taught0205.mp3","us":"media/ldoce/hwd/ame/f/taught.mp3"},"examples":[{"en":"Her face was taut and pale.","cn":"她神色紧张，脸色苍白。"},{"en":"His body was solid and taut.","cn":"他身体结实，肌肉发达。"}],"oxford":{"phon":"tɔːt","pos":"adjective","senses":[{"en":"stretched tightly","cn":"拉紧的；绷紧的","ex":{"en":"taut violin strings","cn":"拉紧的小提琴弦"}},{"en":"showing that you are anxious or tense","cn":"显得焦虑的（或紧张的）","ex":{"en":"a voice taut with anger","cn":"气得发紧的声音"}},{"en":"with hard muscles; not fat","cn":"肌肉结实的；不虚胖的","ex":{"en":"His body was solid and taut.","cn":"他身体结实，肌肉发达。"}},{"en":"carefully written with no unnecessary parts in it","cn":"结构严谨的；紧凑的","ex":{"en":"a taut thriller","cn":"故事紧凑的惊悚小说"}}]}},"tarry":{"collins":{"senses":[{"pos":"VERB 动词","cn":"逗留;停留;徘徊","en":"If you tarry somewhere, you stay there longer than you meant to and delay leaving.","ex":{"en":"Two old boys tarried on the street corner discussing cattle.","cn":"两个大男孩在街角停留许久，一直在讨论牛。"}},{"pos":"ADJ 形容词","cn":"柏油含量高的;像柏油的","en":"If you describe something as tarry, you mean that it has a lot of tar in it or is like tar.","ex":{"en":"I smelled tarry melted asphalt.","cn":"我闻到了柏油熔化了的味道。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to stay in a place, especially when you should leave 〔","cn":"尤指应离开时〕逗留﹐停留﹐徘徊"},{"en":"to delay or be slow in going somewhere","cn":"耽搁﹐拖延"},{"en":"covered with tar (= a thick black liquid )","cn":"涂了柏油的﹐以柏油覆盖的"}]},"vocab":{"pos":"1 v 2 adj","senses":[{"en":"To tarry is to linger and take your time leaving. If you really like going to Sally’s Diner for dessert, you might tarry over coffee and end up leaving after they’ve closed the kitchen."}]},"media":{"uk":"media/ldoce/hwd/bre/a/tarry_v0205.mp3","us":"media/ldoce/hwd/ame/7/l3tarry.mp3"},"oxford":{"phon":"ˈtæri","pos":"verb","senses":[{"en":"to stay in a place, especially when you ought to leave; to delay coming to or going from a place","cn":"逗留；耽搁"}]}},"tactile":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(与人说话时)爱碰别人的，有肢体接触的","en":"If you describe someone as tactile, you mean that they tend to touch other people a lot when talking to them.","ex":{"en":"The children are very tactile with warm, loving natures.","cn":"小孩子说话时喜欢用上热烈、表达喜爱的肢体触碰。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(织物等)手感好的","en":"Something such as fabric which is tactile is pleasant or interesting to touch.","ex":{"en":"Tweed is timeless, tactile and tough.","cn":"粗花呢从不过时，手感很好，结实耐磨。"}},{"pos":"ADJ 形容词","cn":"(经验、感觉)触觉的，通过触觉获得的","en":"Tactile experiences or sensations are received or felt by touch.","ex":{"en":"Babies who sleep with their parents receive much more tactile stimulation than babies who sleep in a cot","cn":"婴儿和父母睡在一块儿比单独睡在婴儿床中能得到更多的触觉刺激。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to your sense of touch","cn":"触觉的"},{"en":"a tactile person likes to touch people, for example when talking to them 〔","cn":"和人谈话等的时候〕爱碰触他人的"}]},"vocab":{"pos":"adj","senses":[{"en":"Tactile has to do with the sense of touch. There's a huge tactile difference between smooth glass and rough sandpaper."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41tactile.mp3","us":"media/ldoce/hwd/ame/3/tactile.mp3"},"examples":[{"en":"He's a very tactile man (= he enjoys touching people).","cn":"他这个人非常爱抚摸他人。"},{"en":"tactile fabric (= pleasant to touch)","cn":"手感好的织物"}],"oxford":{"phon":"ˈtæktaɪl","pos":"adjective","senses":[{"en":"connected with the sense of touch; using your sense of touch","cn":"触觉的；有触觉的；能触知的","ex":{"en":"tactile stimuli","cn":"触觉刺激"}}]}},"tasteless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(家具、服装、房屋装修等)俗气的，难看的，没品位的","en":"If you describe something such as furniture, clothing, or the way that a house is decorated as tasteless, you consider it to be vulgar and unattractive.","ex":{"en":"...a flat crammed with spectacularly tasteless objets d'art.","cn":"摆满了俗不可耐的小艺术品的公寓"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(话语、玩笑等)粗俗的，不雅的，不得体的","en":"If you describe something such as a remark or joke as tasteless, you mean that it is offensive.","ex":{"en":"I think that is the most vulgar and tasteless remark I ever heard in my life.","cn":"我觉得那是我平生听过的最粗俗不堪的话了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(食物、饮料)淡而无味的，没滋味的","en":"If you describe food or drink as tasteless, you mean that it has very little or no flavour.","ex":{"en":"The fish was mushy and tasteless.","cn":"鱼做得太烂了，没滋没味的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"food that is tasteless has little or no taste and is rather unpleasant","cn":""},{"en":"food or drink that is bland has very little taste and is not interesting to eat or drink","cn":""},{"en":"to have very little taste - use this especially when you think something should have more taste","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/tasteless0205.mp3","us":"media/ldoce/hwd/ame/f/tasteless.mp3"},"examples":[{"en":"tasteless soup","cn":"淡而无味的汤"},{"en":"tasteless jokes","cn":"粗俗的笑话"}],"oxford":{"phon":"ˈteɪstləs","pos":"adjective","senses":[{"en":"having little or no taste","cn":"寡淡的；无味的；不可口的","ex":{"en":"tasteless soup","cn":"淡而无味的汤"}},{"en":"offensive and not appropriate","cn":"不雅的；粗俗的；不得体的；煞风景的","ex":{"en":"tasteless jokes","cn":"粗俗的笑话"}},{"en":"showing a lack of the ability to choose things that people recognize as attractive and of good quality","cn":"俗气的；格调低的","ex":{"en":"The sculpture seemed tasteless and vulgar to her.","cn":"这座雕塑在她看来索然无味、庸俗不堪。"}}]}},"tattle":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to talk about other people’s private lives","cn":"说闲话﹔谈论他人隐私"},{"en":"if a child tattles, they tell a parent or teacher that another child has done something bad 〔","cn":"小孩〕打小报告"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41tattle.mp3","us":"media/ldoce/hwd/ame/e/tattle.mp3"},"examples":[{"en":"Robert is always tattling on me for things I didn’t do.","cn":"罗伯特总是乱打我的小报告。"}],"oxford":{"phon":"ˈtætl","pos":"verb","senses":[{"en":"to tell somebody, especially somebody in authority, about something bad that somebody else has done","cn":"（向当权者）告发；（就某人不端行为）打小报告","ex":{"en":"You should learn that you just don’t tattle on classmates.","cn":"你应该认识到你不该打同学们的小报告。"}}]}},"tambourine":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手鼓;铃鼓","en":"A tambourine is a musical instrument which you shake or hit with your hand. It consists of a drum skin on a circular frame with pairs of small round pieces of metal all around the edge."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a circular musical instrument consisting of a frame covered with skin or plastic and small pieces of metal that hang around the edge. You shake it or hit it with your hand.","cn":"铃鼓"}]},"media":{"img":["media/ldoce/img/tambourine.jpg","media/thumb/tambourine.jpg"],"uk":"media/ldoce/hwd/bre/8/tambourine0205.mp3","us":"media/ldoce/hwd/ame/7/tambourine.mp3"},"oxford":{"phon":"ˌtæmbəˈriːn","pos":"noun","senses":[{"en":"a musical instrument that has a round wooden frame, sometimes covered with plastic or skin, with metal discs around the edge. To play it you shake it or hit it with your hand.","cn":"铃鼓（蒙有塑料或皮面，鼓帮装有金属圆片，摇动或用手击打发声）"}]}},"tapestry":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"挂毯;壁毯;织锦;花毯","en":"A tapestry is a large piece of heavy cloth with a picture sewn on it using coloured threads.","ex":{"en":"The seats of the chairs had been recovered in tapestry","cn":"椅座上又铺回了花毯。"}},{"pos":"N-COUNT 可数名词","cn":"各式各样的人(或物)","en":"You can refer to something as a tapestry when it is made up of many varied types of people or things.","ex":{"en":"Hedgerows and meadows are thick with a tapestry of wild flowers.","cn":"灌木树篱和草地中开满了五彩缤纷的野花。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large piece of heavy cloth on which coloured threads are woven to produce a picture, pattern etc","cn":"挂毯﹐壁毯"},{"en":"something that is made up of many different people and things","cn":"丰富多彩的画面"}]},"vocab":{"pos":"n","senses":[{"en":"A tapestry is a picture woven into cloth. It's a decorative rug you hang on the wall, with detailed images or designs on it. Some tapestries, like the famous Unicorn Tapestries, tell stories with their pictures."}]},"media":{"uk":"media/ldoce/hwd/bre/0/tapestry0205.mp3","us":"media/ldoce/hwd/ame/f/tapestry.mp3"},"examples":[{"en":"crafts such as embroidery and tapestry","cn":"诸如刺绣和织锦之类的手工艺"},{"en":"tapestry cushions","cn":"织锦沙发靠背垫"}],"oxford":{"phon":"ˈtæpəstri","pos":"noun","senses":[{"en":"a picture or pattern that is made by weaving coloured wool onto heavy cloth; the art of doing this","cn":"壁毯；挂毯；织锦；绣帷","ex":{"en":"medieval tapestries","cn":"中世纪的壁毯"}}]}},"tasselled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"饰有穗(或缨、流苏)的","en":"Tasselled means decorated with tassels.","ex":{"en":"...tasselled cushions.","cn":"带流苏的垫子"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"threads tied together at one end and hung as a decoration on clothes, curtains etc","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/tassel0205.mp3","us":"media/ldoce/hwd/ame/5/tassel.mp3"},"oxford":{"phon":"ˈtæsld","pos":"adjective","senses":[{"en":"decorated with tassels","cn":"饰有流苏的；带穗的；有缨的"}]}},"tango":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"探戈(舞)","en":"The tango is a South American dance in which two people hold each other closely, walk quickly in one direction, then walk quickly back again."},{"pos":"N-VAR 可变名词","cn":"探戈舞曲","en":"A tango is a piece of music intended for tango dancing.","ex":{"en":"A tango was playing on the jukebox","cn":"点唱机播放着一首探戈舞曲。"}},{"pos":"VERB 动词","cn":"跳探戈舞","en":"If you tango, you dance the tango. it takes two to tango→see: ;","ex":{"en":"They can rock and roll, they can tango, but they can't bop.","cn":"他们会跳摇滚，会跳探戈，就是不会跳博普舞。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a fast dance from South America, or a piece of music for this dance","cn":"探戈舞﹔探戈舞曲"},{"en":"to dance the tango","cn":"跳探戈舞"},{"en":"used to say that if a problem involves two people, then both people are equally responsible","cn":"探戈舞得两个人跳﹔一个巴掌拍不响﹔双方都有责任"}]},"vocab":{"pos":"n v","senses":[{"en":"The noun tango usually refers to the Argentine tango , a dramatic ballroom dance, and the expressive music that goes along with it."}]},"media":{"uk":"media/ldoce/hwd/bre/8/tango_n0205.mp3","us":"media/ldoce/hwd/ame/c/tango1.mp3"},"oxford":{"phon":"ˈtæŋɡəʊ","pos":"noun","senses":[{"en":"a fast South American dance with a strong beat, in which two people hold each other closely; a piece of music for this dance","cn":"探戈舞；探戈舞曲"},{"en":"to dance the tango","cn":"跳探戈舞","pos":"verb"}]}},"taciturn":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"寡言少语的;沉默寡言的;不苟言笑的","en":"A taciturn person does not say very much and can seem unfriendly.","ex":{"en":"A taciturn man, he replied to my questions in monosyllables.","cn":"他寡言少语，回答我的问题时只是往外蹦单字。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not saying much","cn":""},{"en":"not saying anything","cn":""},{"en":"not talking much and seeming a little unfriendly or bad-tempered","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Someone who is taciturn is reserved, not loud and talkative. The word itself refers to the trait of reticence, of seeming aloof and uncommunicative. A taciturn person might be snobby, naturally quiet, or just shy."}]},"media":{"uk":"media/ldoce/hwd/bre/6/taciturn0205.mp3","us":"media/ldoce/hwd/ame/c/taciturn.mp3"},"oxford":{"phon":"ˈtæsɪtɜːn","pos":"adjective","senses":[{"en":"tending not to say very much, in a way that seems unfriendly","cn":"不苟言笑的；沉默寡言的；缄默不语的","ex":{"en":"a taciturn and serious young man","cn":"一个沉默寡言而严肃的年轻人"}}]}},"tasty":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"味道鲜美的;可口的","en":"If you say that food, especially savoury food, is tasty, you mean that it has a fairly strong and pleasant flavour which makes it good to eat.","ex":{"en":"Try this tasty dish for supper with a crispy salad","cn":"晚饭就着鲜脆的色拉尝尝这道佳肴。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指女子)迷人的，性感的","en":"If someone describes a person, especially a woman, as tasty, they think they are sexually desirable."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a very good taste","cn":""},{"en":"having a very bad taste","cn":""},{"en":"tasting full of sugar","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/tasty0205.mp3","us":"media/ldoce/hwd/ame/6/tasty.mp3"},"examples":[{"en":"something tasty to eat","cn":"好吃的东西"},{"en":"a tasty meal","cn":"美餐"}],"oxford":{"phon":"ˈteɪsti","pos":"adjective","senses":[{"en":"having a strong and pleasant taste when it is eaten","cn":"美味的；可口的；好吃的","lab":"approving","ex":{"en":"a tasty meal","cn":"美餐"}},{"en":"sexually attractive","cn":"性感的","lab":"British English, informal, sometimes offensive，，，，"}]}},"tabby":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"斑猫（毛皮上有深色条纹）","en":"A tabby or a tabby cat is a cat whose fur has dark stripes on a lighter background."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a cat with light and dark lines on its fur","cn":"虎斑猫〔毛皮上有深浅条纹的一种猫〕"}]},"vocab":{"pos":"adj n","senses":[{"en":"A tabby is a house cat with stripes on its fur, often in browns and grays. There are different breeds of tabby cats. Occasionally one will dangle off a branch under a caption that says, “Hang in there.”"}]},"media":{"uk":"media/ldoce/hwd/bre/0/tabby0205.mp3","us":"media/ldoce/hwd/ame/b/tabby.mp3"},"oxford":{"phon":"ˈtæbi","pos":"noun","senses":[{"en":"a cat with brown or grey fur marked with dark lines or spots","cn":"斑猫（毛皮褐色或灰色，带有深色斑纹或斑点）"}]}},"tarantula":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"狼蛛;塔兰托毒蛛","en":"A tarantula is a large hairy spider which has a poisonous bite."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large poisonous spider from Southern Europe and tropical America","cn":"塔兰托毒蛛〔见于南欧及热带美洲的一种有毒大蜘蛛〕"}]},"vocab":{"pos":"n","senses":[{"en":"A tarantula is a hairy, poisonous, black spider. Although they are furry and some people keep them as pets, you probably don't want to cuddle up to one."}]},"media":{"img":["media/ldoce/img/tarantula.jpg"],"uk":"media/ldoce/hwd/bre/5/tarantula0205.mp3","us":"media/ldoce/hwd/ame/e/tarantula.mp3"},"oxford":{"phon":"təˈræntʃələ","pos":"noun","senses":[{"en":"a large poisonous spider covered with hair that lives in Central and South America","cn":"塔兰托毒蛛，捕鸟蛛（生活在中南美洲）"}]}},"tan":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"晒黑的皮肤","en":"If you have a tan, your skin has become darker than usual because you have been in the sun.","ex":{"en":"She is tall and blonde, with a permanent tan.","cn":"她高个儿，一头金发，皮肤黝黑。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(皮肤)晒黑","en":"If a part of your body tans or if you tan it, your skin becomes darker than usual because you spend a lot of time in the sun.","ex":{"en":"I have very pale skin that never tans","cn":"我皮肤很白，怎么也晒不黑。"}},{"pos":"COLOUR 颜色词","cn":"棕黄色;黄褐色","en":"Something that is tan is a light brown colour.","ex":{"en":"...a tan leather jacket.","cn":"棕黄色皮夹克"}},{"pos":"VERB 动词","cn":"鞣(革);硝(皮)","en":"To tan animal skins means to make them into leather by treating them with tannin or other chemicals.","ex":{"en":"...the process of tanning animal hides.","cn":"鞣革的过程"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you tan, or if the sun tans you, your skin becomes darker because you spend time in the sun （","cn":"使）〔皮肤〕晒黑"},{"en":"to make animal skin into leather by treating it with tannin (= a kind of acid )","cn":"鞣﹐硝〔皮革〕"},{"en":"the attractive brown colour that someone with pale skin gets after they have been in the sun 〔","cn":"被太阳晒成的〕棕褐色肤色"}]},"collocations":{"phrases":["ADJ. deep, golden | healthy | all-over | fake","VERB + TAN have | show off, sport Show off your tan in this little white top. | get, top up, work on I want to top up my tan on the sunbed a","PREP. against your ~ His teeth were a gleaming flash of white against his tan."]},"media":{"uk":"media/ldoce/hwd/bre/9/tan_v0205.mp3","us":"media/ldoce/hwd/ame/5/tan1.mp3"},"examples":[{"en":"to get a tan","cn":"晒黑"},{"en":"She has a pale skin which doesn’t tan easily.","cn":"她的肤色很白﹐不容易被晒黑。"}],"oxford":{"phon":"tæn","pos":"verb","senses":[{"en":"if a person or their skin tans or is tanned, they become brown as a result of spending time in the sun","cn":"（使）晒成褐色，晒黑","g":"[intransitive, transitive]","ex":{"en":"My skin tans really easily.","cn":"我的皮肤真的很容易晒黑。"}},{"en":"to make animal skin into leather by treating it with chemicals","cn":"鞣（革）；硝（皮）","g":"[transitive]"},{"en":"a yellow-brown colour","cn":"棕黄色；黄褐色","g":"[uncountable]","pos":"noun"},{"en":"the brown colour that somebody with pale skin goes when they have been in the sun","cn":"晒成棕褐肤色；晒成的棕褐色","g":"[countable]","ex":{"en":"to get a tan","cn":"晒黑"},"pos":"noun"},{"en":"yellow-brown in colour","cn":"棕褐色的；棕黄色的","pos":"adjective"},{"en":"tangent","cn":"正切","pos":"abbreviation"}]}},"tabulate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"将…制成表格;以表格形式排列","en":"To tabulate information means to arrange it in columns on a page so that it can be analysed.","ex":{"en":"...methods of collecting, tabulating and analysing numerical data","cn":"搜集信息、列表和分析数据的各种方法"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to arrange figures or information together in a set or a list, so that they can be easily compared","cn":"把…制成表格﹔以表格形式排列〔数字﹑资料等〕"}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"To tabulate information is to organize it into a table. If your friend borrows money from you every week, you might want to tabulate what she owes you."}]},"media":{"uk":"media/ldoce/hwd/bre/2/tabulate0205.mp3","us":"media/ldoce/hwd/ame/c/tabulate.mp3"},"oxford":{"phon":"ˈtæbjuleɪt","pos":"verb","senses":[{"en":"to arrange facts or figures in columns or lists so that they can be read easily","cn":"列成表格；列表显示","ex":{"en":"The survey results are tabulated in section 9 of Appendix 1.","cn":"调查结果列于附录 1 第 9 节。"}}]}},"tannin":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"丹宁酸，鞣酸(用于制革、染色)","en":"Tannin is a yellow or brown chemical that is found in plants such as tea. It is used in the process of making leather and in dyeing."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a reddish acid used in preparing leather, making ink etc","cn":"单宁（酸）﹐鞣酸〔用于制革﹑制造墨水等〕"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41tannin.mp3","us":"media/ldoce/hwd/ame/0/tannin.mp3"},"oxford":{"phon":"ˈtænɪn","pos":"noun","senses":[{"en":"a yellow or brown substance found in the bark of some trees and the fruit of many plants, which is present in wine and tea and used in making leather","cn":"单宁；单宁酸；鞣质"}]}},"taxing":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(任务或难题)费力的，费劲的，劳神的","en":"A taxing task or problem is one that requires a lot of mental or physical effort.","ex":{"en":"They were comparing notes on each other's progress towards solving that most taxing of all puzzles: the riddle of the human genome","cn":"他们就解决人类所面临的最大难题，即人类基因组之谜的进展情况交换了意见。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a challenging job or activity needs a lot of hard work and skill, but it is also interesting and enjoyable","cn":""},{"en":"if a new job or activity is a challenge , it is difficult, but you are determined to do it because it is interesting and exciting","cn":""},{"en":"a demanding job or activity is very difficult and tiring, because it needs all your effort and skill","cn":""}]},"collocations":{"phrases":["VERBS be, prove | become","ADV. very | fairly | intellectually, physically There was nothing intellectually taxing about the course."]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdetaxing.mp3","us":"media/ldoce/hwd/ame/d/taxing.mp3"},"examples":[{"en":"This shouldn't be too taxing for you.","cn":"这对你来说不至于太费劲。"},{"en":"a taxing job","cn":"繁重的工作"}],"oxford":{"phon":"ˈtæksɪŋ","pos":"adjective","senses":[{"en":"needing a great amount of physical or mental effort","cn":"繁重的；费力的；伤脑筋的","ex":{"en":"a taxing job","cn":"繁重的工作"}}]}},"taint":{"collins":{"senses":[{"pos":"VERB 动词","cn":"玷污，毁坏，损害，败坏(地位、名誉)","en":"If a person or thing is tainted by something bad or undesirable, their status or reputation is harmed because they are associated with it.","ex":{"en":"Opposition leaders said that the elections had been tainted by corruption.","cn":"反对派领导人说，选举中存在舞弊现象。"}},{"pos":"N-COUNT 可数名词","cn":"(地位、名誉的)玷污，污点，瑕疵","en":"A taint is an undesirable quality which spoils the status or reputation of someone or something.","ex":{"en":"Her government never really shook off the taint of corruption","cn":"她的政府从来没有真正摆脱掉腐败的阴影。"}},{"pos":"VERB 动词","cn":"污染，毁坏(食品、药品)","en":"If an unpleasant substance taints food or medicine, the food or medicine is spoiled or damaged by it.","ex":{"en":"Rancid oil will taint the flavour.","cn":"变质的油会破坏味道。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a situation or person is tainted by something, it damages them by making them seem bad","cn":"使受负面影响﹔玷污﹐败坏〔某人的名誉〕"},{"en":"to damage something by adding an unwanted substance to it","cn":"污染﹐沾污"},{"en":"the appearance of being related to something bad or morally wrong","cn":"污点﹐瑕疵﹔玷污"}]},"vocab":{"pos":"v n","senses":[{"en":"Taint means to contaminate. If your water supply is tainted with arsenic, you should stop drinking it right away."}]},"media":{"uk":"media/ldoce/hwd/bre/0/taint_v0205.mp3","us":"media/ldoce/hwd/ame/a/taint1.mp3"},"examples":[{"en":"The administration was tainted with scandal.","cn":"丑闻使得政府声名狼藉。"},{"en":"to be free from the taint of corruption","cn":"不受腐败影响"}],"oxford":{"phon":"teɪnt","pos":"verb","senses":[{"en":"to damage or harm the quality of something or the opinion that people have of somebody/something","cn":"使腐坏；污染；玷污，败坏（名声）","ex":{"en":"The administration was tainted with scandal.","cn":"丑闻使得政府声名狼藉。"}},{"en":"the effect of something bad or unpleasant that damages or harms the quality of somebody/something","cn":"腐坏；污染；玷污","ex":{"en":"to be free from the taint of corruption","cn":"不受腐败影响"},"pos":"noun"}]}},"taoism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(中国的)道教","en":"Taoism is a Chinese religious philosophy which believes that people should lead a simple honest life and not interfere with the course of natural events."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a way of thought developed in ancient China, based on the writings of Lao Tzu, emphasizing a natural and simple way of life","cn":"道家学说"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41taoism.mp3","us":"media/ldoce/hwd/ame/5/taoism.mp3"},"oxford":{"phon":"ˈdaʊɪzəm","pos":"noun","senses":[{"en":"a Chinese philosophy based on the writings of Lao-tzu","cn":"道家"}]}},"tandem":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"双人自行车","en":"A tandem is a bicycle designed for two riders, on which one rider sits behind the other."},{"pos":"PHRASE 短语","cn":"与…同时(发生)","en":"If one thing happens or is done in tandem with another thing, the two things happen at the same time.","ex":{"en":"Malcolm's contract will run in tandem with his existing one.","cn":"马尔科姆的合同将与他手头的合同同时生效。"}},{"pos":"PHRASE 短语","cn":"与…协作;配合","en":"If one person does something in tandem with another person, the two people do it by working together.","ex":{"en":"He is working in tandem with officials of the Serious Fraud Office.","cn":"他正配合欺诈重案办公室的官员工作。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a bicycle built for two riders sitting one behind the other","cn":"双人自行车"},{"en":"doing something together or at the same time as someone or something else","cn":"协同工作﹐一起工作"}]},"vocab":{"pos":"n adv","senses":[{"en":"Tandem describes an arrangement where people or animals are in formation, one behind the other. Couples attached at the hip sometimes like to ride tandem bicycles, which allow two people to pedal the same bike. How cute."}]},"media":{"uk":"media/ldoce/hwd/bre/4/tandem0205.mp3","us":"media/ldoce/hwd/ame/d/tandem.mp3","img":["media/thumb/tandem.jpg"]},"examples":[{"en":"The two companies often work in tandem.","cn":"两家公司经常合作。"},{"en":"The group operated in tandem with local criminals.","cn":"该团体和当地的犯罪分子勾结在一起。"}],"oxford":{"phon":"ˈtændəm","pos":"noun","senses":[{"en":"a bicycle for two riders, one behind the other","cn":"双座自行车；双人自行车"}]}},"taxpayer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"纳税人","en":"Taxpayers are people who pay a percentage of their income to the government as tax."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"money that you have to pay to the government, especially from the money you earn or as an additional payment when you buy something","cn":""},{"en":"a tax you pay on something you buy, especially goods you have bought in another country","cn":""},{"en":"a tax on goods coming into a country or going out of a country","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/taxpayer0205.mp3","us":"media/ldoce/hwd/ame/8/taxpayer.mp3"},"examples":[{"en":"The proposal could cost the taxpayer (= all ordinary people who pay tax ) another £18m a year.","cn":"该提议也许又要让纳税人一年多交1,800万英镑的税。"}],"oxford":{"phon":"ˈtækspeɪə(r)","pos":"noun","senses":[{"en":"a person who pays tax to the government, especially on the money that they earn","cn":"纳税人","ex":{"en":"Hundreds of thousands of pounds of taxpayers' money (= money paid in taxes) have been spent on the project.","cn":"纳税人数十万英镑的钱被花在了这个工程上。"}}]}},"tangy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(味道)浓烈的;(气味)浓重的","en":"A tangy flavour or smell is one that is sharp, especially a flavour like that of lemon juice or a smell like that of sea air."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"food that is sour , especially fruit, has a taste that stings your tongue slightly, like a lemon does","cn":""},{"en":"fruits that are tart , especially apples, sting your tongue and make water come into your mouth","cn":""},{"en":"having a strong but pleasant taste that stings your tongue","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41tang.mp3","us":"media/ldoce/hwd/ame/9/tang1.mp3"},"examples":[{"en":"a refreshing tangy lemon flavour","cn":"清新浓郁的柠檬香味"},{"en":"The beer had a sharp, bitter tang.","cn":""}],"oxford":{"phon":"ˈtæŋi","pos":"adjective","senses":[{"en":"having a strong sharp taste or smell","cn":"强烈味道；刺鼻气味","ex":{"en":"a refreshing tangy lemon flavour","cn":"提神的浓烈柠檬香味"}}]}},"tarn":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"山中小湖","en":"A tarn is a small lake in an area of mountains."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small lake among mountains","cn":"冰斗湖﹔山中小湖"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41tarn2.mp3","us":"media/ldoce/hwd/ame/9/ld41tarn2.mp3"},"oxford":{"phon":"tɑːn","pos":"noun","senses":[{"en":"a small lake in the mountains","cn":"冰川湖；山中小湖","ex":{"en":"A short climb from the tarn leads to the ridge wall.","cn":"从塔恩出发，攀登一小段路即可到达山脊墙。"}}]}},"takings":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"(企业一定时期的)销售额，收入","en":"You can use takings to refer to the amount of money that a business such as a shop or a cinema gets from selling its goods or tickets during a particular period.","ex":{"en":"The pub said that their takings were fifteen to twenty thousand pounds a week.","cn":"这家酒馆说，它一周的营业额在 1.5 万到 2 万英镑之间。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"money that you gain by selling things or doing business, after your costs have been paid","cn":""},{"en":"the profit that a company makes","cn":""},{"en":"the profit that you get from an investment","cn":""}]},"collocations":{"phrases":["ADJ. the day's, the month's, etc. | weekly | gross, net | cash | record Store managers are predicting record takings this Christmas. | bar, ","VERB + TAKINGS add up, check, count (up) | boost The shop's new look has boosted its takings considerably. | cut","TAKINGS + VERB be up/down, drop, rise Box office takings are up by 40% on last year.","PREP. in ~ She was losing about &pound; 100 a week in takings. | ~ from the takings from wines and beers •"]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdetakings.mp3","us":"media/ldoce/hwd/ame/9/amelasdetakings.mp3"},"examples":[{"en":"The box office takings are up on last week.","cn":"票房收入较上星期有所增长。"}],"oxford":{"phon":"ˈteɪkɪŋz","pos":"noun","senses":[{"en":"the amount of money that a shop, theatre, etc. receives from selling goods or tickets over a particular period of time","cn":"（某一时期的）进账，票房收入","ex":{"en":"The box office takings are up on last week.","cn":"票房收入较上星期有所增长。"}}]}},"tangent":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"切线","en":"A tangent is a line that touches the edge of a curve or circle at one point, but does not cross it."},{"pos":"PHRASE 短语","cn":"突然偏离原来的思路;突然离题","en":"If someone goes off at a tangent, they start saying or doing something that is not directly connected with what they were saying or doing before.","ex":{"en":"The conversation went off at a tangent.","cn":"交谈突然偏离了正题。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to suddenly start thinking or talking about a subject that is only slightly related, or not related at all, to the original subject","cn":"突然离开原来的思路﹔突然离题"},{"en":"a straight line that touches the outside of a curve but does not cut across it","cn":"切线"}]},"vocab":{"pos":"n","senses":[{"en":"A tangent is an entirely different topic or direction. When you want a break from geometry class, you might ask your teacher about his hobby of woodworking, a topic that's always good for a ten-minute tangent ."}]},"media":{"uk":"media/ldoce/hwd/bre/b/tangent0205.mp3","us":"media/ldoce/hwd/ame/6/tangent.mp3"},"examples":[{"en":"Let’s stay with the topic and not go off at a tangent.","cn":"我们还是继续讨论正题吧﹐不要离题。"}],"oxford":{"phon":"ˈtændʒənt","pos":"noun","senses":[{"en":"a straight line that touches the outside of a curve but does not cross it","cn":"切线","lab":"geometry","ex":{"en":"The cart track branches off at a tangent.","cn":"车轨在切线处分叉。"}},{"en":"the ratio of the length of the side opposite an angle in a right-angled triangle to the length of the side next to it","cn":"正切","lab":"mathematics"}]}},"tacky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"做工粗糙的;劣质的;俗气的","en":"If you describe something as tacky, you dislike it because it is cheap and badly made or vulgar.","ex":{"en":"...a woman in a fake leopard-skin coat and tacky red sunglasses","cn":"身穿假豹皮大衣、戴着俗气的大红色太阳镜的女人"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(油漆、胶水)发黏的，未干的","en":"If something such as paint or glue is tacky, it is slightly sticky and not yet dry.","ex":{"en":"Test to see if the finish is tacky, and if it is, leave it to harden.","cn":"看看最后一道漆干了没有，要是没干，就先让它干透。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not made or chosen with good taste","cn":""},{"en":"not chosen with taste - use this about things that cost a lot of money or are very brightly coloured, and are bought to impress people","cn":""},{"en":"unattractive, of poor quality, and showing a lack of good taste","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Things that are tacky are cheap, flashy, garish, gaudy, loud, tawdry, or trashy. Tacky clothes are a fashion nightmare, and tacky comments are embarrassing for everyone involved."}]},"media":{"uk":"media/ldoce/hwd/bre/6/tacky0205.mp3","us":"media/ldoce/hwd/ame/2/tacky.mp3"},"examples":[{"en":"The movie had a really tacky ending.","cn":"这部电影的结尾真差劲。"},{"en":"tacky souvenirs","cn":"蹩脚的纪念品"}],"oxford":{"phon":"ˈtæki","pos":"adjective","senses":[{"en":"cheap, badly made and/or not in good taste","cn":"低劣的；蹩脚的；俗气的；乏味的","lab":"informal","ex":{"en":"tacky souvenirs","cn":"蹩脚的纪念品"}},{"en":"not dry and therefore slightly sticky","cn":"未干透的；发黏的"}]}},"tarp":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(防水)帆布，油布","en":"A tarp is a sheet of heavy waterproof material that is used as a protective cover."}]}},"tartar":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"牙垢;牙石","en":"Tartar is a hard yellowish substance that forms on your teeth and causes them to decay if it is not removed."},{"pos":"N-COUNT 可数名词","cn":"凶悍的人，脾气暴戾的人;(尤指)悍妇","en":"If you describe someone, especially a woman in a position of authority, as a tartar, you mean that they are fierce, bad-tempered, and strict.","ex":{"en":"She can be quite a tartar.","cn":"她有时真是个悍妇。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a hard substance that forms on your teeth","cn":"牙石﹐牙垢"},{"en":"someone who has a violent temper","cn":"凶悍的人﹐脾气暴戾的人"}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"Tartar is the buildup of plaque that can form on your teeth and cause cavities. If you become a dentist one day, part of your job will be scraping tartar off people's teeth."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41tartar.mp3","us":"media/ldoce/hwd/ame/b/tartar1.mp3"},"examples":[{"en":"She’s a real tartar.","cn":"她真是一个悍妇。"}],"oxford":{"phon":"ˈtɑːtə(r)","pos":"noun","senses":[{"en":"a hard substance that forms on teeth","cn":"牙石；牙垢","g":"[uncountable]","ex":{"en":"a build-up of tartar","cn":"牙垢堆积"}},{"en":"a person in a position of authority who is strict and easily made angry","cn":"暴君；脾气暴躁的掌权者","g":"[countable]","lab":"old-fashioned"}]}},"tawdry":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"廉价的;俗气的","en":"If you describe something such as clothes or decorations as tawdry, you mean that they are cheap and show a lack of taste.","ex":{"en":"...tawdry jewellery.","cn":"廉价珠宝"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(故事、事件)令人讨厌的，卑鄙的，不道德的","en":"If you describe something such as a story or an event as tawdry, you mean that it is unpleasant or immoral.","ex":{"en":"...the yawning gulf between her fantasies and the tawdry reality.","cn":"她的幻想和冷酷的现实之间的巨大差距"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"cheaply and badly made","cn":"廉价的﹐不值钱的﹔制作粗糙的"},{"en":"showing low moral standards","cn":"粗俗的﹔下流的﹔卑鄙的﹔卑污的"}]},"vocab":{"pos":"adj","senses":[{"en":"Tawdry means cheap, shoddy, or tasteless. It can be used to describe almost anything from clothes to people to even events or affairs."}]},"media":{"uk":"media/ldoce/hwd/bre/b/tawdry0205.mp3","us":"media/ldoce/hwd/ame/3/tawdry.mp3"},"examples":[{"en":"tawdry jewellery","cn":"俗丽便宜的首饰"},{"en":"a tawdry affair","cn":"卑鄙下流的勾当"}],"oxford":{"phon":"ˈtɔːdri","pos":"adjective","senses":[{"en":"intended to be bright and attractive but cheap and of low quality","cn":"俗丽而不值钱的；俗气的；花里胡哨的","ex":{"en":"tawdry jewellery","cn":"俗丽便宜的首饰"}},{"en":"involving low moral standards; extremely unpleasant or offensive","cn":"粗俗的；下流的；卑鄙的；卑污的","ex":{"en":"a tawdry affair","cn":"卑鄙下流的勾当"}}]}},"talisman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"护身符;避邪物","en":"A talisman is an object which you believe has magic powers to protect you or bring you luck."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an object that is believed to have magic powers to protect the person who owns it","cn":"驱邪物﹐护身符"}]},"vocab":{"pos":"n","senses":[{"en":"A talisman is a charm that is supposed to ward off evil or illness. Your rabbit's foot key chain may be your lucky talisman , but it wasn't so lucky for that rabbit, of course."}]},"media":{"uk":"media/ldoce/hwd/bre/a/talisman0205.mp3","us":"media/ldoce/hwd/ame/0/talisman.mp3"},"oxford":{"phon":"ˈtælɪzmən","pos":"noun","senses":[{"en":"an object that is thought to have magic powers and to bring good luck","cn":"护身符；驱邪物"}]}},"tanker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(运输大量气体或液体的)巨轮;(尤指)油轮","en":"A tanker is a very large ship used for transporting large quantities of gas or liquid, especially oil.","ex":{"en":"A Greek oil tanker has run aground.","cn":"一艘希腊油轮搁浅了。"}},{"pos":"N-COUNT 可数名词","cn":"大卡车;铁路罐车;运输机","en":"A tanker is a large truck, railway vehicle, or aircraft used for transporting large quantities of a substance.","ex":{"en":"...an accident involving a petrol tanker on the M27, east of Southampton.","cn":"在南安普敦以东的 27 号高速公路上发生的一起车祸，其中有一辆油罐车"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a vehicle or ship specially built to carry large quantities of gas or liquid, especially oil","cn":"油罐车﹔油船﹐油轮"}]},"collocations":{"phrases":["ADJ. giant, huge, large | gas, oil | coastal","TANKER + VERB carry sth, transport sth a tanker carrying thousands of tons of crude oil | run aground The tanker ran aground in heavy seas a","TANKER + NOUN disaster, spill the worst year for tanker spills for ten years | fleet | route | traffic | operator, owner 2 heavy vehicle for","ADJ. fuel, milk, petrol | road","VERB + TANKER drive","TANKER + VERB carry sth","TANKER + NOUN driver"]},"media":{"uk":"media/ldoce/hwd/bre/b/tanker0205.mp3","us":"media/ldoce/hwd/ame/5/tanker.mp3","img":["media/thumb/tanker.jpg"]},"examples":[{"en":"an oil tanker","cn":"油轮"}],"oxford":{"phon":"ˈtæŋkə(r)","pos":"noun","senses":[{"en":"a ship or lorry that carries oil, gas or petrol in large quantities","cn":"液货船；罐式汽车；油轮；油槽车","ex":{"en":"an oil tanker","cn":"油轮"}}]}},"tankard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(带把手的金属制的)大啤酒杯","en":"A tankard is a large metal cup with a handle, which you can drink beer from.","ex":{"en":"...a large pewter tankard.","cn":"大号白镴啤酒杯"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large metal cup, usually with a handle, which you can drink beer from 〔","cn":"通常有柄、金属制的〕大啤酒杯"}]},"media":{"img":["media/ldoce/img/tankard.jpg"],"uk":"media/ldoce/hwd/bre/c/tankard0205.mp3","us":"media/ldoce/hwd/ame/4/tankard.mp3"},"oxford":{"phon":"ˈtæŋkəd","pos":"noun","senses":[{"en":"a large, usually metal, cup with a handle, that is used for drinking beer from","cn":"（通常为金属的）单柄大酒杯，啤酒杯"}]}},"tamarind":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"罗望子果实;罗望子树","en":"A tamarind is a fruit which grows on a tropical evergreen tree which has pleasant-smelling flowers. You can also refer to the tree on which this fruit grows as a tamarind ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tropical tree, or the fruit of this tree","cn":"酸豆（树）"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41tamarind.mp3","us":"media/ldoce/hwd/ame/4/tamarind.mp3"},"oxford":{"phon":"ˈtæmərɪnd","pos":"noun","senses":[{"en":"a tropical tree that produces fruit, also called tamarinds, that are often preserved and used in cooking","cn":"罗望子树，酸豆（热带树木）；罗望子果，酸豆（常用于亚洲式烹调）"}]}},"tailpipe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(汽车的)排气管，尾气喷管","en":"A tailpipe is the end pipe of a car's exhaust system."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a pipe on a vehicle or machine through which gas or steam passes 〔","cn":"车辆或机器的〕尾部排气管"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41tail_pipe.mp3","us":"media/ldoce/hwd/ame/7/tailpipe.mp3"},"oxford":{"phon":"ˈteɪlpaɪp","pos":"noun","senses":[{"en":"a pipe through which waste gases come out of a vehicle","cn":"（汽车的）排气管"}]}},"tamoxifen":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(治疗乳腺癌的)他莫昔芬，三苯氧胺","en":"Tamoxifen is a drug that is used for treating women who have breast cancer."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drug that is used to treat breast cancer","cn":"他莫昔芬﹐三苯氧胺〔用于治疗乳腺癌的一种药物〕"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41tamoxifen2.mp3","us":"media/ldoce/hwd/ame/a/laadtamoxifen.mp3"},"oxford":{"phon":"təˈmɒksɪfen","pos":"noun","senses":[{"en":"a drug that is especially used to treat breast cancer","cn":"三苯氧胺，他莫昔芬（尤用于治疗乳腺癌）","ex":{"en":"the benefits and risks of tamoxifen","cn":"他莫昔芬的益处和风险"}}]}},"tact":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（言谈举止的）老练，圆通，得体，乖巧","en":"Tact is the ability to avoid upsetting or offending people by being careful not to say or do things that would hurt their feelings.","ex":{"en":"On this occasion the press have not been intrusive and they have shown great tact.","cn":"媒体此次并没有过多纠缠，表现十分得体。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you do something with care, you are careful to avoid damage, mistakes etc","cn":""},{"en":"care to avoid danger or risks, or care about trusting information that might not be true","cn":""},{"en":"a sensible and careful attitude that makes you avoid unnecessary risks – a rather formal use","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"To talk carefully without hurting anyone’s feelings, that’s tact . Politicians have tact , which makes them good at speaking about sensitive matters without making fools of themselves. At least, sometimes they have tact ."}]},"collocations":{"phrases":["ADJ. considerable, great, the utmost","VERB + TACT have | call for, need, require The situation called for considerable tact. | display, exercise, show, use Employees are trained ","PREP. with ~ The incident should have been handled with more tact by the police.","PHRASES a lack of tact, the soul of tact Their host, who was the soul of tact, never mentioned the incident again. | tact and diplomacy/sens"]},"media":{"uk":"media/ldoce/hwd/bre/c/tact0205.mp3","us":"media/ldoce/hwd/ame/5/tact.mp3"},"examples":[{"en":"Settling the dispute required great tact and diplomacy.","cn":"解决这个争端需要十分老练和娴熟的外交手腕。"},{"en":"She is not exactly known for her tact.","cn":"她并不以策略见称。"}],"oxford":{"phon":"tækt","pos":"noun","senses":[{"en":"the ability to deal with difficult or embarrassing situations carefully and without doing or saying anything that will annoy or upset other people","cn":"（处事、言谈等的）圆通，老练，圆滑","ex":{"en":"Settling the dispute required great tact and diplomacy.","cn":"解决这个争端需要十分老练和娴熟的外交手腕。"}}]}},"tailwind":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(从行驶的交通工具后面吹来的)顺风","en":"A tailwind is a wind that is blowing from behind an aeroplane, boat, or other vehicle, making it move faster.","ex":{"en":"A tailwind had cut the flying time by half an hour.","cn":"由于顺风，飞行时间缩短了半小时。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wind blowing in the same direction that something or someone is travelling 〔","cn":"车辆等行驶时从后面吹来的〕顺风"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41tailwind.mp3","us":"media/ldoce/hwd/ame/6/ld41tailwind.mp3"},"oxford":{"phon":"ˈteɪlwɪnd","pos":"noun","senses":[{"en":"a wind that blows from behind a moving vehicle, a runner, etc.","cn":"顺风","ex":{"en":"A tailwind made the ride home very relaxing.","cn":"顺风使骑车回家格外轻松。"}}]}},"talmud":{"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"《塔木德经》(犹太教法典)","en":"The Talmud is the collection of ancient Jewish laws which governs the religious and non-religious life of Orthodox Jews."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the writings that make up Jewish law about religious and non-religious life 《","cn":"塔木德经》〔规范犹太人宗教及世俗生活的法典〕"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41talmud.mp3","us":"media/ldoce/hwd/ame/f/talmud.mp3"}},"taffeta":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（主要用于制作女装的）塔夫绸","en":"Taffeta is shiny stiff material made of silk or nylon that is used mainly for making women's clothes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a shiny stiff cloth made from silk or nylon","cn":"塔夫绸"}]},"media":{"uk":"media/ldoce/hwd/bre/8/taffeta0205.mp3","us":"media/ldoce/hwd/ame/6/taffeta.mp3"},"oxford":{"phon":"ˈtæfɪtə","pos":"noun","senses":[{"en":"a type of stiff, shiny cloth made from silk or a similar material, used especially for making dresses","cn":"塔夫绸"}]}},"tantrum":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"发脾气;耍性子","en":"If a child has a tantrum, they lose their temper in a noisy and uncontrolled way. If you say that an adult is throwing a tantrum, you are criticizing them for losing their temper and acting in a childish way.","ex":{"en":"My son had a tantrum and banged his fist on the ground","cn":"我儿子大发脾气，一拳捶在了地上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if someone, especially a child, has or throws a tantrum , they shout angrily and cry, especially because they cannot have what they want","cn":""},{"en":"to start a loud angry argument with someone, especially in a public place and in a way that is embarrassing","cn":""},{"en":"a sudden expression of very strong angry feelings, especially because you cannot control your anger any longer","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A tantrum is a short-lived fit of frustration. Kids have them. Politicians have them. Reality show stars have them. I bet even you have had one!"}]},"collocations":{"phrases":["ADJ. temper","VERB + TANTRUM have, throw He threw a tantrum on the school bus. | deal with | ignore"]},"media":{"uk":"media/ldoce/hwd/bre/a/tantrum0205.mp3","us":"media/ldoce/hwd/ame/8/tantrum.mp3"},"examples":[{"en":"Children often have temper tantrums at the age of two or thereabouts.","cn":"儿童在两岁左右经常爱使性子。"},{"en":"to have/throw a tantrum","cn":"发脾气"}],"oxford":{"phon":"ˈtæntrəm","pos":"noun","senses":[{"en":"a sudden short period of angry, unreasonable behaviour, especially in a child","cn":"（尤指儿童）耍脾气，使性子","ex":{"en":"to have/throw a tantrum","cn":"发脾气"}}]}},"tacit":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"默认的;默许的;不言而喻的","en":"If you refer to someone's tacit agreement or approval, you mean they are agreeing to something or approving it without actually saying so, often because they are unwilling to admit to doing so.","ex":{"en":"The question was a tacit admission that a mistake had indeed been made","cn":"问这个问题实际上等于默认确实出了差错。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"tacit agreement, approval, support etc is given without anything actually being said","cn":"心照不宣的﹐默认的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something tacit is implied or understood without question. Holding hands might be a tacit acknowledgment that a boy and girl are dating."}]},"media":{"uk":"media/ldoce/hwd/bre/c/tacit0205.mp3","us":"media/ldoce/hwd/ame/b/tacit.mp3"},"examples":[{"en":"By tacit agreement , the subject was never mentioned again.","cn":"根据达成的默契，这个话题从未再提起过。"},{"en":"tacit approval/support/knowledge","cn":"默许；暗中支持；只可意会的认识"}],"oxford":{"phon":"ˈtæsɪt","pos":"adjective","senses":[{"en":"that is suggested indirectly or understood, rather than said in words","cn":"心照不宣的；不言而喻的；默示的","ex":{"en":"tacit approval/support/knowledge","cn":"默许；暗中支持；了然于心的认识"}}]}},"taco":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(包着肉、蔬菜和辣酱的)墨西哥玉米薄饼卷","en":"A taco is a crispy Mexican pancake made from corn and eggs, which is folded and filled with meat, vegetables, and a spicy sauce."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of Mexican food made from a corn tortilla that is folded in half and filled with meat, beans etc 〔","cn":"用肉﹑豆子等作馅的〕墨西哥玉米薄饼卷"}]},"media":{"uk":"media/ldoce/hwd/bre/e/taco0205.mp3","us":"media/ldoce/hwd/ame/b/taco.mp3"},"oxford":{"phon":"ˈtækəʊ","pos":"noun","senses":[{"en":"a type of Mexican food consisting of a fried pancake that is folded over and filled with meat, beans, etc.","cn":"墨西哥玉米卷（包着肉、豆等）"}]}},"tamp":{"collins":{"senses":[{"pos":"VERB 动词","cn":"压实;夯实","en":"If you tamp something, you press it down by tapping it several times so that it becomes flatter and more solid.","ex":{"en":"Then I tamp down the soil with the back of a rake","cn":"然后我用耙子的背将土壤拍实。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to press or push something down by lightly hitting it several times","cn":"压实﹔拍打…使坚实"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41tamp.mp3","us":"media/ldoce/hwd/ame/7/tamp.mp3"},"examples":[{"en":"The old man tamped down the tobacco with his thumb.","cn":"老人用大拇指把烟叶压实。"}],"oxford":{"phon":"tæmp","pos":"verb","senses":[{"en":"to press something down hard, especially into a closed space","cn":"捣实；压实；塞紧","ex":{"en":"He tamped down the tobacco in his pipe with his thumb.","cn":"他用拇指压住烟斗里的烟草。"}}]}},"tatty":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不整洁的;邋遢的;破烂的","en":"If you describe something as tatty, you think it is untidy, rather dirty, and looks as if it has not been cared for.","ex":{"en":"There were a lot of guest houses which were very tatty.","cn":"有许多小旅馆都又脏又乱。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"clothes, books etc that look shabby are no longer in good condition because they are old and have been used a lot","cn":""},{"en":"something such as material or cloth that is worn is thinner or weaker in particular parts as a result of being used a lot over a long time","cn":""},{"en":"clothes or books that are tattered are old and torn","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/tatty0205.mp3","us":"media/ldoce/hwd/ame/1/laadtatty.mp3"},"examples":[{"en":"a tatty carpet","cn":"破旧的地毯"},{"en":"tatty jeans","cn":"破旧的牛仔裤"}],"oxford":{"phon":"ˈtæti","pos":"adjective","senses":[{"en":"in a bad condition because it has been used a lot or has not been cared for well","cn":"褴褛的；破烂的；破败的；邋遢的","ex":{"en":"a tatty carpet","cn":"破旧的地毯"}}]}},"tart":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(尤指甜心的)果馅饼","en":"A tart is a shallow pastry case with a filling of food, especially sweet food.","ex":{"en":"...jam tarts.","cn":"果酱馅饼"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(水果等)味道浓烈的，味儿冲的","en":"If something such as fruit is tart, it has a sharp taste.","ex":{"en":"The blackberries were a bit too tart on their own, so we stewed them gently with some apples.","cn":"光黑莓味道有点儿冲，所以我们将它和几个苹果一起用小火炖了炖。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(言语)尖刻的，尖酸的，刻薄的","en":"A tart remark or way of speaking is sharp and unpleasant, often in a way that is rather cruel.","ex":{"en":"The words were more tart than she had intended","cn":"话听起来太刻薄，她本没想这么刻薄的。"}},{"pos":"N-COUNT 可数名词","cn":"淫妇;荡妇;妓女","en":"If someone refers to a woman or girl as a tart, they are criticizing her because they think she is sexually immoral or dresses in a way that makes her look sexually immoral.","ex":{"en":"He was nasty about my appearance. If I dressed up he'd say I looked like a tart.","cn":"他对我的外表要求很苛刻，我要是打扮打扮，他就会说我像荡妇。"}},{"pos":"","cn":"","en":"相关词组：tart up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"having a very good taste","cn":""},{"en":"having a very bad taste","cn":""},{"en":"tasting full of sugar","cn":""}]},"vocab":{"pos":"1 adj 2 n 3 n","senses":[{"en":"A tart is small pie filled with fruit or custard, with no top crust, like the cherry tarts you bought at the bakery."}]},"collocations":{"phrases":["ADJ. fruit, jam, treacle | apple, strawberry, etc.","VERB + TART make 2 woman","ADJ. cheap, little","VERB + TART look like That dress makes her look like a tart. | call sb He had called her a cheap little tart."]},"media":{"img":["media/ldoce/img/strawberry_tart.jpg"],"uk":"media/ldoce/hwd/bre/0/tart_v0205.mp3","us":"media/ldoce/hwd/ame/1/tart1.mp3"},"examples":[{"en":"‘Too late!’ said my mother tartly. “","cn":"早干什么去了！”我母亲刻薄地说。"},{"en":"‘Too late!’ said my mother tartly.","cn":""}],"oxford":{"phon":"tɑːt","pos":"noun","senses":[{"en":"an open pie filled with sweet food such as fruit","cn":"甜果馅饼","g":"[countable, uncountable]","ex":{"en":"a strawberry tart","cn":"草莓馅饼"}},{"en":"an offensive word for a woman who you think behaves or dresses in a way that is intended to attract sexual attention","cn":"放荡的女人；骚货","g":"[countable]","lab":"British English, informal, disapproving，，，，","ex":{"en":"He said my dress made me look like a tart.","cn":"他说我的衣服让我看起来像个骚货。"}},{"en":"a person who works as a prostitute","cn":"妓女","g":"[countable]","lab":"slang"},{"en":"having a bitter, sharp taste that may be pleasant or unpleasant","cn":"苦涩的；带酸味的","ex":{"en":"tart apples","cn":"酸苹果"},"pos":"adjective"},{"en":"quick and unkind","cn":"尖酸的；刻薄的；辛辣的","g":"[usually before noun]","ex":{"en":"a tart reply","cn":"尖刻的答复"},"pos":"adjective"}]}},"taoiseach":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(爱尔兰共和国的)总理","en":"The prime minister of the Republic of Ireland is called the Taoiseach ."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the title of the prime minister of the Republic of Ireland","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41taoiseach.mp3","us":"media/ldoce/hwd/ame/e/ld41taoiseach.mp3"},"oxford":{"phon":"ˈtiːʃəx","pos":"noun","senses":[{"en":"the Prime Minister of the Irish Republic","cn":"（爱尔兰共和国）总理"}]}},"tarot":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"塔罗牌;塔罗牌占卜","en":"The Tarot is a pack of cards with pictures on them that is used to predict what will happen to people in the future. Tarot is also used to refer to the system of predicting people's futures using these cards.","ex":{"en":"...the suits of the Tarot","cn":"塔罗牌里的各种花色"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of 78 cards, used for telling what will happen to someone in the future","cn":"塔罗牌〔一套用于占卜的纸牌﹐共78张〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/tarot0205.mp3","us":"media/ldoce/hwd/ame/c/tarot.mp3"},"oxford":{"phon":"ˈtærəʊ","pos":"noun","senses":[{"en":"a set of special cards with pictures on them, used for telling somebody what will happen to them in the future","cn":"塔罗纸牌（用于占卜）","ex":{"en":"to read/interpret the tarot","cn":"解读塔罗牌"}}]}},"tactful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有分寸的;考虑周全的;圆通的","en":"If you describe a person or what they say as tactful you approve of them because they are careful not to offend or upset another person.","ex":{"en":"He had been extremely tactful in dealing with the financial question","cn":"他在处理这个财务问题时很有分寸。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"careful not to do or say anything that will hurt or embarrass other people","cn":""},{"en":"if you make a guarded statement, remark etc you are careful not to let other people know much about your thoughts or intentions","cn":""},{"en":"very careful about what you say or do, so that you do not make people feel angry, upset, or embarrassed","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you are tactful , you have a knack for saying the right thing at the right time. A tactful person is appropriate and sensitive, never rude or careless."}]},"media":{"uk":"media/ldoce/hwd/bre/0/tactful0205.mp3","us":"media/ldoce/hwd/ame/7/tactful.mp3"},"examples":[{"en":"I tried to find a tactful way of telling her the truth.","cn":"我设法找一个妥善的办法，把实情告诉她。"},{"en":"I tactfully suggested he should see a doctor.","cn":"我婉转地建议他去看医生。"}],"oxford":{"phon":"ˈtæktfl","pos":"adjective","senses":[{"en":"careful not to say or do anything that will annoy or upset other people","cn":"圆通的；得体的；不得罪人的","ex":{"en":"That wasn't a very tactful thing to say!","cn":"说这种话可不太得体！"}}]}},"taskmaster":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"监工;工头","en":"If you refer to someone as a hard taskmaster, you mean that they expect the people they supervise to work very hard.","ex":{"en":"They're both tough taskmasters, but Stephen is much more supportive.","cn":"他们俩都是严厉的工头，不过斯蒂芬更喜欢帮助他人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to force people to work very hard","cn":"监工严苛"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41taskmaster.mp3","us":"media/ldoce/hwd/ame/9/taskmaster.mp3"},"examples":[{"en":"She was a hard taskmaster.","cn":"她是个严厉的工头。"}],"oxford":{"phon":"ˈtɑːskmɑːstə(r)","pos":"noun","senses":[{"en":"a person who gives other people work to do, often work that is difficult","cn":"工头；监工；监督人","ex":{"en":"She was a hard taskmaster.","cn":"她是个严厉的工头。"}}]}},"tack":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指固定地毯的)大头钉，平头钉","en":"A tack is a short nail with a broad, flat head, especially one that is used for fastening carpets to the floor. to get down to brass tacks→see: ;"},{"pos":"VERB 动词","cn":"用大头钉(或图钉)固定","en":"If you tack something to a surface, you pin it there with tacks or drawing pins.","ex":{"en":"He had tacked this note to her door","cn":"他用图钉将这张便条钉在她的门上。"}},{"pos":"N-SING 单数名词","cn":"方法;策略;思路","en":"If you change tack or try a different tack, you try a different method for dealing with a situation.","ex":{"en":"In desperation I changed tack","cn":"我走投无路，于是改变了策略。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(船只)曲折航行，蜿蜒航行","en":"If a sailing boat is tacking or if the people in it tack it, it is sailing towards a particular point in a series of sideways movements rather than in a straight line.","ex":{"en":"We were tacking fairly close inshore","cn":"我们沿着近海岸曲折航行。"}},{"pos":"VERB 动词","cn":"（用大针脚）粗缝，暂时缝上","en":"If you tack pieces of material together, you sew them together with big, loose stitches in order to hold them firmly or check that they fit, before sewing them properly.","ex":{"en":"Tack them together with a 1.5 cm seam","cn":"用 1.5 厘米的针脚将它们暂时缝上。"}},{"pos":"","cn":"","en":"相关词组：tack on"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you are wrong , you think or say something that is not correct","cn":""},{"en":"to have an incorrect opinion or belief about something - use this as a polite way of saying someone is wrong","cn":""},{"en":"to be wrong because you have been given information that is incorrect or untrue","cn":""}]},"collocations":{"phrases":["ADJ. right, wrong","VERB + TACK go off on, take, try New research is taking a different tack. The interviewer decided to try another tack. | change, switch She ","PREP. on a/the ~ I think you're on the wrong tack with that approach.","PHRASES a change of tack 2 direction of a sailing boat in relation to the wind","ADJ. port, starboard | opposite","VERB + TACK sail on We were sailing on starboard tack. | change, swing onto/to The yacht swung to the opposite tack."]},"media":{"uk":"media/ldoce/hwd/bre/6/tack_v0205.mp3","us":"media/ldoce/hwd/ame/f/tack1.mp3"},"examples":[{"en":"It was a brave decision to change tack in the middle of the project.","cn":"在项目进行过程当中改变方针是个大胆的决定。"},{"en":"When threats failed, she decided to try/take a different tack.","cn":"威胁不成，她便决定变换策略。"}],"oxford":{"phon":"tæk","pos":"noun","senses":[{"en":"the way in which you deal with a particular situation; the direction of your words or thoughts","cn":"方针；方法；思路","g":"[uncountable, singular]","ex":{"en":"a complete change of tack","cn":"方法的完全改变"}},{"en":"the direction that a boat with sails takes as it sails at an angle to the wind in order to fill its sails","cn":"（帆船的）戗风调向，戗风行驶","g":"[countable, uncountable]","lab":"specialist","ex":{"en":"They were sailing on (a) port/starboard tack (= with the wind coming from the left/right side).","cn":"他们正在左／右舷戗风行驶。"}},{"en":"a small nail with a sharp point and a flat head, used especially for fixing a carpet to the floor","cn":"（尤指把地毯钉在地板上的）平头钉，大头钉","g":"[countable]","ex":{"en":"a carpet tack","cn":"地毯钉"}},{"en":"a short pin with a large round, flat head, used especially for fastening paper to a board or wall","cn":"图钉","g":"[countable]","lab":"both North American English"},{"en":"a long, loose stitch used for holding pieces of cloth together temporarily, before you sew them finally","cn":"粗线脚缝；假缝","g":"[countable]"},{"en":"the equipment that you need for riding a horse, such as a saddle and bridle","cn":"鞍辔；马具","g":"[uncountable]","lab":"specialist","ex":{"en":"a tack room (= the room where this equipment is kept)","cn":"马具室（= 存放该设备的房间）"}},{"en":"to fasten something in place with a tack or tacks","cn":"（用平头钉）钉住","g":"[transitive]","ex":{"en":"The carpet was tacked to the floor.","cn":"地毯是用平头钉钉在地板上的。"},"pos":"verb"},{"en":"to fasten pieces of cloth together temporarily with long, loose stitches before sewing them finally","cn":"绷；用粗线脚缝","g":"[transitive]","ex":{"en":"She tacked the sleeve of the blouse into the armhole.","cn":"她把衬衫的袖子钉进袖窿里。"},"pos":"verb"},{"en":"to change the direction of a sailing boat by turning the front of the boat into and through the wind, so that the wind blows onto the sails from the opposite side; to do this several times in order to travel in the direction that the wind is coming from","cn":"戗风行驶；换戗；作之字形航行","g":"[intransitive]","lab":"specialist","pos":"verb"}]}},"tanner":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"制革工;鞣皮工","en":"A tanner is someone whose job is making leather from animal skins."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to tan animal skins (= make them into leather by treating them with a special acid )","cn":"鞣皮工﹐制革工"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41tanner.mp3","us":"media/ldoce/hwd/ame/0/tanner.mp3"},"oxford":{"phon":"ˈtænə(r)","pos":"noun","senses":[{"en":"a person whose job is to tan animal skins to make leather","cn":"鞣皮工；硝皮匠；制革工人"}]}},"tat":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"廉价品;劣质品","en":"You can use tat to refer to ornaments, used goods, cheap clothes, or other items which you think are cheap and of bad quality.","ex":{"en":"...souvenir shops selling an astounding variety of tat.","cn":"出售种类多得惊人的劣质品的纪念品商店"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"things that are cheap and badly made","cn":"不值钱的东西﹔质量低劣的东西"},{"en":"an informal American word for tattoo tattoo","cn":"的非正式美语说法"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41tat.mp3","us":"media/ldoce/hwd/ame/d/tat.mp3"},"oxford":{"phon":"tæt","pos":"noun","senses":[{"en":"goods that are cheap and of low quality","cn":"劣质货","g":"[uncountable]","lab":"British English, informal，，"},{"en":"a tattoo (= a picture or design that is marked permanently on a person’s skin by making small holes in the skin with a needle and filling them with coloured ink)","cn":"纹身","g":"[countable]","lab":"informal","ex":{"en":"She has tats over most of her body.","cn":"她全身大部分地方都有纹身。"}},{"en":"to mark somebody’s skin with a tattoo","cn":"将花纹刺在…上；给…文身","ex":{"en":"When they started living together they had each other's names tatted on their arms.","cn":"当他们开始同居时，他们把彼此的名字纹在了手臂上。"},"pos":"verb"}]}},"taurus":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"金牛宫，金牛座(黄道十二宫之一。出生于 4 月 20 日与 5 月 20 日之间的人属此星座)","en":"Taurus is one of the twelve signs of the zodiac. Its symbol is a bull. People who are born approximately between the 20th of April and the 20th of May come under this sign."},{"pos":"N-SING 单数名词","cn":"出生于金牛宫时段的人","en":"A Taurus is a person whose sign of the zodiac is Taurus."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the study of the positions and movements of the stars and how they might influence people and events","cn":""},{"en":"a description of people’s characters and the things that will happen to them, based on the position of the stars and planets at the time of their birth – especially a description that is printed in a newspaper or magazine","cn":""},{"en":"the twelve signs that you can belong to according to your birth date and the position of the stars then, which some people believe influence our characters and our lives","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/taurus0205.mp3","us":"media/ldoce/hwd/ame/e/taurus.mp3"},"oxford":{"phon":"ˈtɔːrəs","pos":"noun","senses":[{"en":"the second sign of the zodiac, the Bull","cn":"黄道第二宫；金牛宫；金牛（星）座","g":"[uncountable]"},{"en":"a person born when the sun is in this sign, that is between 21 April and 21 May","cn":"金牛座的人（约出生于 4 月 21 日至 5 月 21 日）","g":"[singular]"}]}},"tabloid":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(版面小、文章短、图片多的)通俗小报","en":"A tabloid is a newspaper that has small pages, short articles, and lots of photographs. Tabloids are often considered to be less serious than other newspapers.","ex":{"en":"'The British tabloids called me leggy and stunning,' she recalls.","cn":"“当时的英国小报都说我‘双腿修长’、‘艳惊四座’，”她回忆道。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a newspaper. Paper is more common than newspaper in everyday English","cn":""},{"en":"newspapers and news magazines in general, and the people who write for them","cn":""},{"en":"newspapers, magazines, television, radio, and the Internet, considered as a group that provides news and information","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A tabloid is a newspaper, especially one that's smaller than a traditional daily paper and focuses on sensational news items. If you're lucky, you might read some juicy tabloid headlines when you pass the corner newsstand."}]},"collocations":{"phrases":["ADJ. daily, Sunday | national | popular","VERB + TABLOID read","TABLOID + NOUN journalism, newspaper, press He believes that the tabloid press has behaved disgracefully.","PREP. in a/the ~ I despair when I read what passes for news in some of the tabloids."]},"media":{"uk":"media/ldoce/hwd/bre/2/tabloid0205.mp3","us":"media/ldoce/hwd/ame/7/tabloid.mp3"},"examples":[{"en":"a serious paper in a new tabloid format","cn":"一份以小报形式重新编排的严肃报纸"},{"en":"The story made the front page in all the tabloids.","cn":"这件事成了所有小报的头版新闻。"}],"oxford":{"phon":"ˈtæblɔɪd","pos":"adjective","senses":[{"en":"tabloid newspapers have small pages and short articles with a lot of pictures and stories about famous people, and are often thought of as less serious than other newspapers","cn":"通俗小报（文短图多，内容多为名人逸事，常被视为不太严肃）","lab":"sometimes disapproving","ex":{"en":"a tabloid newspaper","cn":"通俗小报"}},{"en":"used to describe the small size of some newspapers (usually half the size of larger papers)","cn":"小报（版面通常比大报小一半）","ex":{"en":"a serious paper in a new tabloid format","cn":"新改为小报版式的严肃报纸"}},{"en":"a newspaper with small pages (usually half the size of those in larger papers)","cn":"小报（版面通常比大报小一半）","pos":"noun"},{"en":"a newspaper of this size with short articles and a lot of pictures and stories about famous people, often thought of as less serious than other newspapers","cn":"通俗小报（文短图多，内容多为名人逸事，常被视为不太严肃）","lab":"sometimes disapproving","ex":{"en":"The story made the front page in all the tabloids.","cn":"这件事成了所有小报的头版新闻。"},"pos":"noun"}]}},"tadpole":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蝌蚪","en":"Tadpoles are small water creatures which grow into frogs or toads."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small creature that has a long tail, lives in water, and grows into a frog or toad","cn":"蝌蚪"}]},"media":{"uk":"media/ldoce/hwd/bre/9/tadpole0205.mp3","us":"media/ldoce/hwd/ame/7/tadpole.mp3"},"oxford":{"phon":"ˈtædpəʊl","pos":"noun","senses":[{"en":"a small creature with a large head and a small tail, that lives in water and is the young form of a frog, toad, etc.","cn":"蝌蚪"}]}},"takeout":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"外卖店;外卖餐馆","en":"A takeout is a store or restaurant which sells hot cooked food that you eat somewhere else."},{"pos":"N-COUNT 可数名词","cn":"外卖饭菜;外卖食物","en":"A takeout or takeout food is hot cooked food which you buy from a store or restaurant and eat somewhere else."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a meal that you buy at a restaurant to eat at home 〔","cn":"餐馆的〕外卖食品"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41takeout.mp3","us":"media/ldoce/hwd/ame/2/laadtakeout.mp3"},"oxford":{"phon":"ˈteɪkaʊt","pos":"noun","senses":[{"en":"a restaurant that cooks and sells food that you take away and eat somewhere else","cn":"外卖餐馆"},{"en":"a meal that you buy at this type of restaurant","cn":"外卖的饭菜；外卖食物","ex":{"en":"Let's have a takeout tonight.","cn":"今晚我们吃外卖吧。"}}]}},"tamper":{"collins":{"senses":[{"pos":"VERB 动词","cn":"干预;篡改","en":"If someone tampers with something, they interfere with it or try to change it when they have no right to do so.","ex":{"en":"I don't want to be accused of tampering with the evidence","cn":"我不希望被人控告篡改证据。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to deliberately damage buildings, vehicles, or public property","cn":""},{"en":"to deliberately damage a room or building by breaking windows, furniture etc","cn":""},{"en":"to cause a lot of damage to a thing or place, either deliberately or by using it carelessly","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To tamper is to alter or mess with something, usually for a bad reason. Tamper also refers to being nosy about someone's business. Don’t tamper with anything; it’s annoying."}]},"media":{"uk":"media/ldoce/hwd/bre/0/tamper0205.mp3","us":"media/ldoce/hwd/ame/b/tamper.mp3"},"examples":[{"en":"Someone had obviously tampered with the brakes of my car.","cn":"显然有人鼓捣过我汽车的刹车。"},{"en":"He noticed that the instruments had been tampered with.","cn":"他注意到仪器被人动过了。"}]},"tablespoon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大汤匙;大调羹","en":"A tablespoon is a fairly large spoon used for serving food and in cooking."},{"pos":"N-COUNT 可数名词","cn":"一大汤匙(或大调羹)的量","en":"You can refer to an amount of food resting on a tablespoon as a tablespoon of food.","ex":{"en":"...a tablespoon of sugar.","cn":"一大汤匙糖"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large spoon used for serving food","cn":"汤匙﹐大调羹"},{"en":"the amount that a tablespoon can hold, used as a unit for measuring food or liquid in cooking","cn":"一汤匙之量﹐一大调羹之量"}]},"media":{"uk":"media/ldoce/hwd/bre/0/tablespoon0205.mp3","us":"media/ldoce/hwd/ame/1/laadtablespoon.mp3","img":["media/thumb/tablespoon.jpg"]},"examples":[{"en":"Add two tablespoons of water.","cn":"加两汤匙的水。"},{"en":"two tablespoons of flour","cn":"两汤匙面粉"}],"oxford":{"phon":"ˈteɪblspuːn","pos":"noun","senses":[{"en":"a large spoon, used especially for serving food","cn":"餐匙，汤匙（尤用于分食物）"},{"en":"the amount a tablespoon can hold","cn":"一餐匙，一汤匙（的量）","ex":{"en":"Add two tablespoons of water.","cn":"加两汤匙的水。"}}]}},"tantalize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使(某人)想要却得不到(某物);逗引;挑逗;撩拨","en":"If someone or something tantalizes you, they make you feel hopeful and excited about getting what you want, usually before disappointing you by not letting you have what they appeared to offer.","ex":{"en":"The boy would come into the room and tantalize the dog with his feed.","cn":"那个男孩会到房间里拿狗食逗弄狗。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to show or promise something that someone really wants, but then not allow them to have it","cn":"使〔某人想要某物却得不到而〕干着急﹔逗引﹔撩拨"}]},"vocab":{"pos":"v","senses":[{"en":"When you tantalize people, you torment them in a specific way — by showing them something they want but can’t have. You could tantalize people with cavities and nut allergies by eating pecan pie in front of them."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41tantalize.mp3","us":"media/ldoce/hwd/ame/d/tantalize.mp3"},"examples":[{"en":"The tantalizing aroma of fresh coffee wafted towards them.","cn":"新鲜咖啡那诱人的香味向他们飘来。"},{"en":"The branch was tantalizingly out of reach.","cn":"够不到那树枝，让人干着急。"}],"oxford":{"phon":"ˈtæntəlaɪz","pos":"verb","senses":[{"en":"to make you want something that you cannot have or do","cn":"（以可望而不可即之物）逗引，招惹"}]}},"tablecloth":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"台布;桌布","en":"A tablecloth is a cloth used to cover a table."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a cloth used for covering a table","cn":"桌布﹐台布"}]},"media":{"uk":"media/ldoce/hwd/bre/0/tablecloth0205.mp3","us":"media/ldoce/hwd/ame/6/tablecloth.mp3"},"oxford":{"phon":"ˈteɪblklɒθ","pos":"noun","senses":[{"en":"a cloth that you use for covering a table, especially when you have a meal","cn":"（尤指餐桌的）桌布，台布"}]}},"talon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(猛禽的)爪，利爪","en":"The talons of a bird of prey are its hooked claws."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sharp powerful curved nail on the feet of some birds that catch animals for food 〔","cn":"猛禽的〕利爪"}]},"vocab":{"pos":"n","senses":[{"en":"A talon is a large, hooked claw. Although talons are usually associated with eagles, hawks and other birds of prey, you can also use the word to describe the flesh-tearing claws or fingernails of raptors, werewolves or even enraged preschoolers."}]},"media":{"uk":"media/ldoce/hwd/bre/6/talon0205.mp3","us":"media/ldoce/hwd/ame/8/talon.mp3","img":["media/thumb/talon.jpg"]},"oxford":{"phon":"ˈtælən","pos":"noun","senses":[{"en":"a long, sharp, curved nail on the feet of some birds, especially birds of prey (= birds that kill other creatures for food)","cn":"（某些鸟类，尤指猛禽的）爪"}]}},"tame":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(动物)驯化的，驯服的","en":"A tame animal or bird is one that is not afraid of humans.","ex":{"en":"The deer never became tame; they would run away if you approached them.","cn":"那些鹿一直没有被驯服：你一靠近，它们就跑开。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"乏味的;没劲的","en":"If you say that something or someone is tame, you are criticizing them for being weak and uninteresting, rather than forceful or shocking.","ex":{"en":"Some of today's political demonstrations look rather tame","cn":"如今有些政治游行显得毫无激情。"}},{"pos":"VERB 动词","cn":"驯化，驯服(野生动物或鸟)","en":"If someone tames a wild animal or bird, they train it not to be afraid of humans and to do what they say.","ex":{"en":"The Amazons were believed to have been the first to tame horses.","cn":"据说亚马孙人最先驯化了马。"}},{"pos":"VERB 动词","cn":"制服;控制;驾驭","en":"If you tame someone or something that is dangerous, uncontrolled, or likely to cause trouble, you bring them under control.","ex":{"en":"Two regiments of cavalry were called out to tame the crowds.","cn":"调集了两个装甲兵团去威慑、控制人群。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a tame animal or bird is not wild any longer, because it has been trained to live with people 〔","cn":"动物〕驯化的﹐由人驯养的"},{"en":"dull and disappointing","cn":"平淡的﹔枯燥乏味的"},{"en":"used to describe a person who is willing to do what other people ask, even if it is slightly dishonest","cn":"听使唤的﹔温顺的"}]},"vocab":{"pos":"adj v","senses":[{"en":"If something is tame , it cannot surprise or injure you. It’s predictable. Tame can be used as an adjective or verb. A circus lion is tame (adjective) because it’s been tamed (verb). A “lion-tamer” beat the wildness out of it."}]},"collocations":{"phrases":["VERBS be, look, seem | become","ADV. extremely, very | almost | quite 2 boring","VERBS appear, be, look, seem, sound | become | find sth I found office work very tame after army life.","ADV. positively, very living a life that makes Wild West movies look positively tame | a bit, a little, pretty, rather, somewhat To us it wa"]},"media":{"uk":"media/ldoce/hwd/bre/4/tame_adj0205.mp3","us":"media/ldoce/hwd/ame/d/tame1.mp3"},"examples":[{"en":"I have a tame doctor who'll always give me a sick note when I want a day off.","cn":"我的医生对我百依百顺，我想要休一天假时，他总会给我开病假条。"},{"en":"You'll find life here pretty tame after New York.","cn":"这里的生活相当枯燥，与纽约形成对比。"}],"oxford":{"phon":"teɪm","pos":"adjective","senses":[{"en":"not afraid of people, and used to living with them","cn":"驯养的；驯服的","ex":{"en":"The bird became so tame that it was impossible to release it back into the wild.","cn":"这只鸟变得如此驯服，以至于不可能将它放回野外。"}},{"en":"not interesting or exciting","cn":"平淡无奇的；枯燥乏味的","lab":"informal","ex":{"en":"You'll find life here pretty tame after New York.","cn":"这里的生活相当枯燥，与纽约形成对比。"}},{"en":"willing to do what other people ask","cn":"听使唤的；温顺的","lab":"informal","ex":{"en":"I have a tame doctor who'll always give me a sick note when I want a day off.","cn":"我的医生对我有求必应，我想要休一天假时，他总会给我开病假条。"}},{"en":"to make an animal, bird, etc. not afraid of people and used to living with them","cn":"驯养；驯化；驯服","ex":{"en":"Lions can never be completely tamed.","cn":"狮子永远不能被完全驯化。"},"pos":"verb"},{"en":"to make an emotion, an organization, a situation, etc., less powerful or easier to control","cn":"控制；驾驭；制服","ex":{"en":"She made strenuous efforts to tame her anger.","cn":"她竭力压制心头怒火。"},"pos":"verb"}]}},"tactic":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"战术;策略;招数","en":"Tactics are the methods that you choose to use in order to achieve what you want in a particular situation.","ex":{"en":"What sort of tactics will the President use to rally the people behind him?","cn":"总统会用什么样的策略把人们号召起来支持他呢？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to deliberately delay doing something, or to deliberately stop someone else from doing something until a later time, either because you are not ready or to give yourself an advantage","cn":""},{"en":"to deliberately try to delay doing something or making a decision, because you are not ready or want more time to think about it","cn":""},{"en":"methods used, especially by politicians, in order to delay a plan or decision so that something can be done during the delay","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Tactic is another word for maneuver or method. Looking for a way to get something done? Then you better find a tactic ."}]},"collocations":{"phrases":["ADJ. subtle | legitimate Some players see injuring their opponent as a legitimate tactic. | devious, dubious, underhand | aggressive, bully-","VERB + TACTIC decide on, discuss, plan, talk (about), work out She decided on a stalling tactic. | adopt, apply, deploy, employ, try, use th","TACTIC + VERB pay off, succeed, work His strong-arm tactics paid off. | fail","PREP. ~ for teaching parents tactics for dealing with aggressive children"]},"media":{"uk":"media/ldoce/hwd/bre/9/tactic0205.mp3","us":"media/ldoce/hwd/ame/8/tactic.mp3"},"examples":[{"en":"This was just the latest in a series of delaying tactics.","cn":"这只是一系列拖延战术中的一个新花招。"},{"en":"The manager discussed tactics with his team.","cn":"经理和他手下的一班人讨论了策略问题。"}],"oxford":{"phon":"ˈtæktɪk","pos":"noun","senses":[{"en":"the particular method you use to achieve something","cn":"策略；手段；招数","g":"[countable, usually plural]","ex":{"en":"They tried all kinds of tactics to get us to go.","cn":"他们施尽所有的招数想让我们离开。"}},{"en":"the art of moving soldiers and military equipment around during a battle or war in order to use them in the most effective way","cn":"战术；兵法","g":"[plural]"}]}},"tableware":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"餐具","en":"Tableware consists of the objects used on the table at meals, for example plates, glasses, or cutlery."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the plates, glasses, knives etc used when eating a meal","cn":"餐具"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41tableware.mp3","us":"media/ldoce/hwd/ame/3/tableware.mp3"},"oxford":{"phon":"ˈteɪblweə(r)","pos":"noun","senses":[{"en":"the word used in shops, etc. for items that you use for meals, such as plates, glasses, knives and forks","cn":"（商店用语）餐具"}]}},"tablespoonful":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一大汤匙(或大调羹)的量","en":"You can refer to an amount of food resting on a tablespoon as a tablespoonful of food.","ex":{"en":"Grate a tablespoonful of fresh ginger into a pan.","cn":"磨碎一汤匙鲜姜，放入平底锅。"}}]}},"tax-free":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(收入)免税的","en":"Tax-free is used to describe income on which you do not have to pay tax.","ex":{"en":"...a tax-free investment plan.","cn":"免税的投资计划"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not taxed","cn":"不纳税的﹐免税的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/tax_free0205.mp3","us":"media/ldoce/hwd/ame/5/tax-free.mp3"},"examples":[{"en":"a tax-free allowance","cn":"免税额"},{"en":"He was paid a tax-free cash sum as compensation.","cn":"给了他一笔免税的现金作为补偿。"}],"oxford":{"phon":"ˌtæks ˈfriː","pos":"adverb","senses":[{"en":"without having to pay tax on money, goods, etc.","cn":"免税的；不纳税的","ex":{"en":"The money will continue to earn interest tax-free until your retirement.","cn":"这笔钱将继续赚取免税利息，直到您退休。"}},{"en":"that you do not have to pay tax on","cn":"免税的；不纳税的","ex":{"en":"a tax-free allowance","cn":"免税额"},"pos":"adjective"}]}},"tad":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"稍微;略微","en":"You can use a tad in expressions such as a tad big or a tad small when you mean that it is slightly too big or slightly too small.","ex":{"en":"It was a tad confusing","cn":"这叫人有点糊涂。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small amount","cn":"少量﹐一点"},{"en":"slightly","cn":"稍微"}]},"media":{"uk":"media/ldoce/hwd/bre/f/tad0205.mp3","us":"media/ldoce/hwd/ame/1/laadtad.mp3"},"examples":[{"en":"It's a tad too expensive for me.","cn":"这对我来说稍微贵了一点儿。"},{"en":"Could you turn the sound down just a tad?","cn":"你把音量调低一点儿好吗？"}],"oxford":{"phon":"tæd","pos":"adverb","senses":[{"en":"by a very small amount","cn":"差一点儿","ex":{"en":"It's a tad too expensive for me.","cn":"这对我来说有点儿小贵。"}},{"en":"a very small amount","cn":"一点点；少量","ex":{"en":"Could you turn the sound down just a tad?","cn":"你把音量调低一点儿好吗？"},"pos":"noun"}]}},"tailor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(男装)裁缝","en":"A tailor is a person whose job is to make men's clothes."},{"pos":"VERB 动词","cn":"按需定制;量身打造","en":"If you tailor something such as a plan or system to someone's needs, you make it suitable for a particular person or purpose by changing the details of it.","ex":{"en":"We can tailor the program to the patient's needs.","cn":"我们可以根据病人的需要调整治疗方案。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something so that it is exactly right for someone’s particular needs or for a particular purpose","cn":"根据特定需要制作﹐定做"},{"en":"tailor something to something Treatment is tailored to the needs of each patient.","cn":"治疗方案是针对各个病人的需要而制订的。 tailor something to meet/suit somebody’s needs/requirements The classes are tailored to suit learner"},{"en":"someone whose job is to make men’s clothes, that are measured to fit each customer perfectly 〔","cn":"男装〕裁缝"}]},"vocab":{"pos":"n v","senses":[{"en":"A tailor helps make your clothes fit you better. Similarly, when you tailor something to the needs of others, you are adjusting what you do to best suit them rather than taking a general approach."}]},"collocations":{"phrases":["ADV. carefully | exactly | accordingly, individually, specially, specifically We identify your needs, and tailor your training accordingly.","PREP. for a system that is specially tailored for small firms | to The account offered by the bank will be tailored exactly to your needs."]},"media":{"uk":"media/ldoce/hwd/bre/a/tailor_v0205.mp3","us":"media/ldoce/hwd/ame/c/tailor1.mp3"},"examples":[{"en":"Most travel agents are prepared to tailor travel arrangements to meet individual requirements.","cn":"为了满足个别人士需要，大多数旅行社都愿意作出专门的旅游安排。"},{"en":"Special programmes of study are tailored to the needs of specific groups.","cn":"为满足特定群体的需要，特制了专门的课程。"}],"oxford":{"phon":"ˈteɪlə(r)","pos":"noun","senses":[{"en":"a person whose job is to make men’s clothes, especially somebody who makes suits, etc. for individual customers","cn":"（尤指为个人客户定制男式西装等的）裁缝"},{"en":"to make or adapt something for a particular purpose, a particular person, etc.","cn":"专门制作；定做","ex":{"en":"Much of the software is supplied ready tailored for the user.","cn":"许多软件都是为用户量身定制的。"},"pos":"verb"}]}},"tally":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"账目;积分;得分","en":"A tally is a record of amounts or numbers which you keep changing and adding to as the activity which affects it progresses.","ex":{"en":"They do not keep a tally of visitors to the palace, but it is very popular","cn":"他们没有对参观宫殿的人数进行统计，不过这地方很受欢迎。"}},{"pos":"V-RECIP 相互动词","cn":"与…一致;与…相同;与…吻合","en":"If one number or statement tallies with another, they agree with each other or are exactly the same. You can also say that two numbers or statements tally .","ex":{"en":"Its own estimate of three hundred tallies with that of another survey","cn":"其估计数目 300 与另一项调查的结果相吻合。"}},{"pos":"VERB 动词","cn":"计算;合计;清点","en":"If you tally numbers, items, or totals, you count them.","ex":{"en":"...as we tally the number of workers who have been laid off this year","cn":"我们统计今年下岗工人数量的时候"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to find the total number of things or people in a group by counting them all","cn":""},{"en":"to put several numbers or amounts together and calculate the total","cn":""},{"en":"to keep a record, either on paper or in your memory, of numbers or amounts that increase over a period of time, so that you always know what the total is","cn":""}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"A tally is a continuous count of something, like the number of words in a document, or the number of favors your best friend owes you. To tally is to add up, like keeping the score of a game."}]},"media":{"uk":"media/ldoce/hwd/bre/c/tally_n0205.mp3","us":"media/ldoce/hwd/ame/6/tally1.mp3"},"examples":[{"en":"Her report of what happened tallied exactly with the story of another witness.","cn":"她对于事情的叙述和另一个证人的说法完全吻合。"},{"en":"He hopes to improve on his tally of three goals in the past nine games.","cn":"他希望提高在过去九场比赛中打进三球的纪录。"}],"oxford":{"phon":"ˈtæli","pos":"noun","senses":[{"en":"a record of the number or amount of something, especially one that you can keep adding to","cn":"记录；积分表；账","ex":{"en":"He hopes to improve on his tally of three goals in the past nine games.","cn":"他希望提高在过去九场比赛中打进三球的纪录。"}},{"en":"to be the same as or to match another person’s account of something, another set of figures, etc.","cn":"（说法、数字等）与…符合（或一致）；吻合","g":"[intransitive]","ex":{"en":"Her report of what happened tallied exactly with the story of another witness.","cn":"她对于事情的叙述和另一个证人的说法完全吻合。"},"pos":"verb"},{"en":"to calculate the total number, cost, etc. of something","cn":"计算（总的数目、成本等）；合计","g":"[transitive]","ex":{"en":"When we tallied up the cost of moving, we decided against it.","cn":"计算了搬迁的成本之后，我们决定不这样做。"},"pos":"verb"}]}},"tar":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"柏油;沥青","en":"Tar is a thick black sticky substance that is used especially for making roads.","ex":{"en":"The oil has hardened to tar","cn":"油已经硬化成柏油了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(烟草中的)焦油","en":"Tar is one of the poisonous substances contained in tobacco."},{"pos":"PHRASE 短语","cn":"被当作一丘之貉;被当成一路货色","en":"If some people in a group behave badly and if people then wrongly think that all of the group is equally bad, you can say that the whole group is tarred with the same brush .","ex":{"en":"I am a football supporter and I have to often explain that I'm not one of the hooligan sort because we'll all get tarred with the same brush when there's trouble.","cn":"我是足球迷，经常要解释我不是那种足球流氓，因为一旦出事，我们就会被当成是一路货色。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a black substance, thick and sticky when hot but hard when cold, used especially for making road surfaces","cn":"柏油﹐沥青"},{"en":"a sticky substance that forms when tobacco burns, and that gets into the lungs of people who smoke 〔","cn":"烟草的〕焦油"},{"en":"to cover a surface with tar","cn":"用沥青覆盖〔表面〕"}]},"media":{"uk":"media/ldoce/hwd/bre/8/tar_n0205.mp3","us":"media/ldoce/hwd/ame/3/tar1.mp3"},"examples":[{"en":"low-tar cigarettes","cn":"尼古丁含量低的卷烟"},{"en":"a tarred road","cn":"柏油路"}],"oxford":{"phon":"tɑː(r)","pos":"noun","senses":[{"en":"a thick, sticky black liquid that becomes hard when cold. Tar is obtained from coal and is used especially in making roads.","cn":"焦油；焦油沥青；柏油"},{"en":"a substance similar to tar that is formed when tobacco is burned","cn":"（烟草点燃后产生的）焦油","ex":{"en":"low-tar cigarettes","cn":"焦油含量低的卷烟"}},{"en":"to cover something with tar","cn":"用沥青涂抹；用柏油铺","ex":{"en":"a tarred road","cn":"柏油路"},"pos":"verb"}]}},"talc":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同 talcum powder","en":"Talc is the same as talcum powder ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"talcum powder","cn":"滑石粉﹐爽身粉"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41talc.mp3","us":"media/ldoce/hwd/ame/0/talc.mp3"}},"taxidermist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"动物标本剥制师","en":"A taxidermist is a person whose job is to prepare the skins of dead animals and birds and fill them with a special material to make them look as if they are alive."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is taxidermy","cn":"动物标本剥制师"}]},"vocab":{"pos":"n","senses":[{"en":"Those creepy stuffed and mounted raccoons in your grandparents' house were crafted by a taxidermist , a person who is skilled at making lifelike displays from the bodies of dead animals."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41taxidermist.mp3","us":"media/ldoce/hwd/ame/3/taxidermist.mp3"},"oxford":{"phon":"ˈtæksɪdɜːmɪst","pos":"noun","senses":[{"en":"a person who does taxidermy as a job or interest","cn":"动物标本剥制师"}]}},"tableau":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(以静态画面再现历史场景的)舞台造型，人物造型","en":"A tableau is a scene, for example from the Bible, history, or mythology, that consists of a group of people in costumes who do not speak or move. The people are sometimes on a float in a procession.","ex":{"en":"...a nativity tableau.","cn":"基督降生的舞台场景"}},{"pos":"N-COUNT 可数名词","cn":"(尤指取材自《圣经》、历史、神话传说的)雕刻作品，绘画作品","en":"A tableau is a piece of art such as a sculpture or painting that shows a scene, especially one from the Bible, history, or mythology.","ex":{"en":"...Gaudi's luxuriant stone tableau of the Nativity on the cathedral's east face.","cn":"大教堂东面石壁上是由高迪创作的有关基督降生的华丽浮雕"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of people shown in a work of art 〔","cn":"艺术作品中的〕一组人物"},{"en":"a group of people arranged on stage like a picture","cn":"舞台造型〔由一群人在舞台上塑造的静态画面〕"},{"en":"something you see that looks like a picture, especially a group of people who are not moving or speaking","cn":"静态画面﹐静态场景〔尤指人群静止或静默的场景〕"}]},"vocab":{"pos":"n","senses":[{"en":"A tableau is a dramatic picture. If you catch a glance into the Oval Office and see top advisers speaking to each other with intensity, you behold a dramatic political tableau ."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41tableau.mp3","us":"media/ldoce/hwd/ame/e/tableau.mp3"},"examples":[{"en":"( figurative ) She stood at the door observing the peaceful domestic tableau around the fire.","cn":"她站在门口，看着炉火周围阖家祥和的景象。"},{"en":"The procession included a tableau of the Battle of Hastings.","cn":"游行队伍中包括黑斯廷斯战役的人物造型。"}],"oxford":{"phon":"ˈtæbləʊ","pos":"noun","senses":[{"en":"a scene showing, for example, events and people from history, that is presented by a group of actors who do not move or speak","cn":"舞台造型；静态画面","lab":"figurative","ex":{"en":"The procession included a tableau of the Battle of Hastings.","cn":"游行队伍中包括黑斯廷斯战役的人物造型。"}},{"en":"a work of art, especially a set of statues, showing a group of people, animals, etc.","cn":"群像（尤指雕塑）"}]}},"taupe":{"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"灰褐色","en":"Something that is taupe is a pale brownish-grey colour.","ex":{"en":"...a pale wool jacket in taupe, apricot, and cream.","cn":"灰褐色、杏黄色和乳白色相间的色彩暗淡的羊毛衫"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a brownish-grey colour","cn":"褐灰色"}]},"media":{"uk":"media/ldoce/hwd/bre/f/taupe0205.mp3","us":"media/ldoce/hwd/ame/9/laadtaupe.mp3"},"oxford":{"phon":"təʊp","pos":"adjective","senses":[{"en":"grey-brown in colour","cn":"棕灰色的；灰褐色的；暗褐色的"},{"en":"a grey-brown colour","cn":"灰褐色","pos":"noun"}]}},"taper":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)一端逐渐变细;(使)变锥形","en":"If something tapers, or if you taper it, it becomes gradually thinner at one end.","ex":{"en":"Unlike other trees, it doesn't taper very much. It stays fat all the way up","cn":"和别的树不同，它不是越往上越细，而是上下一样粗。"}},{"pos":"V-ERG 及物/不及物动词","cn":"逐渐减少;逐渐缩小","en":"If something tapers or is tapered, it gradually becomes reduced in amount, number, or size until it is greatly reduced.","ex":{"en":"There are signs that inflation is tapering","cn":"种种迹象显示，通货膨胀率在逐渐下降。"}},{"pos":"N-COUNT 可数名词","cn":"细长蜡烛;点火木片","en":"A taper is a long, thin candle or a thin wooden strip that is used for lighting fires."},{"pos":"","cn":"","en":"相关词组：taper off"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to become less","cn":""},{"en":"to become less, especially by a large amount","cn":""},{"en":"to become less - used especially in writing about business or technical subjects","cn":""}]},"vocab":{"pos":"1 v n 2 n","senses":[{"en":"To taper is to gradually grow smaller or more narrow or less intense. Taper is often used with the word \"off.\" Part of the power of the Vietnam Memorial is in how the two walls appear to \" taper off\" into infinity."}]},"media":{"uk":"media/ldoce/hwd/bre/3/taper_v0205.mp3","us":"media/ldoce/hwd/ame/e/taper1.mp3"},"examples":[{"en":"They are gradually tapering off production of the older models.","cn":"他们在逐步减少生产旧型号的产品。"},{"en":"The tail tapered to a rounded tip.","cn":"尾部越来越细，最后成了个圆尖。"}],"oxford":{"phon":"ˈteɪpə(r)","pos":"verb","senses":[{"en":"to become gradually narrower; to make something become gradually narrower","cn":"（使）逐渐变窄","ex":{"en":"The tail tapered to a rounded tip.","cn":"尾部越来越细，最后成了个圆尖。"}},{"en":"a long, thin piece of wood, paper, etc. that is used for lighting fires or lamps","cn":"（点火或灯用的）木条，纸媒","ex":{"en":"She lit the gas with a taper.","cn":"她用火柴点亮了煤气灯。"},"pos":"noun"},{"en":"a long, thin candle","cn":"细长蜡烛","pos":"noun"},{"en":"the way that something gradually decreases in size, becoming thinner","cn":"渐减；逐渐缩小（或变细）","g":"[usually singular]","pos":"noun"}]}},"taster":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"品尝师；试味员","en":"A taster is someone whose job is to taste different wines, teas, or other foods or drinks, in order to test their quality.","ex":{"en":"...a wine taster.","cn":"品酒师"}},{"pos":"N-COUNT 可数名词","cn":"试样;小样;试用品","en":"If you refer to something as a taster of something greater, or of something that will come later, you mean that it gives you an idea what that thing is like, and often makes you interested in it or want more of it.","ex":{"en":"...a taster of things to come","cn":"即将推出之物的试用品"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to test the quality of foods, teas, wines etc by tasting them","cn":"品尝家﹐试味专家"},{"en":"a small example of something that is provided so that you can see if you like it 〔","cn":"供尝试的〕小样品"}]},"media":{"uk":"media/ldoce/hwd/bre/c/taster0205.mp3","us":"media/ldoce/hwd/ame/f/taster.mp3"},"examples":[{"en":"Here’s a taster of what will be in print next month.","cn":"这儿有一份下个月刊载内容的小样。"},{"en":"a taster from her next album","cn":"她下一张专辑的小样"}],"oxford":{"phon":"ˈteɪstə(r)","pos":"noun","senses":[{"en":"a person whose job is to judge the quality of wine, tea, etc. by tasting it","cn":"试味员；品酒师；品茶员"},{"en":"a small example of something for you to try in order to see if you would like more of it","cn":"（供尝试的）小样品","lab":"informal, especially British English，，","ex":{"en":"The programme is intended as a taster for those who might like to find out more about studying computer science.","cn":"该程序旨在为那些可能想了解更多有关计算机科学学习的人提供一个尝鲜机会。"}}]}},"tapeworm":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(寄生于人、畜体内的)绦虫","en":"A tapeworm is a long, flat parasite which lives in the stomach and intestines of animals or people."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long flat worm that lives in the bowel s of humans and other animals and can make them ill","cn":"绦虫〔一种肠内寄生虫〕"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41tapeworm.mp3","us":"media/ldoce/hwd/ame/8/tapeworm.mp3"},"oxford":{"phon":"ˈteɪpwɜːm","pos":"noun","senses":[{"en":"a long, flat worm that can live in the intestines of animals and humans and can cause illness","cn":"绦虫"}]}},"tallow":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(用于制造蜡烛、肥皂的)动物油脂","en":"Tallow is hard animal fat that is used for making candles and soap."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"hard animal fat used to make candle s 〔","cn":"用于制造蜡烛的〕动物油脂"}]},"vocab":{"pos":"n","senses":[{"en":"In the old days, candles were mostly made from tallow , a form of animal fat that provided an inexpensive way for people to light their homes at night."}]},"media":{"uk":"media/ldoce/hwd/bre/b/tallow0205.mp3","us":"media/ldoce/hwd/ame/e/tallow.mp3"},"oxford":{"phon":"ˈtæləʊ","pos":"noun","senses":[{"en":"animal fat used for making candles, soap, etc.","cn":"（用以制造蜡烛、肥皂等的）动物油脂"}]}},"tailcoat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（男子在正式场合穿的）燕尾服，晚礼服","en":"A tailcoat is a man's coat which is short at the front with long pieces at the back. Tailcoats were popular in the 19th century and are now worn only for very formal occasions, such as weddings."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man’s jacket which is short at the front and divided into two long pieces at the back, worn to very formal events 〔","cn":"男子的〕晚礼服﹐燕尾服"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld45tailcoat.mp3","us":"media/ldoce/hwd/ame/b/tailcoat.mp3"},"oxford":{"phon":"ˈteɪlkəʊt","pos":"noun","senses":[{"en":"a long jacket divided at the back below the waist into two pieces that become narrower at the bottom, worn by men at very formal events","cn":"燕尾服；男子晚礼服"}]}},"tangled":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"things such as papers, clothes, or objects that are mixed up are put together untidily when they do not belong together, or are in the wrong order","cn":""},{"en":"things such as papers, books, clothes etc that are jumbled are mixed together very untidily, especially in a pile, so that it is difficult to find anything","cn":""},{"en":"hair, grass, string etc that is tangled is mixed up and difficult to separate","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Tangled is an adjective that describes a confused mass. You're likely to hear tangled used most often when referring to hair. If it's tangled, you can't brush or comb through it."}]},"collocations":{"phrases":["VERBS be, look | become, get","ADV. hopelessly | all My hair had got all tangled. | a bit Your hair looks a bit tangled. | up","PREP. in My legs got hopelessly tangled in the rope."]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdetangled.mp3","us":"media/ldoce/hwd/ame/8/laadtangled.mp3"},"examples":[{"en":"tangled hair/bed clothes","cn":"凌乱的头发/床上用品"},{"en":"tangled financial affairs","cn":"错综复杂的财务"}],"oxford":{"phon":"ˈtæŋɡld","pos":"adjective","senses":[{"en":"twisted together in an untidy way","cn":"缠结的；混乱的；紊乱的","ex":{"en":"tangled hair/bed clothes","cn":"凌乱的头发／床上用品"}},{"en":"complicated, and not easy to understand","cn":"复杂的；纠缠不清的","ex":{"en":"tangled financial affairs","cn":"错综复杂的财务"}}]}},"tattered":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣服、书等)破烂的，破旧的","en":"If something such as clothing or a book is tattered, it is damaged or torn, especially because it has been used a lot over a long period of time.","ex":{"en":"He fled wearing only a sarong and a tattered shirt.","cn":"他逃走时只穿着莎笼和破旧的衬衫。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"损坏严重的;一败涂地的","en":"If you describe something as tattered, you mean that it has been badly damaged or has failed completely.","ex":{"en":"But, two-and-a-half years later, things haven't quite gone to plan and Stanley's dreams of fame and fortune lie tattered and torn.","cn":"但是，两年半之后，事情并未如愿发展，斯坦利追求名利的梦想完全破灭了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"clothes, books etc that look shabby are no longer in good condition because they are old and have been used a lot","cn":""},{"en":"something such as material or cloth that is worn is thinner or weaker in particular parts as a result of being used a lot over a long time","cn":""},{"en":"clothes or books that are tattered are old and torn","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If something's tattered , it's worn ragged. You'll understand tattered if your dress has been dragging under your car for the last 100 miles. It will be a tattered mess."}]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdetattered.mp3","us":"media/ldoce/hwd/ame/0/tattered.mp3"},"examples":[{"en":"( figurative ) the hotel's tattered reputation","cn":"旅馆的败坏的名声"},{"en":"( figurative ) tattered relationships","cn":"破裂了的关系"}],"oxford":{"phon":"ˈtætəd","pos":"adjective","senses":[{"en":"old and torn; in bad condition","cn":"破烂的；破旧的；褴褛的；破裂的","lab":"figurative","ex":{"en":"tattered clothes","cn":"破旧的衣服"}}]}},"tab":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(标明相关信息的)小布条，小标签，小纸条","en":"A tab is a small piece of cloth or paper that is attached to something, usually with information about that thing written on it.","ex":{"en":"A stupid medical clerk had slipped the wrong tab on his X-ray.","cn":"一个蠢笨的医护人员一不留神在他的X光片上贴错了标签。"}},{"pos":"N-COUNT 可数名词","cn":"(商品、服务的)总价钱，账单","en":"A tab is the total cost of goods or services that you have to pay, or the bill or check for those goods or services.","ex":{"en":"At least one estimate puts the total tab at $7 million","cn":"至少有一个估价把总数定在了 700 万美元。"}},{"pos":"N-COUNT 可数名词","cn":"(易拉罐的)拉环","en":"A tab is a metal strip that you pull off the top of a can of drink in order to open it."},{"pos":"N-COUNT 可数名词","cn":"(尤指非法出售的)药片","en":"A tab is a drug, especially one that is sold illegally, which is in tablet form.","ex":{"en":"One tab of Ecstasy costs at least £15.","cn":"一粒摇头丸至少卖 15 英镑。"}},{"pos":"PHRASE 短语","cn":"密切注意，严密监视(某人的一举一动)","en":"If someone keeps tabs on you, they make sure that they always know where you are and what you are doing, often in order to control you.","ex":{"en":"It was obvious Hill had come over to keep tabs on Johnson and make sure he didn't do anything drastic.","cn":"显然，希尔是来密切监视约翰逊的，以确保他不做出什么过激举动。"}},{"pos":"PHRASE 短语","cn":"(替一群人)付账，承担费用","en":"If you pick up the tab, you pay a bill on behalf of a group of people or provide the money that is needed for something.","ex":{"en":"Pollard picked up the tab for dinner that night","cn":"那天的晚饭是波拉德掏的钱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of paper that tells you how much you must pay","cn":""},{"en":"a bill that tells you how much you must pay in a restaurant","cn":""},{"en":"a document that lists the goods that a company has sent, or the services they have provided, and tells you how much you must pay. It is often sent from one company to another company","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/tab_n0205.mp3","us":"media/ldoce/hwd/ame/a/tab.mp3"},"examples":[{"en":"Insert tab A into slot 1 (= for example to make a model, box, etc.).","cn":"将凸舌 A 插入 1 号孔（如制作模型、盒子等）。"},{"en":"The tab for the meeting could be $3 000.","cn":"这次会议的费用可能是 3 000 元。"}],"oxford":{"phon":"tæb","pos":"noun","senses":[{"en":"a small piece of paper, cloth, metal, etc. that sticks out from the edge of something, and that is used to give information about it, or to hold it, fasten it, etc.","cn":"标签；签条；突耳；凸舌","ex":{"en":"Insert tab A into slot 1 (= for example to make a model, box, etc.).","cn":"将凸舌 A 插入 1 号孔（如制作模型、盒子等）。"}},{"en":"an additional document or page that can be opened on computer software","cn":"标签页；选项卡","lab":"computing","ex":{"en":"You can easily switch between tabs.","cn":"你可以在标签页间轻松切换。"}},{"en":"a fixed position in a line of a document that you are typing that shows where a piece of text or a column of figures, etc. will begin","cn":"（打字）首行固定键位","ex":{"en":"Use the tab key to insert a tab at the beginning of the line.","cn":"使用 Tab 键在行首插入制表符。"}},{"en":"a small piece of metal with a ring attached which is pulled to open cans of food, drink, etc.","cn":"（易拉罐等的）拉环；易拉环","lab":"both North American English"},{"en":"a bill for goods you receive but pay for later, especially for food or drinks in a restaurant or bar; the price or cost of something","cn":"（待付的）账单，账款；（尤指）餐饮账单；费用","ex":{"en":"a bar tab","cn":"酒吧账单"}},{"en":"a small solid piece of an illegal drug","cn":"药片，药丸（指毒品）","lab":"informal","ex":{"en":"a tab of Ecstasy","cn":"一粒摇头丸"}},{"en":"a way of representing musical notes on paper by showing the position of the fingers on a musical instrument rather than the actual notes; an example of this","cn":"符号记谱法，奏法记谱法（标明演奏者的手指位置）","g":"[uncountable, countable]","ex":{"en":"guitar tabs","cn":"吉他奏法乐谱"}},{"en":"to say that somebody is suitable for a particular job or role or describe them in a particular way","cn":"说（某人）适合于（某工作或角色）；把（某人）视为…","lab":"especially North American English","ex":{"en":"He has been tabbed by many people as a future champion.","cn":"许多人都说他是未来的冠军。"},"pos":"verb"},{"en":"to use the tab key when you are using a keyboard","cn":"使用制表键","pos":"verb"}]}},"taunt":{"collins":{"senses":[{"pos":"VERB 动词","cn":"笑话;嘲笑;奚落;羞辱","en":"If someone taunts you, they say unkind or insulting things to you, especially about your weaknesses or failures.","ex":{"en":"A gang taunted a disabled man","cn":"一伙小混混嘲笑一位残疾人。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to laugh at someone and make jokes in order to have fun by embarrassing them, either in a friendly way or in an unkind way. In everyday English, people often say make fun of rather than tease","cn":""},{"en":"to tease someone, especially in an unkind way, by laughing at something they do and making them seem stupid","cn":""},{"en":"to tease someone in a very unpleasant way that shows you do not respect them, in order to make them angry or upset","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"A short list of people not to taunt : your big brother, cops, nightclub bouncers, dragons. Taunts are insulting comments, and, unless you are a really, really fast runner, keep them to yourself."}]},"collocations":{"phrases":["ADV. softly &lsquo;Running away?&rsquo;he taunted softly.","PREP. about Some of the girls taunted her about her weight. | with The other children taunted him with nicknames."]},"media":{"uk":"media/ldoce/hwd/bre/5/taunt_n0205.mp3","us":"media/ldoce/hwd/ame/7/taunt1.mp3"},"examples":[{"en":"Black players often had to endure racist taunts.","cn":"黑人运动员经常得忍受种族歧视性的奚落。"},{"en":"The other kids continually taunted him about his size.","cn":"其他孩子不断地耻笑他的个头儿。"}],"oxford":{"phon":"tɔːnt","pos":"verb","senses":[{"en":"to try to make somebody angry or upset by saying unkind things about them, laughing at their failures, etc.","cn":"辱骂；嘲笑；讽刺；奚落","ex":{"en":"The other kids continually taunted him about his size.","cn":"其他孩子不断地耻笑他的个头儿。"}},{"en":"an offensive or unkind remark that is intended to make somebody angry or upset","cn":"辱骂（或嘲笑、讽刺、奚落等）的言辞","ex":{"en":"Black players often had to endure racist taunts.","cn":"黑人运动员经常得忍受种族歧视性的奚落。"},"pos":"noun"}]}},"tapioca":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(木薯粉制成的)西米","en":"Tapioca is a food consisting of white grains, rather like rice, which come from the cassava plant."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"small hard white grains made from the crushed dried roots of cassava , or a dessert made from cooking this 〔","cn":"木薯粉制成的〕西米﹔西米甜点"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41tapioca.mp3","us":"media/ldoce/hwd/ame/d/tapioca.mp3"},"oxford":{"phon":"ˌtæpiˈəʊkə","pos":"noun","senses":[{"en":"hard white grains obtained from the cassava plant, often cooked with milk to make a dessert (= a sweet dish)","cn":"木薯淀粉"}]}},"taxable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(收入)应纳税的，该缴税的","en":"Taxable income is income on which you have to pay tax."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if money that you receive is taxable, you have to pay tax on it","cn":"应纳税的﹐应课税的"},{"en":"OPP non-taxable taxable income/profits/earnings etc","cn":""}]},"collocations":{"phrases":["VERBS be | become | remain | make sth","ADV. fully Where payments exceed these limits they become fully taxable."]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41taxable.mp3","us":"media/ldoce/hwd/ame/9/ld41taxable.mp3"},"examples":[{"en":"taxable income","cn":"应课税的收入"}],"oxford":{"phon":"ˈtæksəbl","pos":"adjective","senses":[{"en":"that you have to pay tax on","cn":"应纳税的；应课税的","ex":{"en":"taxable income","cn":"应课税的收入"}}]}},"tabasco":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"塔巴斯科辣酱","en":"Tabasco is a hot spicy sauce made from peppers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very spicy red sauce made from chilli peppers","cn":"辣椒仔辣椒酱"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41tabasco.mp3","us":"media/ldoce/hwd/ame/8/tabasco.mp3"},"oxford":{"phon":"təˈbæskəʊ","pos":"noun","senses":[{"en":"a red spicy sauce made from peppers","cn":"塔巴斯科辣椒酱"}]}},"tavern":{"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"酒吧;酒馆","en":"A tavern is a bar or pub."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place where people go to buy and drink alcoholic drinks","cn":""},{"en":"a building in Britain where alcohol can be bought and drunk, and where meals are often served","cn":""},{"en":"a pub","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A tavern is a pub or a bar, often one that rents upstairs rooms to travelers."}]},"media":{"uk":"media/ldoce/hwd/bre/a/tavern0205.mp3","us":"media/ldoce/hwd/ame/c/tavern.mp3"},"examples":[{"en":"Murphy’s Tavern","cn":"墨菲酒馆"}],"oxford":{"phon":"ˈtævən","pos":"noun","senses":[{"en":"a pub or an inn","cn":"酒馆；小旅店；客栈","ex":{"en":"It is said he was killed in a tavern brawl.","cn":"据说他死于酒馆的一次斗殴。"}}]}},"tariff":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(政府对进口商品征收的)关税","en":"A tariff is a tax that a government collects on goods coming into a country.","ex":{"en":"America wants to eliminate tariffs on items such as electronics.","cn":"美国打算取消电子产品等的关税。"}},{"pos":"N-COUNT 可数名词","cn":"(公共服务的)收费，费用;(旅馆的)住宿费，服务费","en":"A tariff is the rate at which you are charged for public services such as gas and electricity, or for accommodation and services in a hotel.","ex":{"en":"The daily tariff includes accommodation and unlimited use of the pool and gymnasium.","cn":"日常费用包括住宿以及游泳池和健身房的不限时使用。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"money that you must pay to the government, especially from the money you earn, or as an additional payment when you buy something","cn":""},{"en":"a tax you pay on something you buy","cn":""},{"en":"a tax on goods coming into a country or going out of a country, especially to protect a country’s industry from cheap goods from other countries","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A tariff is a kind of tax on goods a country imports or exports. If you want to buy a European-made car in the U.S., the price will include tariffs the government adds to the price of imported vehicles."}]},"collocations":{"phrases":["ADJ. high, low | preferential, protective, punitive British industry was sheltered from foreign competition by protective tariffs. | externa","QUANT. level a 40% level of tariffs on imports","VERB + TARIFF fix, set The agreement fixed tariffs for foreign goods coming into Japan at 5%. | impose, introduce, levy The US could impose ","TARIFF + NOUN reduction, reform | structure, system | level, rate | barrier the aim of removing all tariff barriers by the year 2003","PREP. ~ on They set a tariff of 36% on British wool cloth.","PHRASES a reduction in tariff/tariffs"]},"media":{"uk":"media/ldoce/hwd/bre/f/tariff0205.mp3","us":"media/ldoce/hwd/ame/c/tariff.mp3"},"examples":[{"en":"The government may impose tariffs on imports.","cn":"政府可能要对进口货物征收关税。"}],"oxford":{"phon":"ˈtærɪf","pos":"noun","senses":[{"en":"a tax that is paid on goods coming into or going out of a country","cn":"关税","lab":"US English","ex":{"en":"A general tariff was imposed on foreign imports.","cn":"国外进口货物当时按普通税率征税。"}},{"en":"a list of fixed prices that are charged by a hotel or restaurant for rooms, meals, etc., or by a company for a particular service","cn":"（旅馆、饭店或服务公司的）价目表，收费表","ex":{"en":"mobile-phone tariffs","cn":"手机话费单"}},{"en":"a level of punishment for somebody who has been found guilty of a crime","cn":"量刑标准","lab":"British English, law，，"}]}},"tachograph":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(卡车、长途汽车等的)速度里程仪","en":"A tachograph is a device that is put in vehicles such as lorries and coaches in order to record information such as how fast the vehicle goes, how far it travels, and the number of breaks the driver takes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment for recording the speed of a vehicle, the distance it has travelled etc","cn":"行驶记录表﹔速度记录仪"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41tachograph.mp3","us":"media/ldoce/hwd/ame/e/ld41tachograph.mp3"},"oxford":{"phon":"ˈtækəɡrɑːf","pos":"noun","senses":[{"en":"a device that is used in vehicles such as large lorries and some types of buses to measure their speed, how far they have travelled and when the driver has stopped to rest","cn":"（机动车的）行驶记录表"}]}},"tailgate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(卡车、小轿车后面的)后背门，尾门，车斗门","en":"A tailgate is a door at the back of a truck or car, that is hinged at the bottom so that it opens downwards.","ex":{"en":"He let down the tailgate so the dog could jump out.","cn":"他放下后背门，好让狗跳出来。"}},{"pos":"VERB 动词","cn":"紧随…行驶","en":"If you tailgate someone, you drive very closely behind them.","ex":{"en":"Perhaps the fact that the car was tailgating him made him accelerate","cn":"或许是因为那辆汽车跟得太紧，他才加速的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a door at the back of a truck or car that opens out and down 〔","cn":"汽车后部的〕后背门﹐尾门"},{"en":"a tailgate party","cn":"车尾大聚餐"},{"en":"to drive too closely to the vehicle in front of you","cn":"紧随〔前车〕行驶﹐紧跟…行驶"}]},"media":{"uk":"media/ldoce/hwd/bre/b/tailgate_n0205.mp3","us":"media/ldoce/hwd/ame/8/tailgate1.mp3"},"oxford":{"phon":"ˈteɪlɡeɪt","pos":"noun","senses":[{"en":"a door at the back of a lorry that opens downwards and that you can open or remove when you are loading or unloading the vehicle","cn":"（卡车的）后拦板，后挡板"},{"en":"the door that opens upwards at the back of a car (called a hatchback) that has three or five doors","cn":"（三门或五门轿车的）尾门，舱盖式后背门"},{"en":"to drive too closely behind another vehicle","cn":"紧跟（另一车辆）行驶","g":"[intransitive, transitive]","lab":"informal","pos":"verb"},{"en":"to eat food and drinks outdoors, served from the tailgate of a car","cn":"旅行野餐（打开轿车舱盖式后背门就餐）","g":"[intransitive]","lab":"North American English","pos":"verb"}]}},"takeaway":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"外卖店;外卖餐馆","en":"A takeaway is a shop or restaurant which sells hot cooked food that you eat somewhere else."},{"pos":"N-COUNT 可数名词","cn":"(商店、餐馆的)外卖食品","en":"A takeaway is hot cooked food that you buy from a shop or restaurant and eat somewhere else.","ex":{"en":"...a Chinese takeaway.","cn":"外卖中餐"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a meal that you buy from a restaurant and then eat at home","cn":""},{"en":"food or drink to take away or to go is intended to be taken away from the restaurant where you have bought it so that you can eat it somewhere else","cn":""},{"en":"a meal that you buy at a shop or restaurant to eat at home 〔","cn":"商店或餐馆的〕外卖食品"}]},"media":{"img":["media/ldoce/img/takeaway.jpg"],"uk":"media/ldoce/hwd/bre/5/takeaway0205.mp3","us":"media/ldoce/hwd/ame/8/ld41takeaway.mp3"},"examples":[{"en":"Let's have a takeaway tonight.","cn":"咱们今晚吃一顿外卖的饭菜吧。"},{"en":"Let’s have a takeaway tonight.","cn":"我们今晚叫外卖吧。"}],"oxford":{"phon":"ˈteɪkəweɪ","pos":"noun","senses":[{"en":"a restaurant that cooks and sells food that you take away and eat somewhere else","cn":"外卖餐馆","lab":"British English","ex":{"en":"We can get something to eat from the Chinese takeaway.","cn":"我们可以从中国外卖店买点东西吃。"}},{"en":"a meal that you buy at this type of restaurant","cn":"外卖的饭菜；外卖食物","lab":"British English","ex":{"en":"Let's have a takeaway tonight.","cn":"咱们今晚吃一顿外卖的饭菜吧。"}},{"en":"an important fact, point or idea to be remembered from a talk, meeting or event","cn":"外卖：在谈话，会议或活动中要记住的重要事实，观点或想法","ex":{"en":"The key takeaways from the presentation are: 1. …","cn":"演讲的主要要点是： 1. ..."}}]}},"tampon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"卫生棉条;月经棉塞","en":"A tampon is a tube made of cotton wool that a woman puts inside her vagina in order to absorb blood during menstruation."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tube-shaped mass of cotton or similar material that a woman puts inside her vagina during her period (= monthly flow of blood ) 〔","cn":"妇女用的〕月经棉塞﹐卫生棉条"}]},"media":{"uk":"media/ldoce/hwd/bre/a/tampon0205.mp3","us":"media/ldoce/hwd/ame/f/tampon.mp3"},"oxford":{"phon":"ˈtæmpɒn","pos":"noun","senses":[{"en":"a piece of cotton material with a special shape that a woman puts inside her vagina to hold blood during her period","cn":"（女子用的）月经棉条，卫生栓"}]}},"tactless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(言行)未经考虑的，冒失的，没分寸的","en":"If you describe someone as tactless, you think what they say or do is likely to offend other people.","ex":{"en":"Throughout his school life Darius was tactless and egocentric","cn":"上学期间，达赖厄斯粗鲁冒失，而且总以自我为中心。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not paying enough attention to what you are doing, so that you make mistakes, damage things etc","cn":""},{"en":"often dropping or breaking things because you move around in a careless way","cn":""},{"en":"careless and lazy in the way you do your work or in your behaviour generally","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be tactless is to either be rude (without manners) or inept (without finesse). Either way, it's awkward."}]},"media":{"uk":"media/ldoce/hwd/bre/2/tactless0205.mp3","us":"media/ldoce/hwd/ame/9/laadtactless.mp3"},"examples":[{"en":"It was tactless of you to comment on his hair!","cn":"你竟对他的头发说三道四，真是缺心眼！"},{"en":"a tactless remark","cn":"不得体的话"}],"oxford":{"phon":"ˈtæktləs","pos":"adjective","senses":[{"en":"saying or doing things that are likely to annoy or to upset other people","cn":"言行不得体的；得罪人的；不圆通的；没策略的","ex":{"en":"a tactless remark","cn":"不得体的话"}}]}},"taffy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"太妃糖;乳脂糖","en":"Taffy is a sticky sweet that you chew. It is made by boiling sugar and butter together with water."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of soft chewy sweet","cn":"太妃糖﹐乳脂糖"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41taffy2.mp3","us":"media/ldoce/hwd/ame/7/taffy.mp3"},"oxford":{"phon":"ˈtæfi","pos":"noun","senses":[{"en":"a type of soft sweet made of brown sugar boiled until it is very thick and given different shapes and colours","cn":"太妃糖；乳脂糖"},{"en":"an offensive word for a person from Wales","cn":"威尔士人"}]}},"tanned":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a darker skin colour because you have been in the sun 〔","cn":"皮肤〕被晒黑的"}]},"collocations":{"phrases":["VERBS be, look | become, get","ADV. deeply, very His blue eyes glittered in his deeply tanned face. | lightly, slightly | healthily"]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdetanned.mp3","us":"media/ldoce/hwd/ame/f/laadtanned.mp3"},"examples":[{"en":"He had a tough tanned face and clear eyes.","cn":"他粗犷的脸庞晒得黝黑﹐双眸明亮有神。"}],"oxford":{"phon":"tænd","pos":"adjective","senses":[{"en":"having a brown skin colour as a result of being in the sun","cn":"皮肤晒成褐色的；晒黑的","ex":{"en":"He had a tanned face and clear eyes.","cn":"他有着晒黑的脸和清澈的眼睛。"}}]}},"takeover":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"收购;接管;接收","en":"A takeover is the act of gaining control of a company by buying more of its shares than anyone else.","ex":{"en":"...the government's takeover of the Bank of New England Corporation.","cn":"政府对新英格兰银行的接管"}},{"pos":"N-COUNT 可数名词","cn":"(武装)占领，接管，控制","en":"A takeover is the act of taking control of a country, political party, or movement by force.","ex":{"en":"There's been a military takeover of some kind.","cn":"发生了类似军事接管的事件。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt by the army to take control of the government","cn":""},{"en":"a successful attempt by the army to take control of their own country by removing the legal government","cn":""},{"en":"when one company takes control of another by buying more than half its share s","cn":"收购"}]},"collocations":{"phrases":["ADJ. attempted, proposed | hostile | agreed | company | communist, military","TAKEOVER + NOUN attempt, bid a hostile takeover bid | offer | battle The consortium won a fierce takeover battle for the engineering group."]},"media":{"uk":"media/ldoce/hwd/bre/6/takeover0205.mp3","us":"media/ldoce/hwd/ame/8/takeover.mp3"},"examples":[{"en":"a takeover bid for the company","cn":"收购这家公司的出价"},{"en":"Thornbury has announced a takeover bid of a regional TV company.","cn":"索恩伯里已宣布将出价收购一家地方电视公司。"}],"oxford":{"phon":"ˈteɪkəʊvə(r)","pos":"noun","senses":[{"en":"an act of taking control of a company by buying most of its shares","cn":"收购；接收；接管","lab":"North American English","ex":{"en":"a takeover bid for the company","cn":"收购这家公司的出价"}},{"en":"an act of taking control of a country, an area or a political organization by force","cn":"（对国家、地区、政治组织等的）强行接管，控制","ex":{"en":"attempts to prevent the takeover of the Republic by the military","cn":"试图阻止军队接管共和国"}}]}},"tassel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(衣服、灯罩上的)穗，缨，流苏","en":"Tassels are bunches of short pieces of wool or other material tied together at one end and attached as decorations to something such as a piece of clothing or a lampshade."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"threads tied together at one end and hung as a decoration on clothes, curtains etc 〔","cn":"衣服﹑窗帘等上的〕流苏﹐穗﹐缨"}]},"media":{"uk":"media/ldoce/hwd/bre/1/tassel0205.mp3","us":"media/ldoce/hwd/ame/5/tassel.mp3","img":["media/pic/tassel.jpg","media/thumb/tassel.jpg"]},"oxford":{"phon":"ˈtæsl","pos":"noun","senses":[{"en":"a bunch of threads that are tied together at one end and hang from cushions, curtains, clothes, etc. as a decoration","cn":"（靠垫、窗帘、衣服等的）流苏，穗，缨"}]}},"tautological":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"同义反复的;赘述的","en":"A tautological statement involves tautology."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement in which you say the same thing twice using different words in a way which is not necessary, for example, ‘He sat alone by himself.’","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something tautological is redundant and circular, especially when talking about logic. \"Logical things are logical\" is a tautological sentence."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41tautology.mp3","us":"media/ldoce/hwd/ame/4/tautology.mp3"},"oxford":{"phon":"ˌtɔːtəˈlɒdʒɪkl","pos":"adjective","senses":[{"en":"saying the same thing twice in different words, when this is unnecessary, for example ‘They spoke in turn, one after the other.’","cn":"同义反复；赘述"}]}},"tarnish":{"collins":{"senses":[{"pos":"VERB 动词","cn":"玷污，败坏，损害(名誉或形象)","en":"If you say that something tarnishes someone's reputation or image, you mean that it causes people to have a worse opinion of them than they would otherwise have had.","ex":{"en":"The affair could tarnish the reputation of the prime minister","cn":"这一事件可能有损首相的名誉。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)有污迹;(使)失去光泽;(使)变暗淡","en":"If a metal tarnishes or if something tarnishes it, it becomes stained and loses its brightness.","ex":{"en":"It never rusts or tarnishes","cn":"它从不生锈，也不会失去光泽。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"锈斑;污点","en":"Tarnish is a substance which forms of the surface of some metals and which stains them or causes them to lose their brightness.","ex":{"en":"The tarnish lay thick on the inside of the ring.","cn":"戒指内侧有一层厚厚的锈斑。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if an event or fact tarnishes someone’s reputation , record, image etc, it makes it worse","cn":"玷污﹐败坏﹐损害〔名誉﹑形象等〕"},{"en":"if metals such as silver, copper , or brass tarnish, or if something tarnishes them, they become dull and lose their colour （","cn":"使）〔银﹑铜等金属〕失去光泽﹐变暗淡"},{"en":"dullness of colour, or loss of brightness","cn":"颜色晦暗﹔暗淡无光"}]},"vocab":{"pos":"v n","senses":[{"en":"To tarnish is to become dull or discolored. Silver tends to tarnish easily, which is why your mother is always having you polish the family silver."}]},"collocations":{"phrases":["ADV. badly The mirror had tarnished quite badly. 2 spoil sth","ADV. severely their severely tarnished reputation"]},"media":{"uk":"media/ldoce/hwd/bre/8/tarnish_v0205.mp3","us":"media/ldoce/hwd/ame/0/tarnish1.mp3"},"examples":[{"en":"He hopes to improve the newspaper's somewhat tarnished public image.","cn":"他希望改善报纸略有受损的公众形象。"},{"en":"The mirrors had tarnished with age.","cn":"这些镜子因年深日久而照影不清楚。"}],"oxford":{"phon":"ˈtɑːnɪʃ","pos":"verb","senses":[{"en":"if metal tarnishes or something tarnishes it, it no longer looks bright and shiny","cn":"（使）失去光泽，暗淡","g":"[intransitive, transitive]","ex":{"en":"The mirrors had tarnished with age.","cn":"这些镜子因年深日久而照影不清楚。"}},{"en":"to damage the good opinion people have of somebody/something","cn":"玷污，败坏，损坏（名声等）","g":"[transitive, often passive]","ex":{"en":"Reputations can be easily tarnished.","cn":"名声易损。"}},{"en":"a thin layer on the surface of a metal that makes it look darker and less bright","cn":"（金属表面上的）暗锈","pos":"noun"}]}},"tartan":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(苏格兰)花格图案，花格织物，格呢","en":"Tartan is a design for cloth traditionally associated with Scotland, and which has a number of distinctive types. The design is made up of lines of different widths and colours crossing each other at right angles. Tartan is also used to refer to cloth which has this pattern.","ex":{"en":"The corridors are carpeted in tartan.","cn":"走廊里铺的是花格地毯。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a traditional Scottish pattern of coloured squares and crossed lines, or cloth, especially wool cloth, with this pattern 〔","cn":"苏格兰〕花格图案﹐格子花呢"}]},"media":{"uk":"media/ldoce/hwd/bre/5/tartan0205.mp3","us":"media/ldoce/hwd/ame/4/tartan.mp3","img":["media/thumb/tartan.jpg"]},"examples":[{"en":"the MacLeod tartan","cn":"麦克劳德花格图案"},{"en":"a tartan rug","cn":"花格小地毯"}],"oxford":{"phon":"ˈtɑːtn","pos":"noun","senses":[{"en":"a pattern of squares and lines of different colours and widths that cross each other at an angle of 90°, used especially on cloth, and originally from Scotland","cn":"（尤指源自苏格兰织物的）花格图案，方格花纹","g":"[uncountable, countable]","ex":{"en":"a tartan rug","cn":"花格小地毯"}},{"en":"a tartan pattern connected with a particular group of families (= a clan) in Scotland","cn":"（与苏格兰某家族有关的）花格图案，方格花纹","g":"[countable]","ex":{"en":"the MacLeod tartan","cn":"麦克劳德花格图案"}},{"en":"cloth, especially made of wool, that has a tartan pattern","cn":"花格布料；（尤指）苏格兰格呢","g":"[uncountable]"}]}},"taxicab":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 taxi","en":"A taxicab is the same as a taxi ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a taxi","cn":"出租车﹐的士"}]},"media":{"uk":"media/ldoce/hwd/bre/6/taxicab0205.mp3","us":"media/ldoce/hwd/ame/5/laadtaxicab.mp3"}},"taxidermy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"动物标本剥制术","en":"Taxidermy is the craft of preparing the skins of dead animals and birds and filling them with a special material to make them look as if they are alive."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the art of filling the skins of dead animals, birds, or fish with a special material so that they look as though they are alive","cn":"动物标本剥制术"}]},"vocab":{"pos":"n","senses":[{"en":"If you're a fan of taxidermy , you like real stuffed animals — animal skins specially prepared and mounted to look like they're alive."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41taxidermy.mp3","us":"media/ldoce/hwd/ame/3/taxidermy.mp3"},"oxford":{"phon":"ˈtæksɪdɜːmi","pos":"noun","senses":[{"en":"the art of stuffing dead animals, birds and fish with a special material so that they look like living ones and can be displayed","cn":"动物标本剥制术（将动物充填以支撑物，以表现出其生前外形）"}]}},"tawny":{"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"黄褐色","en":"Tawny hair, fur, or skin is a pale brown colour.","ex":{"en":"She had tawny hair.","cn":"她有一头黄褐色的头发。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"brownish-yellow in colour","cn":"黄褐色的"}]},"vocab":{"pos":"adj","senses":[{"en":"A color adjective, tawny describes something that is a mix of yellow, orange, and brown colors. A lion has a beautiful tawny coat."}]},"media":{"uk":"media/ldoce/hwd/bre/9/tawny0205.mp3","us":"media/ldoce/hwd/ame/d/tawny.mp3"},"examples":[{"en":"the lion's tawny mane","cn":"狮子的黄褐色鬃毛"},{"en":"a lion’s tawny fur","cn":"狮子的黄褐色毛皮"}],"oxford":{"phon":"ˈtɔːni","pos":"adjective","senses":[{"en":"brown-yellow in colour","cn":"黄褐色的；茶色的","ex":{"en":"the lion’s tawny mane","cn":"狮子的黄褐色鬃毛"}}]}},"tautology":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"同义反复;赘述","en":"Tautology is the use of different words to say the same thing twice in the same statement. 'The money should be adequate enough' is an example of tautology."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement in which you say the same thing twice using different words in a way which is not necessary, for example, ‘He sat alone by himself.’","cn":"同义反复﹐赘述"}]},"vocab":{"pos":"n","senses":[{"en":"Tautology is useless restatement, or saying the same thing twice using different words. “Speedy sprint\" is a tautology because sprint already means \"speedy running.\""}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41tautology.mp3","us":"media/ldoce/hwd/ame/4/tautology.mp3"},"oxford":{"phon":"tɔːˈtɒlədʒi","pos":"noun","senses":[{"en":"a statement in which you say the same thing twice in different words, when this is unnecessary, for example ‘They spoke in turn, one after the other.’","cn":"同义反复；赘述"}]}},"taxonomy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(动植物等的)分类法，分类学","en":"Taxonomy is the process of naming and classifying things such as animals and plants into groups within a larger system, according to their similarities and differences."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process or a system of organizing things into different groups that show their natural relationships, especially plants or animals 〔","cn":"动植物等的〕分类学"}]},"vocab":{"pos":"n","senses":[{"en":"Taxonomy is all about organizing and classifying. To make it sound more scientific, you could refer to your project of reorganizing your spice rack according to smell as a taxonomy of spices."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41taxonomy.mp3","us":"media/ldoce/hwd/ame/e/taxonomy.mp3"},"examples":[{"en":"plant taxonomy","cn":"植物分类学"}],"oxford":{"phon":"tækˈsɒnəmi","pos":"noun","senses":[{"en":"the scientific process of classifying things (= arranging them into groups)","cn":"分类学","g":"[uncountable]","ex":{"en":"plant taxonomy","cn":"植物分类学"}},{"en":"a particular system of classifying things","cn":"分类法；分类系统","g":"[countable]"}]}},"tasteful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"高雅的;雅致的;有品位的","en":"If you say that something is tasteful, you consider it to be attractive, elegant, and in good taste.","ex":{"en":"The decor is tasteful and restrained.","cn":"装饰风格素雅简约。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"made or chosen with good taste","cn":""},{"en":"to be attractive and suitable in a way that shows good taste","cn":""},{"en":"made, decorated, or chosen with good taste","cn":"有品位的﹐有鉴赏力的﹐趣味高雅的"}]},"collocations":{"phrases":["VERBS be Most of the furniture was quite tasteful.","ADV. very | impeccably | quite"]},"media":{"uk":"media/ldoce/hwd/bre/4/tasteful0205.mp3","us":"media/ldoce/hwd/ame/7/tasteful.mp3"},"examples":[{"en":"The bedroom was tastefully furnished.","cn":"这卧室布置得很雅致。"},{"en":"tasteful furnishings","cn":"品味高雅的家具陈设"}],"oxford":{"phon":"ˈteɪstfl","pos":"adjective","senses":[{"en":"attractive and of good quality and showing that the person who chose them can recognize good things","cn":"高雅的；雅致的；优美的","ex":{"en":"tasteful furniture/ornaments/decor","cn":"高雅的家具/装饰品/装饰"}}]}},"tangerine":{"collins":{"senses":[{"pos":"","cn":"橘子;柑橘","en":"tangerines A tangerine is a small sweet orange."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small sweet fruit like an orange with a skin that comes off easily","cn":"橘子"},{"en":"a bright orange colour","cn":"橘色"}]},"media":{"uk":"media/ldoce/hwd/bre/a/tangerine0205.mp3","us":"media/ldoce/hwd/ame/c/ld45tangerine.mp3"},"examples":[{"en":"a tangerine evening gown","cn":"橘红色的女晚礼服"}],"oxford":{"phon":"ˌtændʒəˈriːn","pos":"adjective","senses":[{"en":"deep orange-yellow in colour","cn":"橘黄色；橘红色","ex":{"en":"a tangerine evening gown","cn":"橘红色的女晚礼服"}},{"en":"a type of small sweet orange with loose skin that comes off easily","cn":"橘","g":"[countable]","pos":"noun"},{"en":"a deep orange-yellow colour","cn":"橘黄色；橘红色","g":"[uncountable]","pos":"noun"}]}},"tactician":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"战术家;谋略家","en":"If you say that someone is a good tactician, you mean that they are skilful at choosing the best methods in order to achieve what they want.","ex":{"en":"He is an extremely astute political tactician","cn":"他是个极其精明的政治谋略家。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is very good at tactic s","cn":"战术家﹔谋略家"}]},"vocab":{"pos":"n","senses":[{"en":"A tactician is someone good at planning tactics: the specific means of accomplishing goals."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41tactician.mp3","us":"media/ldoce/hwd/ame/4/tactician.mp3"},"oxford":{"phon":"tækˈtɪʃn","pos":"noun","senses":[{"en":"a person who is very clever at planning the best way to achieve something","cn":"有策略的人；手段高明的人","ex":{"en":"a fine political tactician","cn":"优秀的政治战术家"}}]}},"tardy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"晚的;迟到的","en":"If you describe something or someone as tardy, you think that they are later than they should be or later than expected.","ex":{"en":"He wept for the loss of his mother and his tardy recognition of her affection","cn":"他痛哭流涕，不仅因为失去了母亲，还因为这么晚才认识到了妈妈对他的爱。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"拖沓的;反应迟缓的","en":"If you describe someone or something as tardy, you are criticizing them because they are slow to act.","ex":{"en":"...companies who are tardy in paying bills","cn":"迟迟不付账的公司"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"arriving or happening after the time that was expected or arranged","cn":""},{"en":"not arriving or doing something at the time that was expected or arranged","cn":""},{"en":"not done or happening by the expected time – used especially about payments that are late or library books that should have been returned","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When you're tardy, you're late. If you've ever been late for school, you know about tardy, and you may have a stash of notes your teacher has sent home to your parents, informing them of your tardiness."}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41tardy.mp3","us":"media/ldoce/hwd/ame/b/tardy.mp3"},"examples":[{"en":"The law is often tardy in reacting to changing attitudes.","cn":"法律对变化中的观念常常反应迟缓。"},{"en":"people who are tardy in paying their bills","cn":"拖延付账的人"}],"oxford":{"phon":"ˈtɑːdi","pos":"adjective","senses":[{"en":"slow to act, move or happen; late in happening or arriving","cn":"行动缓慢的；拖拉的；迟缓的；迟到的","lab":"North American English","ex":{"en":"The law is often tardy in reacting to changing attitudes.","cn":"法律对变化中的观念常常反应迟缓。"}}]}},"tactical":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(行动、计划)战术上的，策略性的","en":"You use tactical to describe an action or plan which is intended to help someone achieve what they want in a particular situation.","ex":{"en":"It's not yet clear whether the Prime Minister's resignation offer is a serious one, or whether it's simply a tactical move","cn":"现在还不清楚首相提出辞职是认真的，还是仅仅作为一种策略。"}},{"pos":"ADJ 形容词","cn":"(武器、军队)战术的，作战的","en":"Tactical weapons or forces are those which a military leader can decide for themselves to use in a battle, rather than waiting for a decision by a political leader.","ex":{"en":"They have removed all tactical nuclear missiles that could strike Europe.","cn":"他们已经拆除所有能够袭击欧洲的战术核导弹。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to what you do to achieve what you want, especially as part of a game or large plan","cn":"策略性的﹔谋略性的"},{"en":"a missile that is sent a short distance in military battle","cn":"战术性武器/导弹"},{"en":"relating to the way military forces are arranged in a battle","cn":"战术上的"}]},"vocab":{"pos":"adj","senses":[{"en":"A tactical move on the military's part is one that is carefully planned and often small in scale, but important in getting control of an area."}]},"media":{"uk":"media/ldoce/hwd/bre/9/tactical0205.mp3","us":"media/ldoce/hwd/ame/0/ld44tactical.mp3"},"examples":[{"en":"Telling your boss you were looking for a new job was a tactical error (= it was the wrong thing to do at that time).","cn":"你把正在另找工作的事告诉了老板，是个策略上的错误。"},{"en":"He was given tactical command of the operation.","cn":"他被授以这次军事行动的作战指挥权。"}],"oxford":{"phon":"ˈtæktɪkl","pos":"adjective","senses":[{"en":"connected with the particular method you use to achieve something","cn":"战术上的；策略上的","g":"[usually before noun]","ex":{"en":"tactical planning","cn":"对策谋划"}},{"en":"carefully planned in order to achieve a particular aim","cn":"有谋略的；手段高明的；善于谋划的","g":"[usually before noun]","ex":{"en":"a tactical decision","cn":"高明的决策"}},{"en":"used or having an effect over short distances or for a short time","cn":"战术的；短程的","g":"[only before noun]","ex":{"en":"tactical weapons/missiles","cn":"战术武器／导弹"}},{"en":"connected with military tactics","cn":"作战的","g":"[only before noun]","ex":{"en":"He was given tactical command of the operation.","cn":"他被授以这次军事行动的作战指挥权。"}}]}},"tattoo":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"文身;刺青","en":"A tattoo is a design that is drawn on someone's skin using needles to make little holes and filling them with coloured dye."},{"pos":"VERB 动词","cn":"给…文身;在…身上刺花纹","en":"If someone tattoos you, they give you a tattoo.","ex":{"en":"In the old days, they would paint and tattoo their bodies for ceremonies","cn":"过去，他们举行各种仪式前会在身上进行彩绘、文身。"}},{"pos":"N-COUNT 可数名词","cn":"(军队的)表演操","en":"A military tattoo is a public display of exercises and music given by members of the armed forces."},{"pos":"N-COUNT 可数名词","cn":"快速的击打;不停的敲击","en":"If you beat a tattoo, you hit something quickly and repeatedly."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a picture or writing that is permanently marked on your skin using a needle and ink","cn":"文身"},{"en":"an outdoor military show with music, usually at night 〔","cn":"常在夜间举行的﹑有音乐伴奏的〕军操表演"},{"en":"a fast continuous beating of a drum, or a sound like this","cn":"急促而连续的击鼓[敲击声]"}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A tattoo is a permanent design made on skin with a needle and ink. If you want a butterfly tattoo but you're scared of needles, you might settle for a temporary version."}]},"collocations":{"phrases":["VERB + TATTOO do She's having a tattoo done on her leg. | have | be covered in His arms were covered in tattoos. | remove I've decided to ge","TATTOO + NOUN parlour"]},"media":{"uk":"media/ldoce/hwd/bre/f/tattoo_n0205.mp3","us":"media/ldoce/hwd/ame/3/tattoo1.mp3"},"examples":[{"en":"He had a heart tattooed on his shoulder.","cn":"他让人给他在肩膀上刺了一颗心形图案。"},{"en":"His shoulder was tattooed with a heart.","cn":"他的肩膀上刺了一颗心形图案。"}],"oxford":{"phon":"təˈtuː","pos":"noun","senses":[{"en":"a picture or design that is marked permanently on a person’s skin by making small holes in the skin with a needle and filling them with coloured ink","cn":"文身；（在皮肤上刺的）花纹","lab":"North American English also","ex":{"en":"His arms were covered in tattoos.","cn":"他的胳膊上刺满了文身。"}},{"en":"an outdoor show by members of the armed forces that includes marching, music and military exercises","cn":"野外军事表演（包括齐步前进、军乐和军事演习）","lab":"especially British English","ex":{"en":"the Edinburgh military tattoo","cn":"爱丁堡军事表演"}},{"en":"a rapid and continuous series of hits, especially on a drum as a military signal","cn":"连续急促的敲击；（尤指军事上的）回营号，击鼓号","g":"[usually singular]","ex":{"en":"The drummers beat a tattoo each morning.","cn":"鼓手们每天早上都敲鼓。"}},{"en":"to mark somebody’s skin with a tattoo","cn":"将花纹刺在…上；给…文身","ex":{"en":"He had a heart tattooed on his shoulder.","cn":"他让人给他在肩膀上刺了一颗心形图案。"},"pos":"verb"}]}},"tarmac":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(铺路面用的)柏油碎石","en":"Tarmac is a material used for making road surfaces, consisting of crushed stones mixed with tar.","ex":{"en":"...a strip of tarmac.","cn":"狭长的柏油碎石路面"}},{"pos":"N-SING 单数名词","cn":"柏油碎石地面;(尤指)停机坪","en":"The tarmac is an area with a surface made of tarmac, especially the area from which planes take off at an airport.","ex":{"en":"Standing on the tarmac were two American planes.","cn":"停机坪上停着两架美国飞机。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mixture of tar and very small stones, used for making the surface of roads Tarmac","cn":"柏油碎石"},{"en":"an area covered with tarmac outside airport buildings Tarmac","cn":"柏油碎石飞机跑道[停机坪]"},{"en":"to cover a road’s surface with tarmac","cn":"在〔路面〕上铺柏油碎石"}]},"media":{"uk":"media/ldoce/hwd/bre/f/tarmac_n0205.mp3","us":"media/ldoce/hwd/ame/d/tarmac1.mp3"},"examples":[{"en":"Three planes were standing on the tarmac, waiting to take off.","cn":"三架飞机停在跑道上，等候起飞。"},{"en":"Journalists waited on the tarmac to question him.","cn":"新闻记者们在停机坪上等候着向他提问。"}],"oxford":{"phon":"ˈtɑːmæk","pos":"verb","senses":[{"en":"to cover a surface with Tarmac™","cn":"以塔玛克柏油碎石铺筑（路面）","ex":{"en":"tarmacked roads","cn":"柏油碎石路面"}},{"en":"a black material used for making road surfaces, that consists of small stones mixed with tar","cn":"塔玛克柏油碎石（用作铺筑路面材料）","lab":"less frequent","pos":"noun"},{"en":"an area with a Tarmac surface, especially at an airport","cn":"柏油碎石路面；柏油碎石铺的停机坪（或跑道）","ex":{"en":"Three planes were standing on the tarmac, waiting to take off.","cn":"三架飞机停在跑道上，等候起飞。"},"pos":"noun"}]}},"tabernacle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(某些基督教新教教派和摩门教派的)教堂，礼拜堂","en":"A tabernacle is a church used by certain Christian Protestant groups and by Mormons.","ex":{"en":"...the vision which led Earl Paulk to create his first tabernacle in Atlanta.","cn":"促使保尔克伯爵在亚特兰大建第一座教堂的远见卓识"}},{"pos":"N-PROPER 专有名词","cn":"(存放古代犹太人圣典的)圣幕，会幕","en":"The Tabernacle was a small tent which contained the most holy writings of the ancient Jews and which they took with them when they were travelling."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a church or other building used by some Christian groups as a place of worship 〔","cn":"某些基督教派的〕教堂﹐礼拜堂"},{"en":"a box in which holy bread and wine are kept in Catholic churches 〔","cn":"天主教堂里存放圣餐饼和葡萄酒的〕圣体柜"},{"en":"the small tent in which the ancient Jews kept their most holy objects 〔","cn":"古代犹太人存放圣物的〕圣幕﹐会幕"}]},"vocab":{"pos":"n","senses":[{"en":"A tabernacle was originally a Jewish place of worship, like a moveable tent. Synagogues and temples are tabernacles . Tabernacle has now branched out and can refer to a place of worship for Christians, too."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41tabernacle.mp3","us":"media/ldoce/hwd/ame/7/tabernacle.mp3"},"examples":[{"en":"a Mormon tabernacle","cn":"摩门教教堂"}],"oxford":{"phon":"ˈtæbənækl","pos":"noun","senses":[{"en":"a small place of worship that could be moved, used by the Israelites in ancient times when they were travelling in the desert","cn":"圣所，会幕（古代犹太人在沙漠旅途中拜神用）"},{"en":"a place of worship for some groups of Christians","cn":"（某些基督教派的）礼拜堂，会堂","ex":{"en":"a Mormon tabernacle","cn":"摩门教教堂"}}]}},"taker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"接受…的人","en":"If there are no takers for something such as an investment or a challenge, nobody is willing to accept it.","ex":{"en":"Over 100 buyers or investors were approached, but there were no takers","cn":"已接触过 100 多个买主或投资人，不过没人愿意接受。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if there are no takers for something, no one accepts or wants what is being offered","cn":"没有/有很少/有不多的接受者"},{"en":"someone who accepts support and help from other people, but who is not willing to give them support or help","cn":"只接受不给予的人"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41taker.mp3","us":"media/ldoce/hwd/ame/6/taker.mp3"},"examples":[{"en":"They won't find many takers for the house at that price.","cn":"以这样的要价，他们不会为房子找到多少承让人的。"},{"en":"It is better to be a giver than a taker.","cn":"施比受有福。"}],"oxford":{"phon":"ˈteɪkə(r)","pos":"noun","senses":[{"en":"a person who is willing to accept something that is being offered","cn":"接受者；收受人","g":"[usually plural]","ex":{"en":"They won't find many takers for the house at that price.","cn":"以这样的要价，他们不会为房子找到多少承让人的。"}},{"en":"a person who takes something","cn":"接受者","ex":{"en":"drug takers","cn":"吸毒者"}}]}}});
